CREATE OR REPLACE FUNCTION public.aka_agent_admin_docs(p_staff_id bigint, p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_doc public.auto_admin_api_docs%ROWTYPE; v_id bigint := (p_data->>'id')::bigint;
BEGIN
  PERFORM public.aka_agent_admin_assert_access(p_staff_id,p_username,p_password);
  IF p_action = 'list' THEN
    RETURN (SELECT coalesce(jsonb_agg(to_jsonb(d) || jsonb_build_object('version',md5(to_jsonb(d)::text)) ORDER BY d.sort_order,d.id),'[]') FROM public.auto_admin_api_docs d);
  END IF;
  IF p_action NOT IN ('get','save','delete') OR p_action IS NULL THEN RAISE EXCEPTION 'admin_invalid_action'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT * INTO v_doc FROM public.auto_admin_api_docs WHERE id=v_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'admin_not_found'; END IF;
    IF p_action <> 'get' AND (p_data->>'expected_version') IS DISTINCT FROM md5(to_jsonb(v_doc)::text) THEN RAISE EXCEPTION 'admin_conflict'; END IF;
  ELSIF p_action <> 'save' THEN RAISE EXCEPTION 'admin_not_found'; END IF;
  IF p_action = 'delete' THEN
    DELETE FROM public.auto_admin_api_docs WHERE id=v_id;
    RETURN '{}'::jsonb;
  ELSIF p_action = 'save' THEN
    IF v_id IS NULL THEN
      INSERT INTO public.auto_admin_api_docs(name,url,description,sort_order,is_active)
      VALUES (btrim(p_data->>'name'),btrim(p_data->>'url'),p_data->>'description',coalesce((p_data->>'sort_order')::integer,0),coalesce((p_data->>'is_active')::boolean,true)) RETURNING * INTO v_doc;
    ELSE
      UPDATE public.auto_admin_api_docs SET name=btrim(p_data->>'name'),url=btrim(p_data->>'url'),description=p_data->>'description',
        sort_order=(p_data->>'sort_order')::integer,is_active=(p_data->>'is_active')::boolean,updated_at=clock_timestamp()
      WHERE id=v_id RETURNING * INTO v_doc;
    END IF;
  END IF;
  RETURN to_jsonb(v_doc) || jsonb_build_object('version',md5(to_jsonb(v_doc)::text));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_admin_notifications(p_staff_id bigint, p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_value text; v_id bigint := (p_data->>'staff_id')::bigint; v_rows jsonb; v_setting public.auto_system_settings%ROWTYPE;
BEGIN
  PERFORM public.aka_agent_admin_assert_access(p_staff_id,p_username,p_password);
  IF p_action = 'global' THEN
    SELECT * INTO v_setting FROM public.auto_system_settings WHERE key='app.notification';
    IF NOT FOUND THEN RAISE EXCEPTION 'admin_not_found'; END IF;
    RETURN jsonb_build_object('staff_id',NULL,'username','Toàn bộ khách hàng','organization_id',NULL,'organization_name','Toàn hệ thống',
      'raw_value',coalesce(v_setting.value,''),'version',md5(coalesce(v_setting.value,'')),'is_active',v_setting.is_active);
  ELSIF p_action IN ('list','search') THEN
    SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.staff_id),'[]') INTO v_rows FROM (
      SELECT s.id AS staff_id,s.username,s.organization_id,coalesce(o.name,'') AS organization_name,
        coalesce(s.app_notification,'') AS raw_value,md5(coalesce(s.app_notification,'')) AS version,s.is_active
      FROM public.org_staff s LEFT JOIN public.org_organization o ON o.id=s.organization_id
      WHERE (p_action='list' AND nullif(btrim(s.app_notification),'') IS NOT NULL AND s.id>coalesce((p_data->>'cursor')::bigint,0))
         OR (p_action='search' AND length(btrim(coalesce(p_data->>'search','')))>=2 AND s.username ILIKE '%' || replace(replace(replace(left(p_data->>'search',100),E'\\',E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%')
      ORDER BY s.id LIMIT 101
    ) q;
    IF p_action='search' THEN RETURN (SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(v_rows) WITH ORDINALITY e(x,n) WHERE n<=100); END IF;
    RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(v_rows) WITH ORDINALITY e(x,n) WHERE n<=100),
      'next_cursor',CASE WHEN jsonb_array_length(v_rows)>100 THEN v_rows->99->>'staff_id' END);
  ELSIF p_action='save' THEN
    v_value := p_data->>'raw_value';
    IF v_value IS NULL OR length(v_value)>100000 THEN RAISE EXCEPTION 'admin_invalid_value'; END IF;
    IF v_id IS NULL THEN
      SELECT * INTO v_setting FROM public.auto_system_settings WHERE key='app.notification' FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'admin_not_found'; END IF;
      IF (p_data->>'expected_version') IS DISTINCT FROM md5(coalesce(v_setting.value,'')) THEN RAISE EXCEPTION 'admin_conflict'; END IF;
      UPDATE public.auto_system_settings SET value=v_value,updated_at=clock_timestamp() WHERE id=v_setting.id;
    ELSE
      PERFORM 1 FROM public.org_staff WHERE id=v_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'admin_not_found'; END IF;
      IF NOT EXISTS (SELECT 1 FROM public.org_staff WHERE id=v_id AND md5(coalesce(app_notification,''))=p_data->>'expected_version') THEN RAISE EXCEPTION 'admin_conflict'; END IF;
      UPDATE public.org_staff SET app_notification=v_value,updated_at=clock_timestamp() WHERE id=v_id;
    END IF;
    RETURN '{}'::jsonb;
  END IF;
  RAISE EXCEPTION 'admin_invalid_action';
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_admin_settings(p_staff_id bigint, p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
 SET statement_timeout TO '8s'
 SET lock_timeout TO '3s'
AS $function$
DECLARE v_setting public.auto_system_settings%ROWTYPE; v_version text;
BEGIN
  PERFORM public.aka_agent_admin_assert_access(p_staff_id,p_username,p_password);
  IF p_action='list' THEN
    RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'key',s.key,'description',s.description,'is_secret',s.is_secret,'is_active',s.is_active,
      'value',CASE WHEN s.is_secret THEN NULL ELSE s.value END,'version',md5(to_jsonb(s)::text)) ORDER BY s.key),'[]') FROM public.auto_system_settings s);
  ELSIF p_action IN ('reveal','save') THEN
    SELECT * INTO v_setting FROM public.auto_system_settings WHERE id=(p_data->>'id')::bigint FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'admin_not_found'; END IF;
    v_version := md5(to_jsonb(v_setting)::text);
    IF p_action='reveal' THEN RETURN to_jsonb(v_setting) || jsonb_build_object('version',v_version); END IF;
    IF (p_data->>'expected_version') IS DISTINCT FROM v_version THEN RAISE EXCEPTION 'admin_conflict'; END IF;
    IF length(coalesce(p_data->>'value',''))>1000000 OR length(coalesce(p_data->>'description',''))>10000 THEN RAISE EXCEPTION 'admin_invalid_value'; END IF;
    IF p_data ? 'value' AND jsonb_typeof(p_data->'value') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'admin_invalid_value'; END IF;
    UPDATE public.auto_system_settings SET description=p_data->>'description',
      value=CASE WHEN p_data ? 'value' THEN p_data->>'value' ELSE value END,updated_at=clock_timestamp()
    WHERE id=v_setting.id;
    RETURN '{}'::jsonb;
  END IF;
  RAISE EXCEPTION 'admin_invalid_action';
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_advance_zalo_server_multi_daily_slot(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_next_schedule timestamp with time zone)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, reset_count integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_campaign_status text;
  v_account_status text;
  v_account_login_status text;
  v_account_is_active boolean;
  v_account_is_delete boolean;
  v_campaign_is_delete boolean;
  v_reset_count integer := 0;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Campaign, account and staff IDs must be positive integers'; END IF;
  IF p_next_schedule IS NULL THEN RAISE EXCEPTION 'Next schedule is required'; END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', NULL::text, NULL::text, 0;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Input status mutations use input -> campaign -> account. Lock every live
  -- row in the same deterministic order before advancing the whole slot so a
  -- concurrent pause/resume cannot invert the order or commit a stale state.
  PERFORM input_data.id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
  ORDER BY input_data.id
  FOR UPDATE OF input_data;

  SELECT campaign.status, account.status, account.login_status,
    COALESCE(account.is_active, false), COALESCE(account.is_delete, false),
    COALESCE(campaign.is_delete, false)
  INTO v_campaign_status, v_account_status, v_account_login_status,
    v_account_is_active, v_account_is_delete, v_campaign_is_delete
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND campaign.action_id IN ('zalo_message_friend', 'zalo_message_group')
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
  FOR UPDATE OF campaign, account;

  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found', NULL::text, NULL::text, 0; RETURN; END IF;
  IF v_campaign_is_delete THEN RETURN QUERY SELECT false, 'campaign_deleted', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF v_account_is_delete THEN RETURN QUERY SELECT false, 'account_deleted', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF NOT v_account_is_active THEN RETURN QUERY SELECT false, 'account_inactive', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF v_account_login_status IS DISTINCT FROM 'đã đăng nhập' THEN RETURN QUERY SELECT false, 'account_logged_out', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF v_campaign_status IS DISTINCT FROM 'đang chạy' OR v_account_status IS DISTINCT FROM 'đang chạy' THEN
    RETURN QUERY SELECT false, 'runtime_control_paused', v_campaign_status, v_account_status, 0;
    RETURN;
  END IF;

  UPDATE public.auto_campaign_input_data
  SET status = 'chờ xử lý', note = '', date_action = NULL
  WHERE campaign_id = p_campaign_id
    AND COALESCE(is_delete, false) = false
    AND status <> 'tạm dừng';
  GET DIAGNOSTICS v_reset_count = ROW_COUNT;

  UPDATE public.auto_campaigns
  SET status = 'chờ xử lý', schedule = p_next_schedule, note = NULL, updated_at = now()
  WHERE id = p_campaign_id;
  RETURN QUERY SELECT true, 'advanced', 'chờ xử lý', v_account_status, v_reset_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_apply_zalo_server_campaign_tags(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_account_id bigint, p_runtime_claim_token uuid, p_runtime_unit_token uuid, p_input_data_id bigint, p_contact_type text, p_target_uid text, p_tag_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_input public.auto_campaign_input_data%ROWTYPE;
  v_caps record;
  v_uid text := NULLIF(btrim(p_target_uid),'');
  v_input_uid text;
  v_uids text[];
  v_contacts bigint[];
  v_tags bigint[];
BEGIN
  IF p_staff_id IS NULL OR p_staff_id<=0 OR p_organization_id IS NULL OR p_organization_id<=0
    OR p_campaign_id IS NULL OR p_campaign_id<=0 OR p_account_id IS NULL OR p_account_id<=0
    OR p_runtime_claim_token IS NULL OR p_runtime_unit_token IS NULL
    OR p_input_data_id IS NULL OR p_input_data_id<=0
    OR p_contact_type IS NULL OR p_contact_type NOT IN ('person','group')
    OR v_uid IS NULL OR length(v_uid)>256
    OR COALESCE(cardinality(p_tag_ids),0)<1
    OR EXISTS (SELECT 1 FROM unnest(p_tag_ids) id WHERE id IS NULL OR id<=0)
  THEN RAISE EXCEPTION 'server_campaign_tag_claim_required'; END IF;

  -- Same lock order as run-unit claim/content allocation. No separate lease,
  -- SQL connection, credential lookup, or change to campaign ownership.
  PERFORM 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id
    AND is_active IS TRUE FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'server_campaign_tag_staff_invalid'; END IF;
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  SELECT * INTO v_caps FROM public.resolve_organization_zalo_account_capabilities(p_organization_id);
  IF NOT COALESCE(v_caps.qr_enabled,false) OR NOT COALESCE(v_caps.server_enabled,false)
    THEN RAISE EXCEPTION 'server_campaign_tag_runtime_not_owner'; END IF;
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
  SELECT * INTO v_input FROM public.auto_campaign_input_data
    WHERE id=p_input_data_id AND campaign_id=p_campaign_id AND NOT COALESCE(is_delete,false)
      AND status='đang chạy' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'server_campaign_tag_input_not_owned'; END IF;

  SELECT c.* INTO v_campaign FROM public.auto_campaigns c
    JOIN public.auto_accounts a ON a.id=c.account_id AND a.staff_id=c.staff_id
    WHERE c.id=p_campaign_id AND c.account_id=p_account_id AND c.staff_id=p_staff_id
      AND c.organization_id=p_organization_id AND a.organization_id=p_organization_id
      AND NOT COALESCE(c.is_delete,false) AND NOT COALESCE(a.is_delete,false)
      AND a.is_active IS TRUE AND a.login_status='đã đăng nhập'
      AND lower(btrim(a.flatform_type))='zalo' AND a.is_zalo_server IS TRUE AND a.is_zalo_show_web IS NOT TRUE
      AND c.runtime_claim_target='server' AND c.runtime_claim_token=p_runtime_claim_token
      AND c.runtime_unit_token=p_runtime_unit_token AND c.runtime_unit_claimed_at IS NOT NULL
    FOR UPDATE OF c,a;
  IF NOT FOUND THEN RAISE EXCEPTION 'server_campaign_tag_claim_invalid'; END IF;
  -- A soft pause drains the already-owned unit; do not require running status
  -- on campaign/account. Release or replacement invalidates these tokens.
  IF NOT COALESCE(p_input_data_id=ANY(v_campaign.runtime_unit_input_data_ids),false)
    THEN RAISE EXCEPTION 'server_campaign_tag_input_not_in_unit'; END IF;

  IF (v_campaign.extra_settings->'enableAkaBizTag') IS DISTINCT FROM 'true'::jsonb
    OR jsonb_typeof(v_campaign.extra_settings->'akaBizTagIds') IS DISTINCT FROM 'array'
    OR v_campaign.action_id IS NULL
    OR v_campaign.action_id NOT IN ('zalo_message_phone','zalo_message_friend','zalo_message_group_member',
      'zalo_message_group_realtime','zalo_message_remarketing_customer','zalo_message_friend_recommendation',
      'zalo_message_group','zalo_add_group_member')
    OR (p_contact_type='group') IS DISTINCT FROM (v_campaign.action_id='zalo_message_group')
  THEN RAISE EXCEPTION 'server_campaign_tag_configuration_invalid'; END IF;
  SELECT array_agg(DISTINCT id ORDER BY id) INTO v_tags FROM unnest(p_tag_ids) id;
  IF EXISTS (SELECT 1 FROM unnest(v_tags) requested(id) WHERE NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(v_campaign.extra_settings->'akaBizTagIds') configured(value)
      WHERE configured.value=requested.id::text))
    OR EXISTS (SELECT 1 FROM unnest(v_tags) requested(id) WHERE NOT EXISTS (
      SELECT 1 FROM public.auto_contact_tags t WHERE t.id=requested.id AND t.staff_id=p_staff_id
        AND t.organization_id=p_organization_id
        AND (t.auto_account_id IS NULL OR t.auto_account_id=p_account_id)))
  THEN RAISE EXCEPTION 'server_campaign_tag_scope_invalid'; END IF;

  -- Phone resolution persists input.uid before tagging. All other paths retain
  -- their input UID. Never accept arbitrary contact IDs from the Server client.
  v_input_uid := NULLIF(btrim(v_input.uid),'');
  IF p_contact_type='group' THEN
    IF NULLIF(regexp_replace(v_uid,'^[gG]',''),'') IS NULL
      OR NULLIF(regexp_replace(v_uid,'^[gG]',''),'') IS DISTINCT FROM
      NULLIF(regexp_replace(v_input_uid,'^[gG]',''),'') OR v_input_uid IS NULL
      THEN RAISE EXCEPTION 'server_campaign_tag_target_mismatch'; END IF;
    v_uids := ARRAY[v_uid,regexp_replace(v_uid,'^[gG]','')];
  ELSE
    IF v_uid IS DISTINCT FROM v_input_uid THEN RAISE EXCEPTION 'server_campaign_tag_target_mismatch'; END IF;
    v_uids := ARRAY[v_uid];
  END IF;
  SELECT COALESCE(array_agg(c.id ORDER BY c.id),'{}'::bigint[]) INTO v_contacts
    FROM public.auto_account_contacts c WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id
      AND c.organization_id=p_organization_id AND c.contact_type=p_contact_type
      AND c.uid=ANY(v_uids) AND NOT c.is_delete;
  RETURN public.aka_agent_internal_mutate_contact_tags(p_staff_id,p_organization_id,v_contacts,v_tags,'add');
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_bind_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_campaign_id bigint, p_group_id bigint, p_bundle_id bigint, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_bind_campaign_data_group_source(
      p_staff_id, p_organization_id, p_request_id, p_campaign_id,
      p_group_id, p_bundle_id
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_browser_run_limits(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '10s'
 SET lock_timeout TO '5s'
AS $function$
DECLARE
  v_staff public.org_staff%ROWTYPE;
  v_key text;
  v_zalo integer;
  v_facebook integer;
  v_revision bigint;
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('get','save') THEN RAISE EXCEPTION 'browser_run_limits_invalid_action'; END IF;
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF p_action = 'save' THEN
    SELECT * INTO v_staff FROM public.org_staff WHERE id=p_staff_id FOR UPDATE;
  ELSE
    SELECT * INTO v_staff FROM public.org_staff WHERE id=p_staff_id;
  END IF;
  -- Revalidate the exact identity after locking, including service_role calls.
  IF NOT FOUND OR v_staff.organization_id IS DISTINCT FROM p_organization_id
    OR v_staff.is_active IS NOT TRUE OR v_staff.deleted_at IS NOT NULL
    OR p_auth_username IS NULL OR p_auth_password IS NULL
    OR v_staff.username IS DISTINCT FROM p_auth_username OR v_staff.password IS DISTINCT FROM p_auth_password
    OR NOT public.aka_agent_staff_time_allowed(p_staff_id) THEN
    RAISE EXCEPTION 'browser_run_limits_access_denied';
  END IF;
  IF p_action='save' THEN
    IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'browser_run_limits_invalid_input'; END IF;
    FOREACH v_key IN ARRAY ARRAY['zaloWebMax','facebookMax'] LOOP
      IF NOT (p_data ? v_key) THEN RAISE EXCEPTION 'browser_run_limits_invalid_input'; END IF;
      IF p_data->v_key <> 'null'::jsonb AND (
        jsonb_typeof(p_data->v_key) <> 'number'
        OR (p_data->>v_key) !~ '^[0-9]+$'
        OR (p_data->>v_key)::numeric < 1 OR (p_data->>v_key)::numeric > 2147483647
      ) THEN RAISE EXCEPTION 'browser_run_limits_invalid_input'; END IF;
    END LOOP;
    IF jsonb_typeof(p_data->'revision') IS DISTINCT FROM 'number'
      OR (p_data->>'revision') !~ '^[0-9]+$'
      OR (p_data->>'revision')::numeric > 9007199254740991 THEN
      RAISE EXCEPTION 'browser_run_limits_invalid_input';
    END IF;
    v_revision := (p_data->>'revision')::bigint;
    IF v_revision IS DISTINCT FROM v_staff.browser_run_limits_revision THEN
      RETURN jsonb_build_object('ok',false,'reason','conflict');
    END IF;
    v_zalo := (p_data->>'zaloWebMax')::integer;
    v_facebook := (p_data->>'facebookMax')::integer;
    UPDATE public.org_staff SET max_running_zalo_web_accounts=v_zalo,
      max_running_facebook_accounts=v_facebook, browser_run_limits_revision=browser_run_limits_revision+1
    WHERE id=p_staff_id RETURNING * INTO v_staff;
  END IF;
  RETURN jsonb_build_object('ok',true,'settings',jsonb_build_object(
    'zaloWebMax',v_staff.max_running_zalo_web_accounts,'facebookMax',v_staff.max_running_facebook_accounts,
    'revision',v_staff.browser_run_limits_revision));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_campaign_diagnostics_evidence(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE
  v_account_id bigint;
  v_log text;
  v_account_history jsonb;
  v_campaign_history jsonb;
  v_results jsonb;
  v_summary jsonb;
  v_inputs jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id, p_organization_id, p_auth_username, p_auth_password);
  -- Explicit credentials and tenant ownership are required even for a service-role caller.
  IF p_staff_id IS NULL OR p_organization_id IS NULL OR p_campaign_id IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.org_staff s JOIN public.org_organization o ON o.id=s.organization_id
      WHERE s.id=p_staff_id AND s.organization_id=p_organization_id AND s.is_active
        AND s.username=p_auth_username AND s.password=p_auth_password) THEN
    RAISE EXCEPTION 'diagnostics_access_denied' USING ERRCODE='42501';
  END IF;
  SELECT c.account_id INTO v_account_id
  FROM public.auto_campaigns c JOIN public.auto_accounts a ON a.id=c.account_id
  WHERE c.id=p_campaign_id AND c.staff_id=p_staff_id AND NOT c.is_delete
    AND (c.organization_id=p_organization_id OR c.organization_id IS NULL)
    AND a.staff_id=p_staff_id AND (a.organization_id=p_organization_id OR a.organization_id IS NULL)
    AND a.flatform_type IN ('facebook','zalo','email');
  IF NOT FOUND THEN RAISE EXCEPTION 'diagnostics_access_denied' USING ERRCODE='42501'; END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC,x.id DESC),'[]') INTO v_account_history FROM (
    SELECT id,created_at,login_status,account_status,source,event_type,left(message,8000) AS message,details
    FROM public.auto_account_logs WHERE account_id=v_account_id
    ORDER BY created_at DESC,id DESC LIMIT 30
  ) x;
  -- Latest 30 nonempty physical lines, preserving the existing evidence contract.
  SELECT coalesce(jsonb_agg(left(x.line,8000) ORDER BY x.id DESC,x.n DESC),'[]') INTO v_campaign_history FROM (
    SELECT h.id,l.line,l.n
    FROM (SELECT id,log FROM public.auto_campaign_logs WHERE campaign_id=p_campaign_id ORDER BY id DESC LIMIT 30) h
    CROSS JOIN LATERAL unnest(string_to_array(h.log,E'\n')) WITH ORDINALITY l(line,n)
    WHERE btrim(l.line)<>'' ORDER BY h.id DESC,l.n DESC LIMIT 30
  ) x;
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC,x.id DESC),'[]') INTO v_results FROM (
    SELECT id,input_data_id,created_at,action_name,action_code,status,left(log,8000) AS log,
      error_code,status_id,sub_status_id,action_status_policy_id,report_group,policy_snapshot,counts_toward_limit,post_url
    FROM public.auto_campaign_details WHERE campaign_id=p_campaign_id AND account_id=v_account_id AND NOT is_delete
    ORDER BY created_at DESC,id DESC LIMIT 30
  ) x;
  SELECT coalesce(jsonb_object_agg(x.status,x.total),'{}') INTO v_summary FROM (
    SELECT coalesce(status,'chưa xác minh') AS status,count(*) AS total FROM public.auto_campaign_input_data
    WHERE campaign_id=p_campaign_id AND NOT is_delete GROUP BY status
  ) x;
  WITH pending AS MATERIALIZED (
    SELECT id,input_id,name,phone,uid,email,status,schedule,note,content,info1,info2,info3,info4,info5,created_at
    FROM public.auto_campaign_input_data WHERE campaign_id=p_campaign_id AND NOT is_delete AND status='chờ xử lý'
    ORDER BY created_at DESC,id DESC LIMIT 30
  ), others AS (
    SELECT id,input_id,name,phone,uid,email,status,schedule,note,content,info1,info2,info3,info4,info5,created_at
    FROM public.auto_campaign_input_data WHERE campaign_id=p_campaign_id AND NOT is_delete AND status IS DISTINCT FROM 'chờ xử lý'
    ORDER BY created_at DESC,id DESC LIMIT (SELECT 30-count(*) FROM pending)
  ), sample AS (SELECT * FROM pending UNION ALL SELECT * FROM others)
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY (x.status='chờ xử lý') DESC NULLS LAST,x.created_at DESC,x.id DESC),'[]') INTO v_inputs FROM sample x;
  RETURN jsonb_build_object('accountHistory',v_account_history,'campaignHistory',v_campaign_history,
    'results',v_results,'inputSummary',v_summary,'inputs',v_inputs);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_campaign_drafts(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_operation text, p_draft_id uuid, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  d public.auto_campaign_drafts%ROWTYPE;
  v_form jsonb;
  v_item jsonb;
  v_count integer;
  v_page integer;
  v_items jsonb;
  v_campaign_ids bigint[];
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id, p_organization_id, p_auth_username, p_auth_password);
  IF NOT EXISTS (SELECT 1 FROM public.org_staff WHERE id = p_staff_id AND organization_id = p_organization_id AND is_active = true) THEN
    RAISE EXCEPTION 'Không có quyền truy cập bản nháp.';
  END IF;

  IF p_operation = 'list' THEN
    v_page := greatest(1, least(coalesce((p_data->>'page')::integer, 1), 100000));
    SELECT count(*) INTO v_count FROM public.auto_campaign_drafts
      WHERE staff_id = p_staff_id AND organization_id = p_organization_id AND NOT is_delete;
    SELECT coalesce(jsonb_agg(x.item ORDER BY x.updated_at DESC, x.id), '[]'::jsonb) INTO v_items FROM (
      SELECT id, updated_at, jsonb_build_object(
        'id', id, 'name', payload #>> '{values,formData,name}',
        'actionId', payload #>> '{values,formData,actionId}',
        'accountIds', payload #> '{values,formData,accountIds}',
        'schedule', payload #>> '{values,formData,schedule}',
        'updatedAt', updated_at, 'revision', revision
      ) AS item FROM public.auto_campaign_drafts
      WHERE staff_id = p_staff_id AND organization_id = p_organization_id AND NOT is_delete
      ORDER BY updated_at DESC, id LIMIT 50 OFFSET (v_page - 1) * 50
    ) x;
    RETURN jsonb_build_object('items', v_items, 'total', v_count);
  END IF;
  IF p_draft_id IS NULL THEN RAISE EXCEPTION 'Bản nháp không hợp lệ.'; END IF;

  -- Serializes retries (including a save whose response was lost).
  PERFORM pg_advisory_xact_lock(hashtextextended('campaign-draft:' || p_draft_id::text, 0));
  SELECT * INTO d FROM public.auto_campaign_drafts WHERE id = p_draft_id FOR UPDATE;
  IF FOUND AND (d.staff_id <> p_staff_id OR d.organization_id <> p_organization_id) THEN
    RAISE EXCEPTION 'Không tìm thấy bản nháp.';
  END IF;

  IF p_operation = 'save' THEN
    IF d.is_delete THEN RAISE EXCEPTION 'Bản nháp đã được xoá hoặc chuyển thành chiến dịch.'; END IF;
    IF p_data #>> '{payload,version}' IS DISTINCT FROM '1' THEN RAISE EXCEPTION 'Phiên bản bản nháp chưa được hỗ trợ.'; END IF;
    v_form := p_data #> '{payload,values,formData}';
    IF jsonb_typeof(v_form) IS DISTINCT FROM 'object'
      OR nullif(btrim(v_form->>'name'), '') IS NULL
      OR nullif(btrim(v_form->>'actionId'), '') IS NULL
      OR jsonb_typeof(v_form->'accountIds') IS DISTINCT FROM 'array'
      OR jsonb_array_length(v_form->'accountIds') = 0
      OR nullif(v_form->>'schedule', '') IS NULL THEN
      RAISE EXCEPTION 'Vui lòng nhập Tên, Hành động, Tài khoản và lịch gửi hợp lệ.';
    END IF;
    PERFORM (v_form->>'schedule')::timestamptz;
    IF NOT EXISTS (SELECT 1 FROM public.auto_campaign_actions WHERE id = v_form->>'actionId' AND is_active = true AND NOT coalesce(is_delete, false)) THEN
      RAISE EXCEPTION 'Hành động không còn khả dụng.';
    END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(v_form->'accountIds') LOOP
      IF NOT EXISTS (SELECT 1 FROM public.auto_accounts a JOIN public.auto_campaign_actions act ON act.id = v_form->>'actionId'
        WHERE a.id = (v_item #>> '{}')::bigint AND a.staff_id = p_staff_id AND a.organization_id = p_organization_id
          AND NOT coalesce(a.is_delete, false) AND a.flatform_type = act.flatform_type) THEN
        RAISE EXCEPTION 'Tài khoản không thuộc người dùng hoặc không phù hợp với hành động.';
      END IF;
    END LOOP;
    IF d.id IS NULL THEN
      IF coalesce((p_data->>'revision')::integer, 0) <> 0 THEN RAISE EXCEPTION 'Không tìm thấy bản nháp.'; END IF;
      INSERT INTO public.auto_campaign_drafts(id, staff_id, organization_id, payload)
      VALUES (p_draft_id, p_staff_id, p_organization_id, p_data->'payload') RETURNING * INTO d;
    ELSIF d.payload IS DISTINCT FROM p_data->'payload' THEN
      IF d.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN
        RAISE EXCEPTION 'Bản nháp đã thay đổi ở nơi khác. Vui lòng mở lại trước khi lưu.';
      END IF;
      UPDATE public.auto_campaign_drafts SET payload = p_data->'payload', revision = revision + 1, updated_at = now()
        WHERE id = d.id RETURNING * INTO d;
    END IF;
  ELSIF d.id IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy bản nháp.';
  ELSIF p_operation = 'get' THEN
    NULL;
  ELSIF p_operation = 'delete' THEN
    IF d.deletion_reason = 'converted' THEN RAISE EXCEPTION 'Bản nháp đã chuyển thành chiến dịch.'; END IF;
    UPDATE public.auto_campaign_drafts SET is_delete = true, deleted_at = coalesce(deleted_at, now()),
      deletion_reason = 'user_deleted', updated_at = now() WHERE id = d.id RETURNING * INTO d;
  ELSIF p_operation = 'complete' THEN
    -- Campaign creation has already succeeded through the normal campaign APIs.
    -- This operation only records the result and soft-deletes the form snapshot.
    IF jsonb_typeof(p_data->'campaignIds') IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_data->'campaignIds') = 0 THEN
      RAISE EXCEPTION 'Danh sách chiến dịch đã tạo không hợp lệ.';
    END IF;
    SELECT array_agg(DISTINCT value::bigint ORDER BY value::bigint) INTO v_campaign_ids
      FROM jsonb_array_elements_text(p_data->'campaignIds');
    IF EXISTS (SELECT 1 FROM unnest(v_campaign_ids) AS ids(id)
      LEFT JOIN public.auto_campaigns c ON c.id = ids.id
      WHERE c.id IS NULL OR c.staff_id <> p_staff_id OR c.organization_id <> p_organization_id) THEN
      RAISE EXCEPTION 'Chiến dịch không thuộc người dùng.';
    END IF;
    IF d.deletion_reason = 'converted' AND d.campaign_ids = v_campaign_ids THEN
      NULL;
    ELSE
      IF d.is_delete THEN RAISE EXCEPTION 'Bản nháp đã được xoá hoặc chuyển thành chiến dịch.'; END IF;
      IF d.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN
        RAISE EXCEPTION 'Bản nháp đã thay đổi ở nơi khác. Bản nháp được giữ lại.';
      END IF;
      UPDATE public.auto_campaign_drafts SET is_delete = true, deleted_at = now(),
        deletion_reason = 'converted', campaign_ids = v_campaign_ids, updated_at = now()
        WHERE id = d.id RETURNING * INTO d;
    END IF;
  ELSE
    RAISE EXCEPTION 'Thao tác bản nháp không hợp lệ.';
  END IF;
  RETURN jsonb_build_object('id', d.id, 'payload', d.payload, 'revision', d.revision, 'updatedAt', d.updated_at,
    'name', d.payload #>> '{values,formData,name}', 'actionId', d.payload #>> '{values,formData,actionId}',
    'accountIds', d.payload #> '{values,formData,accountIds}', 'schedule', d.payload #>> '{values,formData,schedule}',
    'isDelete', d.is_delete,
    'deletionReason', d.deletion_reason, 'campaignIds', to_jsonb(d.campaign_ids));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_campaign_send_exclusion_runtime(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_claim_token uuid, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE c public.auto_campaigns%ROWTYPE; selection jsonb; g jsonb; ids bigint[]; input public.auto_campaign_input_data%ROWTYPE;
 contact_id bigint; fact jsonb; v_uid text; days integer; last_sent timestamptz; current_time_value timestamptz:=clock_timestamp(); keys text[]; tag_ids jsonb; changed integer;
BEGIN
 SELECT campaign.* INTO c FROM public.auto_campaigns campaign JOIN public.auto_accounts a ON a.id=campaign.account_id
  JOIN public.org_staff s ON s.id=campaign.staff_id AND s.organization_id=campaign.organization_id AND s.is_active
  WHERE campaign.id=p_campaign_id AND campaign.account_id=p_account_id AND campaign.staff_id=p_staff_id AND NOT campaign.is_delete
   AND a.staff_id=p_staff_id AND a.organization_id=campaign.organization_id AND NOT a.is_delete
   AND campaign.runtime_claim_token=p_claim_token AND p_claim_token IS NOT NULL
  FOR UPDATE OF campaign;
 IF NOT FOUND THEN RAISE EXCEPTION 'send_exclusion_runtime_claim_lost'; END IF;
 IF p_operation='snapshot' THEN
  selection:=c.extra_settings->'zaloSendExclusionsByAccountId'->p_account_id::text;
  IF selection IS NULL THEN RAISE EXCEPTION 'send_exclusion_account_configuration_missing'; END IF;
  -- Other accounts are validated when saving configuration or starting their own run.
  PERFORM public.aka_agent_internal_validate_send_exclusion_selection(jsonb_build_object(p_account_id::text,selection),c.staff_id,c.organization_id,p_account_id);
  SELECT ARRAY(SELECT DISTINCT value::bigint FROM jsonb_array_elements_text(COALESCE(selection->'blocklistIds','[]'))) INTO ids;
  RETURN jsonb_build_object('catalog',public.aka_agent_internal_send_exclusion_catalog(),'group',public.aka_agent_internal_send_exclusion_group((selection->>'groupId')::bigint),
   'blocklistUids',COALESCE((SELECT jsonb_agg(DISTINCT btrim(ac.uid)) FROM public.auto_account_contact_group_members m
    JOIN public.auto_account_contacts ac ON ac.id=m.contact_id WHERE m.group_id=ANY(ids) AND NOT m.is_delete AND NOT ac.is_delete
    AND ac.account_id=p_account_id AND ac.staff_id=p_staff_id AND ac.organization_id=c.organization_id AND ac.contact_type='person' AND NULLIF(btrim(ac.uid),'') IS NOT NULL),'[]'));
 END IF;
 SELECT * INTO input FROM public.auto_campaign_input_data WHERE id=(p_payload->>'inputId')::bigint AND campaign_id=p_campaign_id AND NOT is_delete;
 IF NOT FOUND THEN RAISE EXCEPTION 'send_exclusion_input_not_found'; END IF;
 IF p_operation='pause' THEN
  UPDATE public.auto_campaign_input_data SET status='tạm dừng',note=left(p_payload->>'note',2000)
   WHERE id=input.id AND campaign_id=c.id AND status=p_payload->>'expectedStatus' AND status IN ('chờ xử lý','đang chạy') AND NOT is_delete;
  GET DIAGNOSTICS changed=ROW_COUNT;
  RETURN jsonb_build_object('changed',changed=1);
 ELSIF p_operation<>'facts' THEN RAISE EXCEPTION 'send_exclusion_operation_invalid'; END IF;
 v_uid:=COALESCE(NULLIF(btrim(p_payload->>'uid'),''),NULLIF(btrim(input.uid),''));
 IF COALESCE((p_payload->>'tags')::boolean,false) THEN
  IF v_uid IS NULL THEN tag_ids:=NULL; ELSE
   SELECT ac.id INTO contact_id FROM public.auto_account_contacts ac WHERE ac.account_id=c.account_id AND ac.staff_id=c.staff_id AND ac.organization_id=c.organization_id AND ac.contact_type='person' AND ac.uid=v_uid AND NOT ac.is_delete ORDER BY ac.id LIMIT 1;
   IF contact_id IS NOT NULL THEN
    fact:=public.aka_agent_data_group_zalo_facts(contact_id); tag_ids:=fact->'akabiz_tag_keys';
   ELSE
    SELECT COALESCE(jsonb_agg(DISTINCT t.id::text),'[]') INTO tag_ids
     FROM public.chat_zalo_account_organization b JOIN public.chat_zalo_account_conversation ac ON ac.chat_zalo_account_id=b.chat_zalo_account_id AND ac.zalo_id=v_uid AND ac.conversation_type='user'
     JOIN public.chat_zalo_conversation conv ON conv.chat_zalo_account_organization_id=b.id AND conv.chat_zalo_account_conversation_id=ac.id AND conv.organization_id=c.organization_id
     JOIN public.chat_zalo_conversation_system_tag link ON link.chat_zalo_conversation_id=conv.id AND link.organization_id=c.organization_id
     JOIN public.auto_contact_tags t ON t.id=link.auto_contact_tag_id AND t.staff_id=c.staff_id AND t.organization_id=c.organization_id AND NOT t.is_delete AND (t.auto_account_id IS NULL OR t.auto_account_id=c.account_id)
     WHERE b.auto_account_id=c.account_id AND b.organization_id=c.organization_id AND b.is_active;
   END IF;
  END IF;
 END IF;
 IF p_payload ? 'days' THEN
  days:=(p_payload->>'days')::integer;
  IF days<1 OR days>3650 THEN RAISE EXCEPTION 'send_exclusion_days_invalid'; END IF;
  keys:=public.aka_agent_internal_delivery_cooldown_target_keys('zalo_person',COALESCE(v_uid,input.uid),input.phone,input.email);
  IF cardinality(keys)>0 THEN
   SELECT max(h.created_at) INTO last_sent FROM public.aka_agent_internal_send_delivery_history(c.account_id,ARRAY['zalo_message_friend','zalo_message_stranger'],((timezone('Asia/Ho_Chi_Minh',current_time_value)::date-days)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'),current_time_value) h WHERE h.target_keys && keys;
  END IF;
 END IF;
 RETURN jsonb_build_object('akabiz_contact',CASE WHEN tag_ids IS NULL THEN NULL ELSE jsonb_build_object('ids',tag_ids,'availableValues',(SELECT COALESCE(jsonb_agg(t.id::text),'[]') FROM public.auto_contact_tags t WHERE t.staff_id=c.staff_id AND t.organization_id=c.organization_id AND NOT t.is_delete AND (t.auto_account_id IS NULL OR t.auto_account_id=c.account_id))) END,
  'campaign_delivery',CASE WHEN days IS NULL OR cardinality(keys)=0 THEN NULL ELSE jsonb_build_object('daysSince',CASE WHEN last_sent IS NULL THEN 3651 ELSE timezone('Asia/Ho_Chi_Minh',current_time_value)::date-timezone('Asia/Ho_Chi_Minh',last_sent)::date END) END);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_check_campaign_daily_boundary(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_claimed_vietnam_date date)
 RETURNS TABLE(allow_new_unit boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date, claimed_vietnam_date_key date, effective_stop_time time without time zone, boundary_at timestamp with time zone, day_changed boolean)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_organization_id bigint;
  v_campaign_status text;
  v_account_status text;
  v_daily_stop_time time without time zone;
  v_campaign_is_delete boolean;
  v_account_is_delete boolean;
  v_account_is_active boolean;
  v_account_login_status text;
  v_account_platform text;
  v_account_is_zalo_web boolean;
  v_account_is_zalo_server boolean;
  v_effective_stop_time time without time zone;
  v_boundary_at timestamptz;
  v_day_changed boolean;
  v_reason text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF p_claimed_vietnam_date IS NULL THEN
    RAISE EXCEPTION 'claimed Vietnam date is required';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true
    AND (public.aka_agent_staff_time_allowed(staff.id) OR EXISTS (
      SELECT 1 FROM public.auto_campaigns held WHERE held.id=p_campaign_id
        AND held.account_id=p_account_id AND held.staff_id=p_staff_id AND held.runtime_unit_token IS NOT NULL
    ))
  ;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date, p_claimed_vietnam_date,
      NULL::time, NULL::timestamptz,
      v_vietnam_date > p_claimed_vietnam_date;
    RETURN;
  END IF;

  SELECT
    campaign.status,
    account.status,
    campaign.daily_stop_time,
    COALESCE(campaign.is_delete, false),
    COALESCE(account.is_delete, false),
    COALESCE(account.is_active, false),
    account.login_status,
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_show_web, false),
    COALESCE(account.is_zalo_server, false)
  INTO
    v_campaign_status,
    v_account_status,
    v_daily_stop_time,
    v_campaign_is_delete,
    v_account_is_delete,
    v_account_is_active,
    v_account_login_status,
    v_account_platform,
    v_account_is_zalo_web,
    v_account_is_zalo_server
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    );

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date, p_claimed_vietnam_date,
      NULL::time, NULL::timestamptz,
      v_vietnam_date > p_claimed_vietnam_date;
    RETURN;
  END IF;

  v_effective_stop_time := LEAST(
    COALESCE(v_daily_stop_time, time '23:59:00'),
    time '23:59:00'
  );
  v_boundary_at := (
    p_claimed_vietnam_date + v_effective_stop_time
  ) AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_day_changed := v_vietnam_date > p_claimed_vietnam_date;

  IF (v_runtime_target = 'server' AND (
      v_account_platform <> 'zalo'
      OR v_account_is_zalo_web
      OR NOT v_account_is_zalo_server
    ))
    OR (v_runtime_target = 'desktop' AND (
      v_account_platform = 'zalo' AND v_account_is_zalo_server
    ))
  THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_campaign_is_delete THEN
    v_reason := 'campaign_deleted';
  ELSIF v_account_is_delete THEN
    v_reason := 'account_deleted';
  ELSIF NOT v_account_is_active THEN
    v_reason := 'account_inactive';
  ELSIF v_account_login_status IS DISTINCT FROM 'đã đăng nhập' THEN
    v_reason := 'account_logged_out';
  ELSIF v_campaign_status IS DISTINCT FROM 'đang chạy'
    OR v_account_status IS DISTINCT FROM 'đang chạy'
  THEN
    -- A concurrent manual campaign/account pause always wins.
    v_reason := 'runtime_control_paused';
  ELSIF p_claimed_vietnam_date > v_vietnam_date THEN
    v_reason := 'invalid_claimed_vietnam_date';
  ELSIF v_day_changed THEN
    v_reason := 'vietnam_day_changed';
  ELSIF v_now >= v_boundary_at THEN
    -- Inclusive comparison: no unit may start exactly at the cutoff.
    v_reason := CASE
      WHEN v_daily_stop_time IS NULL THEN 'daily_drain_due'
      ELSE 'daily_stop_due'
    END;
  ELSE
    v_reason := 'allowed';
  END IF;

  RETURN QUERY SELECT
    v_reason = 'allowed',
    v_reason,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date,
    p_claimed_vietnam_date,
    v_effective_stop_time,
    v_boundary_at,
    v_day_changed;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_claim_account_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_runtime_target text, p_previous_status text, p_claim_token uuid, p_requires_login boolean, p_operation_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_account public.auto_accounts%ROWTYPE; v_organization_id bigint;
BEGIN
  IF p_account_id IS NULL OR p_account_id<=0 OR p_staff_id IS NULL OR p_staff_id<=0
    OR p_claim_token IS NULL OR p_previous_status IS NULL
    OR p_previous_status NOT IN ('chờ xử lý','tạm dừng')
    OR p_platform IS NULL OR p_platform NOT IN ('zalo','facebook','email')
    OR p_runtime_target IS NULL OR p_runtime_target NOT IN ('desktop','server')
    OR (p_platform<>'zalo' AND p_runtime_target<>'desktop') THEN
    RAISE EXCEPTION 'invalid_account_operation_identity';
  END IF;
  IF p_operation_kind IS NULL OR p_operation_kind NOT IN ('operation','type_change')
    OR (p_operation_kind='type_change' AND p_platform<>'zalo') THEN
    RAISE EXCEPTION 'invalid_account_operation_kind';
  END IF;
  -- Keep the existing lock order: staff, entitlement advisory lock, account.
  SELECT organization_id INTO v_organization_id FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share')
    WHERE id=p_staff_id AND is_active=true AND public.aka_agent_staff_time_allowed(p_staff_id) ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object('claimed',false,'reason','staff_not_active');
  END IF;
  IF p_platform='zalo' THEN
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  END IF;
  SELECT * INTO v_account FROM public.auto_accounts a
    WHERE a.id=p_account_id AND a.staff_id=p_staff_id
      AND (a.organization_id IS NULL OR a.organization_id=v_organization_id) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('claimed',false,'reason','account_not_found'); END IF;
  IF COALESCE(v_account.is_delete,false) OR lower(btrim(COALESCE(v_account.flatform_type,'')))<>p_platform
    OR (p_operation_kind='operation' AND v_account.is_active IS NOT TRUE) THEN
    RETURN jsonb_build_object('claimed',false,'reason','account_not_available');
  END IF;
  -- A retry after a lost response must never undo a newer pause/resume write.
  IF v_account.runtime_operation_claim_token=p_claim_token AND v_account.status<>'đang chạy' THEN
    RETURN jsonb_build_object('claimed',false,'reason','control_changed');
  END IF;
  -- Zalo already checks all work below in its existing RPC. Extend the same
  -- producer barrier to non-Zalo scans before delegating their existing claim.
  IF p_platform<>'zalo' AND (EXISTS (SELECT 1 FROM public.auto_campaigns c WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id
      AND (c.status='đang chạy' OR c.runtime_unit_token IS NOT NULL))
    OR EXISTS (SELECT 1 FROM public.auto_campaign_inputs i JOIN public.auto_campaigns c ON c.id=i.campaign_id
      WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id AND i.status='đang chạy')
    OR EXISTS (SELECT 1 FROM public.auto_campaign_input_data d JOIN public.auto_campaigns c ON c.id=d.campaign_id
      WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id AND d.status='đang chạy')) THEN
    RETURN jsonb_build_object('claimed',false,'reason','work_running');
  END IF;
  -- A different token on an idle account can be a completed legacy campaign's
  -- token. Eligibility remains governed by the existing status/work guards.
  IF p_platform='zalo' THEN
    RETURN public.claim_zalo_account_runtime_operation(p_account_id,p_staff_id,p_runtime_target,
      p_previous_status,p_claim_token,CASE WHEN p_operation_kind='type_change' THEN false ELSE COALESCE(p_requires_login,true) END);
  END IF;
  RETURN public.claim_non_zalo_account_runtime_operation(p_account_id,p_staff_id,p_platform,
    p_previous_status,p_claim_token,COALESCE(p_requires_login,true));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_claim_campaign_run_unit_v2(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_claim_token uuid, p_runtime_claim_vietnam_date date, p_runtime_unit_token uuid, p_input_data_ids bigint[] DEFAULT ARRAY[]::bigint[])
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, claimed_count integer, runtime_claim_token uuid, runtime_claim_vietnam_date date, runtime_unit_token uuid, runtime_unit_vietnam_date date, runtime_unit_claimed_at timestamp with time zone, runtime_unit_input_data_ids bigint[], db_now timestamp with time zone, vietnam_date_key date, effective_stop_time time without time zone, boundary_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_input_data_ids bigint[] := ARRAY(
    SELECT DISTINCT ids.input_id
    FROM unnest(
      COALESCE(p_input_data_ids, ARRAY[]::bigint[])
    ) AS ids(input_id)
    ORDER BY ids.input_id
  );
  v_organization_id bigint;
  v_staff_is_active boolean := false;
  v_capabilities record;
  v_campaign_found boolean := false;
  v_campaign_status text;
  v_account_status text;
  v_account_login_status text;
  v_account_is_active boolean;
  v_account_is_delete boolean;
  v_campaign_is_delete boolean;
  v_account_platform text;
  v_account_is_zalo_web boolean;
  v_account_is_zalo_server boolean;
  v_stored_claim_token uuid;
  v_stored_claim_target text;
  v_stored_claim_vietnam_date date;
  v_stored_unit_token uuid;
  v_stored_unit_vietnam_date date;
  v_stored_unit_claimed_at timestamptz;
  v_stored_unit_input_data_ids bigint[];
  v_daily_stop_time time without time zone;
  v_effective_stop_time time without time zone;
  v_boundary_at timestamptz;
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_requested_found_count integer := 0;
  v_requested_pending_count integer := 0;
  v_total_running_count integer := 0;
  v_claimed_count integer := 0;
  v_reason text;
  v_legacy_unit record;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF p_runtime_claim_token IS NULL
    OR p_runtime_claim_vietnam_date IS NULL
    OR p_runtime_unit_token IS NULL
  THEN
    RAISE EXCEPTION 'parent claim token/date and runtime unit token are required';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_input_data_ids, ARRAY[]::bigint[])) AS ids(input_id)
    WHERE ids.input_id IS NULL OR ids.input_id <= 0
  ) THEN
    RAISE EXCEPTION 'input data IDs must be positive integers';
  END IF;
  IF cardinality(v_input_data_ids) > 50 THEN
    RAISE EXCEPTION 'a campaign run unit cannot contain more than 50 input rows';
  END IF;

  SELECT staff.organization_id, COALESCE(staff.is_active, false)
  INTO v_organization_id, v_staff_is_active
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text, 0,
      NULL::uuid, NULL::date,
      NULL::uuid, NULL::date, NULL::timestamptz, NULL::bigint[],
      v_now, v_vietnam_date, NULL::time, NULL::timestamptz;
    RETURN;
  END IF;

  -- Keep the established entitlement -> campaign barrier lock order for both
  -- fresh claims and response recovery. Exact committed-unit recovery does not
  -- consult mutable entitlement/staff-active values after taking these locks.
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  IF cardinality(v_input_data_ids) > 0 THEN
    PERFORM input_data.id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.id = ANY(v_input_data_ids)
      AND input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false
    ORDER BY input_data.id
    FOR UPDATE OF input_data;

    SELECT
      count(*)::integer,
      count(*) FILTER (WHERE input_data.status = 'chờ xử lý')::integer
    INTO v_requested_found_count, v_requested_pending_count
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.id = ANY(v_input_data_ids)
      AND input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false;
  END IF;

  -- Reject a fresh v2 unit while legacy/unrecovered input rows are running.
  PERFORM input_data.id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
    AND input_data.status = 'đang chạy'
  ORDER BY input_data.id
  FOR UPDATE OF input_data;

  SELECT count(*)::integer
  INTO v_total_running_count
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
    AND input_data.status = 'đang chạy';

  SELECT
    campaign.status,
    account.status,
    account.login_status,
    COALESCE(account.is_active, false),
    COALESCE(account.is_delete, false),
    COALESCE(campaign.is_delete, false),
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_show_web, false),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_claim_token,
    campaign.runtime_claim_target,
    campaign.runtime_claim_vietnam_date,
    campaign.runtime_unit_token,
    campaign.runtime_unit_vietnam_date,
    campaign.runtime_unit_claimed_at,
    campaign.runtime_unit_input_data_ids,
    campaign.daily_stop_time
  INTO
    v_campaign_status,
    v_account_status,
    v_account_login_status,
    v_account_is_active,
    v_account_is_delete,
    v_campaign_is_delete,
    v_account_platform,
    v_account_is_zalo_web,
    v_account_is_zalo_server,
    v_stored_claim_token,
    v_stored_claim_target,
    v_stored_claim_vietnam_date,
    v_stored_unit_token,
    v_stored_unit_vietnam_date,
    v_stored_unit_claimed_at,
    v_stored_unit_input_data_ids,
    v_daily_stop_time
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;
  v_campaign_found := FOUND;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_effective_stop_time := LEAST(
    COALESCE(v_daily_stop_time, time '23:59:00'),
    time '23:59:00'
  );
  v_boundary_at := (
    p_runtime_claim_vietnam_date + v_effective_stop_time
  ) AT TIME ZONE 'Asia/Ho_Chi_Minh';

  IF NOT v_campaign_found THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text, 0,
      NULL::uuid, NULL::date,
      NULL::uuid, NULL::date, NULL::timestamptz, NULL::bigint[],
      v_now, v_vietnam_date, NULL::time, NULL::timestamptz;
    RETURN;
  END IF;

  -- The exact committed unit token/date/target/canonical payload is the
  -- linearization point for a lost response. Resolve it only after the same
  -- campaign/input/account locks as a fresh claim, but before mutable
  -- staff-active, entitlement, control, login, or subtype checks. This lets the
  -- caller recover the response and settle instead of stranding maintenance.
  -- Parent fields are NULL-or-match because Desktop soft-pause deliberately
  -- clears that weaker tuple while the opaque unit token/date/exact payload
  -- remains durable; a still-present Server/newer parent must match exactly.
  IF v_stored_unit_token = p_runtime_unit_token
    AND v_stored_unit_vietnam_date = p_runtime_claim_vietnam_date
    AND v_stored_unit_claimed_at IS NOT NULL
    AND v_stored_unit_input_data_ids = v_input_data_ids
    AND (
      v_stored_claim_token IS NULL
      OR v_stored_claim_token = p_runtime_claim_token
    )
    AND (
      v_stored_claim_target IS NULL
      OR v_stored_claim_target = v_runtime_target
    )
    AND (
      v_stored_claim_vietnam_date IS NULL
      OR v_stored_claim_vietnam_date = p_runtime_claim_vietnam_date
    )
  THEN
    RETURN QUERY SELECT
      true, 'already_claimed', v_campaign_status, v_account_status,
      cardinality(v_stored_unit_input_data_ids),
      v_stored_claim_token, v_stored_claim_vietnam_date,
      v_stored_unit_token, v_stored_unit_vietnam_date,
      v_stored_unit_claimed_at, v_stored_unit_input_data_ids,
      v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
    RETURN;
  END IF;

  -- A different/new unit still passes the complete mutable runtime guard.
  IF NOT v_staff_is_active OR NOT public.aka_agent_staff_time_allowed(p_staff_id) THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', v_campaign_status, v_account_status, 0,
      v_stored_claim_token, v_stored_claim_vietnam_date,
      v_stored_unit_token, v_stored_unit_vietnam_date,
      v_stored_unit_claimed_at, v_stored_unit_input_data_ids,
      v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
    RETURN;
  END IF;

  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);

  -- Durable token identity remains authoritative ahead of mutable campaign,
  -- account, login, and subtype checks after the active/entitlement guard.
  IF v_stored_unit_token IS NOT NULL THEN
    IF v_stored_unit_vietnam_date IS NULL
      OR v_stored_unit_claimed_at IS NULL
      OR v_stored_unit_input_data_ids IS NULL
    THEN
      v_reason := 'unit_lease_corrupt';
    ELSIF v_stored_unit_token IS DISTINCT FROM p_runtime_unit_token THEN
      v_reason := 'unit_lease_busy';
    ELSIF (
        v_stored_claim_token IS NOT NULL
        AND v_stored_claim_token IS DISTINCT FROM p_runtime_claim_token
      ) OR (
        v_stored_claim_target IS NOT NULL
        AND v_stored_claim_target IS DISTINCT FROM v_runtime_target
      ) OR (
        v_stored_claim_vietnam_date IS NOT NULL
        AND v_stored_claim_vietnam_date
          IS DISTINCT FROM p_runtime_claim_vietnam_date
      )
    THEN
      v_reason := 'runtime_claim_mismatch';
    ELSIF v_stored_unit_vietnam_date IS DISTINCT FROM p_runtime_claim_vietnam_date
      OR v_stored_unit_input_data_ids IS DISTINCT FROM v_input_data_ids
    THEN
      v_reason := 'unit_lease_payload_mismatch';
    ELSE
      RETURN QUERY SELECT
        true, 'already_claimed', v_campaign_status, v_account_status,
        cardinality(v_stored_unit_input_data_ids),
        v_stored_claim_token, v_stored_claim_vietnam_date,
        v_stored_unit_token, v_stored_unit_vietnam_date,
        v_stored_unit_claimed_at, v_stored_unit_input_data_ids,
        v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
      RETURN;
    END IF;

    RETURN QUERY SELECT
      false, v_reason, v_campaign_status, v_account_status, 0,
      v_stored_claim_token, v_stored_claim_vietnam_date,
      v_stored_unit_token, v_stored_unit_vietnam_date,
      v_stored_unit_claimed_at, v_stored_unit_input_data_ids,
      v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
    RETURN;
  ELSIF v_stored_unit_vietnam_date IS NOT NULL
    OR v_stored_unit_claimed_at IS NOT NULL
    OR v_stored_unit_input_data_ids IS NOT NULL
  THEN
    RETURN QUERY SELECT
      false, 'unit_lease_corrupt', v_campaign_status, v_account_status, 0,
      v_stored_claim_token, v_stored_claim_vietnam_date,
      NULL::uuid, v_stored_unit_vietnam_date,
      v_stored_unit_claimed_at, v_stored_unit_input_data_ids,
      v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
    RETURN;
  END IF;

  IF v_runtime_target = 'server' AND (
      v_account_platform <> 'zalo'
      OR v_account_is_zalo_web
      OR NOT v_account_is_zalo_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_runtime_target = 'desktop'
    AND v_account_platform = 'zalo'
    AND (
      v_account_is_zalo_server
      OR (
        v_account_is_zalo_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_account_is_zalo_web
        AND NOT v_account_is_zalo_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_campaign_is_delete THEN
    v_reason := 'campaign_deleted';
  ELSIF v_account_is_delete THEN
    v_reason := 'account_deleted';
  ELSIF NOT v_account_is_active THEN
    v_reason := 'account_inactive';
  ELSIF v_account_login_status IS DISTINCT FROM 'đã đăng nhập' THEN
    v_reason := 'account_logged_out';
  ELSIF v_campaign_status IS DISTINCT FROM 'đang chạy'
    OR v_account_status IS DISTINCT FROM 'đang chạy'
  THEN
    v_reason := 'runtime_control_paused';
  ELSIF v_stored_claim_token IS DISTINCT FROM p_runtime_claim_token
    OR v_stored_claim_target IS DISTINCT FROM v_runtime_target
    OR v_stored_claim_vietnam_date IS DISTINCT FROM p_runtime_claim_vietnam_date
  THEN
    v_reason := 'runtime_claim_mismatch';
  ELSIF p_runtime_claim_vietnam_date > v_vietnam_date THEN
    v_reason := 'invalid_claimed_vietnam_date';
  ELSIF v_vietnam_date > p_runtime_claim_vietnam_date THEN
    v_reason := 'vietnam_day_changed';
  ELSIF v_now >= v_boundary_at THEN
    v_reason := CASE
      WHEN v_daily_stop_time IS NULL THEN 'daily_drain_due'
      ELSE 'daily_stop_due'
    END;
  ELSIF v_total_running_count > 0
    OR v_requested_found_count <> cardinality(v_input_data_ids)
    OR v_requested_pending_count <> cardinality(v_input_data_ids)
  THEN
    v_reason := 'input_not_pending';
  ELSE
    v_reason := 'allowed';
  END IF;

  IF v_reason='allowed' AND v_account_platform='facebook' THEN
    v_reason:=coalesce(private.facebook_random_unit_gate(p_campaign_id,p_account_id,p_runtime_claim_token,cardinality(v_input_data_ids)),'allowed');
  END IF;

  IF v_reason <> 'allowed' THEN
    RETURN QUERY SELECT
      false, v_reason, v_campaign_status, v_account_status, 0,
      v_stored_claim_token, v_stored_claim_vietnam_date,
      NULL::uuid, NULL::date, NULL::timestamptz, NULL::bigint[],
      v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
    RETURN;
  END IF;

  BEGIN
    IF v_runtime_target = 'server' THEN
      SELECT * INTO v_legacy_unit
      FROM public.aka_agent_claim_zalo_server_run_unit(
        p_campaign_id,
        p_account_id,
        p_staff_id,
        v_input_data_ids
      );
      IF v_legacy_unit.ok IS DISTINCT FROM true THEN
        v_reason := COALESCE(v_legacy_unit.reason, 'unit_claim_rejected');
        RAISE EXCEPTION USING
          ERRCODE = 'P0232',
          MESSAGE = 'legacy Server unit claim rejected';
      END IF;
      v_claimed_count := COALESCE(v_legacy_unit.claimed_count, 0)::integer;
      IF v_claimed_count IS DISTINCT FROM cardinality(v_input_data_ids) THEN
        v_reason := 'unit_claim_count_mismatch';
        RAISE EXCEPTION USING
          ERRCODE = 'P0232',
          MESSAGE = 'legacy Server unit claim count mismatch';
      END IF;
    ELSE
      IF cardinality(v_input_data_ids) > 0 THEN
        UPDATE public.auto_campaign_input_data AS input_data
        SET status = 'đang chạy', date_action = v_now
        WHERE input_data.id = ANY(v_input_data_ids)
          AND input_data.campaign_id = p_campaign_id
          AND COALESCE(input_data.is_delete, false) = false
          AND input_data.status = 'chờ xử lý';
        GET DIAGNOSTICS v_claimed_count = ROW_COUNT;
      END IF;
      IF v_claimed_count IS DISTINCT FROM cardinality(v_input_data_ids) THEN
        v_reason := 'unit_claim_count_mismatch';
        RAISE EXCEPTION USING
          ERRCODE = 'P0232',
          MESSAGE = 'Desktop unit claim count mismatch';
      END IF;
    END IF;

    -- The lease is written only after the exact reservation succeeds and a
    -- final DB-clock sample confirms the inclusive boundary is still open.
    v_now := clock_timestamp();
    v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
    IF v_vietnam_date > p_runtime_claim_vietnam_date THEN
      v_reason := 'vietnam_day_changed';
      RAISE EXCEPTION USING
        ERRCODE = 'P0232',
        MESSAGE = 'run unit crossed Vietnam midnight';
    ELSIF v_now >= v_boundary_at THEN
      v_reason := CASE
        WHEN v_daily_stop_time IS NULL THEN 'daily_drain_due'
        ELSE 'daily_stop_due'
      END;
      RAISE EXCEPTION USING
        ERRCODE = 'P0232',
        MESSAGE = 'run unit crossed its daily boundary';
    END IF;

    UPDATE public.auto_campaigns AS campaign
    SET runtime_unit_token = p_runtime_unit_token,
      runtime_unit_vietnam_date = p_runtime_claim_vietnam_date,
      runtime_unit_claimed_at = v_now,
      runtime_unit_input_data_ids = v_input_data_ids,
      updated_at = v_now
    WHERE campaign.id = p_campaign_id
      AND campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
      AND campaign.runtime_claim_token = p_runtime_claim_token
      AND campaign.runtime_claim_target = v_runtime_target
      AND campaign.runtime_claim_vietnam_date = p_runtime_claim_vietnam_date
      AND campaign.runtime_unit_token IS NULL;

    IF NOT FOUND THEN
      v_reason := 'unit_lease_lost';
      RAISE EXCEPTION USING
        ERRCODE = 'P0232',
        MESSAGE = 'run-unit lease lost parent ownership';
    END IF;

    IF v_account_platform='facebook' THEN PERFORM private.facebook_random_unit_started(p_campaign_id,p_account_id,p_runtime_unit_token); END IF;

    RETURN QUERY SELECT
      true, 'claimed', v_campaign_status, v_account_status, v_claimed_count,
      p_runtime_claim_token, p_runtime_claim_vietnam_date,
      p_runtime_unit_token, p_runtime_claim_vietnam_date,
      v_now, v_input_data_ids,
      v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
    RETURN;
  EXCEPTION
    WHEN SQLSTATE 'P0232' THEN
      -- Reservation and lease writes in this subtransaction are rolled back
      -- together; no compensating UPDATE can clobber a concurrent control row.
      NULL;
  END;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  SELECT campaign.status, account.status,
    campaign.runtime_claim_token, campaign.runtime_claim_vietnam_date,
    campaign.runtime_unit_token, campaign.runtime_unit_vietnam_date,
    campaign.runtime_unit_claimed_at, campaign.runtime_unit_input_data_ids
  INTO v_campaign_status, v_account_status,
    v_stored_claim_token, v_stored_claim_vietnam_date,
    v_stored_unit_token, v_stored_unit_vietnam_date,
    v_stored_unit_claimed_at, v_stored_unit_input_data_ids
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id;

  RETURN QUERY SELECT
    false, COALESCE(v_reason, 'unit_claim_lost'),
    v_campaign_status, v_account_status, 0,
    v_stored_claim_token, v_stored_claim_vietnam_date,
    v_stored_unit_token, v_stored_unit_vietnam_date,
    v_stored_unit_claimed_at, v_stored_unit_input_data_ids,
    v_now, v_vietnam_date, v_effective_stop_time, v_boundary_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_claim_zalo_server_run_unit(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_input_data_ids bigint[] DEFAULT ARRAY[]::bigint[])
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, claimed_count integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_capabilities record;
  v_campaign_status text;
  v_account_status text;
  v_account_login_status text;
  v_account_is_active boolean;
  v_account_is_delete boolean;
  v_campaign_is_delete boolean;
  v_input_data_ids bigint[] := ARRAY(
    SELECT DISTINCT ids.input_id
    FROM unnest(COALESCE(p_input_data_ids, ARRAY[]::bigint[])) AS ids(input_id)
    ORDER BY ids.input_id
  );
  v_input_data_id bigint;
  v_claimed_count integer := 0;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Campaign, account and staff IDs must be positive integers'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(COALESCE(p_input_data_ids, ARRAY[]::bigint[])) AS ids(input_id)
    WHERE ids.input_id IS NULL OR ids.input_id <= 0
  ) THEN RAISE EXCEPTION 'Input data IDs must be positive integers'; END IF;
  IF cardinality(v_input_data_ids) > 50 THEN
    RAISE EXCEPTION 'A Zalo Server run unit cannot contain more than 50 input rows';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', NULL::text, NULL::text, 0;
    RETURN;
  END IF;
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
  THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', NULL::text, NULL::text, 0;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Match Control input pause/resume: requested inputs are always the first
  -- mutable rows in the lock chain, followed by campaign and account below.
  -- The status predicate is rechecked by PostgreSQL after any blocked updater.
  IF cardinality(v_input_data_ids) > 0 THEN
    FOR v_input_data_id IN
      SELECT input_data.id
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.id = ANY(v_input_data_ids)
        AND input_data.campaign_id = p_campaign_id
        AND COALESCE(input_data.is_delete, false) = false
        AND input_data.status = 'chờ xử lý'
      ORDER BY input_data.id
      FOR UPDATE OF input_data
    LOOP
      v_claimed_count := v_claimed_count + 1;
    END LOOP;
  END IF;

  SELECT campaign.status, account.status, account.login_status,
    COALESCE(account.is_active, false), COALESCE(account.is_delete, false),
    COALESCE(campaign.is_delete, false)
  INTO v_campaign_status, v_account_status, v_account_login_status,
    v_account_is_active, v_account_is_delete, v_campaign_is_delete
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
  FOR UPDATE OF campaign, account;

  IF NOT FOUND THEN RETURN QUERY SELECT false, 'not_found', NULL::text, NULL::text, 0; RETURN; END IF;
  IF v_campaign_is_delete THEN RETURN QUERY SELECT false, 'campaign_deleted', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF v_account_is_delete THEN RETURN QUERY SELECT false, 'account_deleted', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF NOT v_account_is_active THEN RETURN QUERY SELECT false, 'account_inactive', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF v_account_login_status IS DISTINCT FROM 'đã đăng nhập' THEN RETURN QUERY SELECT false, 'account_logged_out', v_campaign_status, v_account_status, 0; RETURN; END IF;
  IF v_campaign_status IS DISTINCT FROM 'đang chạy' OR v_account_status IS DISTINCT FROM 'đang chạy' THEN
    RETURN QUERY SELECT false, 'runtime_control_paused', v_campaign_status, v_account_status, 0;
    RETURN;
  END IF;

  IF cardinality(v_input_data_ids) > 0 THEN
    IF v_claimed_count <> cardinality(v_input_data_ids) THEN
      RETURN QUERY SELECT false, 'input_not_pending', v_campaign_status, v_account_status, 0;
      RETURN;
    END IF;
    UPDATE public.auto_campaign_input_data
    SET status = 'đang chạy', date_action = now()
    WHERE id = ANY(v_input_data_ids) AND campaign_id = p_campaign_id;
  END IF;

  RETURN QUERY SELECT true, 'claimed', v_campaign_status, v_account_status, v_claimed_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_cleanup_account_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_runtime_target text, p_previous_status text, p_claim_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_account public.auto_accounts%ROWTYPE; v_organization_id bigint;
BEGIN
  IF p_account_id IS NULL OR p_account_id<=0 OR p_staff_id IS NULL OR p_staff_id<=0
    OR p_claim_token IS NULL OR p_previous_status IS NULL
    OR p_previous_status NOT IN ('chờ xử lý','tạm dừng')
    OR p_platform IS NULL OR p_platform NOT IN ('zalo','facebook','email')
    OR p_runtime_target IS NULL OR p_runtime_target NOT IN ('desktop','server')
    OR (p_platform<>'zalo' AND p_runtime_target<>'desktop') THEN
    RAISE EXCEPTION 'invalid_account_operation_identity';
  END IF;
  -- Cleanup is allowed after entitlement/subtype/active changes, but only for
  -- this staff, organization, platform and exact operation token.
  SELECT organization_id INTO v_organization_id FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share')
    WHERE id=p_staff_id ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','staff_not_found');
  END IF;
  IF p_platform='zalo' THEN
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  END IF;
  SELECT * INTO v_account FROM public.auto_accounts a
    WHERE a.id=p_account_id AND a.staff_id=p_staff_id
      AND (a.organization_id IS NULL OR a.organization_id=v_organization_id)
      AND lower(btrim(COALESCE(a.flatform_type,'')))=p_platform FOR UPDATE;
  IF NOT FOUND OR v_account.runtime_operation_claim_token IS DISTINCT FROM p_claim_token THEN
    RETURN jsonb_build_object('ok',true,'reason','not_owner');
  END IF;
  IF EXISTS (SELECT 1 FROM public.auto_campaigns c WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id
      AND (c.status='đang chạy' OR c.runtime_unit_token IS NOT NULL))
    OR EXISTS (SELECT 1 FROM public.auto_campaign_inputs i JOIN public.auto_campaigns c ON c.id=i.campaign_id
      WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id AND i.status='đang chạy')
    OR EXISTS (SELECT 1 FROM public.auto_campaign_input_data d JOIN public.auto_campaigns c ON c.id=d.campaign_id
      WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id AND d.status='đang chạy') THEN
    RETURN jsonb_build_object('ok',false,'reason','work_running');
  END IF;
  UPDATE public.auto_accounts a SET
    status=CASE WHEN a.status='đang chạy' THEN p_previous_status ELSE a.status END,
    runtime_operation_claim_token=NULL, updated_at=now()
    WHERE a.id=p_account_id AND a.staff_id=p_staff_id AND a.runtime_operation_claim_token=p_claim_token;
  RETURN jsonb_build_object('ok',true,'reason','cleaned');
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_cleanup_failed_campaign_runtime(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_claim_token uuid, p_runtime_unit_token uuid, p_unstarted_input_data_ids bigint[], p_note text, p_pause_unknown_outcome boolean, p_campaign_status text DEFAULT NULL::text, p_account_status text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, reason text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org bigint;
  v_optimistic_ids bigint[];
  v_ids bigint[];
  v_parent uuid;
  v_unit uuid;
  v_account_token uuid;
  v_target text;
  v_claim_date date;
  v_claim_at timestamptz;
  v_unit_date date;
  v_unit_at timestamptz;
  v_campaign_status text;
  v_account_status text;
  v_now timestamptz := clock_timestamp();
  v_unstarted bigint[] := COALESCE(p_unstarted_input_data_ids, ARRAY[]::bigint[]);
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
    OR p_runtime_target IS NULL OR p_runtime_target NOT IN ('desktop', 'server')
    OR p_runtime_claim_token IS NULL OR p_pause_unknown_outcome IS NULL
    OR cardinality(v_unstarted) > 50 OR array_position(v_unstarted, NULL) IS NOT NULL
    OR (p_campaign_status IS NOT NULL AND p_campaign_status NOT IN ('chờ xử lý', 'tạm dừng'))
    OR (p_account_status IS NOT NULL AND p_account_status NOT IN ('chờ xử lý', 'tạm dừng'))
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Invalid failure cleanup payload';
  END IF;

  -- Like v2 settlement, cleanup survives entitlement/subtype changes, but
  -- requires the original opaque token and tenant scope under invoker RLS.
  SELECT staff.organization_id INTO v_org
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') staff WHERE staff.id = p_staff_id ;
  IF NOT FOUND OR v_org IS NULL THEN
    RETURN QUERY SELECT false, 'not_owner'; RETURN;
  END IF;
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
  SELECT c.runtime_unit_input_data_ids INTO v_optimistic_ids
  FROM public.auto_campaigns c JOIN public.auto_accounts a ON a.id = c.account_id AND a.staff_id = c.staff_id
  WHERE c.id = p_campaign_id AND c.account_id = p_account_id AND c.staff_id = p_staff_id
    AND (c.organization_id IS NULL OR c.organization_id = v_org)
    AND (a.organization_id IS NULL OR a.organization_id = v_org);
  PERFORM d.id FROM public.auto_campaign_input_data d
  WHERE d.campaign_id = p_campaign_id AND d.id = ANY(v_optimistic_ids)
  ORDER BY d.id FOR UPDATE OF d;

  SELECT c.runtime_claim_token, c.runtime_claim_target, c.runtime_claim_vietnam_date, c.runtime_claimed_at,
    c.runtime_unit_token, c.runtime_unit_vietnam_date, c.runtime_unit_claimed_at, c.runtime_unit_input_data_ids,
    c.status, a.status, a.runtime_operation_claim_token
  INTO v_parent, v_target, v_claim_date, v_claim_at, v_unit, v_unit_date, v_unit_at, v_ids,
    v_campaign_status, v_account_status, v_account_token
  FROM public.auto_campaigns c JOIN public.auto_accounts a ON a.id = c.account_id AND a.staff_id = c.staff_id
  WHERE c.id = p_campaign_id AND c.account_id = p_account_id AND c.staff_id = p_staff_id
    AND (c.organization_id IS NULL OR c.organization_id = v_org)
    AND (a.organization_id IS NULL OR a.organization_id = v_org)
  FOR UPDATE OF c, a;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found'; RETURN;
  END IF;

  IF (v_parent IS NOT NULL AND v_parent <> p_runtime_claim_token)
    OR (v_account_token IS NOT NULL AND v_account_token <> p_runtime_claim_token)
    OR (v_unit IS NOT NULL AND v_unit IS DISTINCT FROM p_runtime_unit_token)
    OR (v_parent IS NOT NULL AND v_target IS DISTINCT FROM p_runtime_target)
  THEN
    RETURN QUERY SELECT false, 'not_owner'; RETURN;
  END IF;
  IF v_ids IS DISTINCT FROM v_optimistic_ids
    OR (v_parent IS NOT NULL AND (v_claim_date IS NULL OR v_claim_at IS NULL))
    OR (v_parent IS NULL AND (v_target IS NOT NULL OR v_claim_date IS NOT NULL OR v_claim_at IS NOT NULL))
    OR (v_unit IS NOT NULL AND (v_unit_date IS NULL OR v_unit_at IS NULL OR v_ids IS NULL OR cardinality(v_ids) > 50))
    OR (v_unit IS NULL AND (v_unit_date IS NOT NULL OR v_unit_at IS NOT NULL OR v_ids IS NOT NULL))
    OR (v_campaign_status = 'đang chạy' AND v_parent IS DISTINCT FROM p_runtime_claim_token)
    OR (v_account_status = 'đang chạy' AND v_account_token IS DISTINCT FROM p_runtime_claim_token)
  THEN
    RETURN QUERY SELECT false, 'insufficient_ownership'; RETURN;
  END IF;
  IF v_parent IS NULL AND v_unit IS NULL AND v_account_token IS NULL THEN
    -- A committed response can be lost. This branch performs no writes and
    -- cannot release a new owner, including a tokenless legacy running row.
    RETURN QUERY SELECT true, 'already_cleaned'; RETURN;
  END IF;
  IF v_unit IS NOT NULL AND NOT (v_unstarted <@ v_ids) THEN
    RETURN QUERY SELECT false, 'invalid_unstarted_ids'; RETURN;
  END IF;
  IF v_unit IS NULL AND cardinality(v_unstarted) > 0 THEN
    RETURN QUERY SELECT false, 'insufficient_ownership'; RETURN;
  END IF;

  -- A durable pause hint arriving while budget cleanup waits must win too.
  IF coalesce(p_campaign_status,'chờ xử lý')='chờ xử lý' AND private.facebook_random_pause_requested(p_campaign_id,p_account_id,p_runtime_claim_token) THEN
    p_campaign_status:='tạm dừng';
    IF coalesce(p_note,'')='' THEN p_note:='Đang chờ tạm dừng'; END IF;
  END IF;
  IF v_unit IS NOT NULL THEN
    UPDATE public.auto_campaign_input_data d
    SET status = CASE WHEN d.id = ANY(v_unstarted) THEN 'chờ xử lý' ELSE 'hoàn thành' END,
      date_action = CASE WHEN d.id = ANY(v_unstarted) THEN NULL ELSE d.date_action END,
      note = CASE WHEN d.id = ANY(v_unstarted) THEN d.note
        ELSE left(COALESCE(p_note, 'Lượt chạy bị gián đoạn'), 2000) || ' — Kết quả chưa xác nhận; không tự gửi lại.' END
    WHERE d.campaign_id = p_campaign_id AND d.id = ANY(v_ids)
      AND (d.status = 'đang chạy' OR (d.status = 'chờ xử lý' AND NOT (d.id = ANY(v_unstarted))));
    -- An inner error/pause handler may have requeued a started input before its
    -- next write failed. Its still-owned lease proves it cannot be sent again.
    -- Already paused/completed inputs are deliberately untouched.
    PERFORM private.facebook_random_unit_settled(p_campaign_id,p_account_id,p_runtime_unit_token,p_pause_unknown_outcome);
    UPDATE public.auto_campaigns c
    SET runtime_unit_token = NULL, runtime_unit_vietnam_date = NULL,
      runtime_unit_claimed_at = NULL, runtime_unit_input_data_ids = NULL, updated_at = v_now
    WHERE c.id = p_campaign_id AND c.runtime_unit_token = p_runtime_unit_token;
  END IF;

  IF v_parent = p_runtime_claim_token THEN
    UPDATE public.auto_campaigns c
    SET status = CASE WHEN p_pause_unknown_outcome THEN 'tạm dừng' ELSE COALESCE(p_campaign_status, 'chờ xử lý') END,
      note = left(COALESCE(p_note, 'Lượt chạy bị gián đoạn'), 2000)
        || CASE WHEN p_pause_unknown_outcome THEN ' — Chưa xác định phần đã thực hiện; tạm dừng để kiểm tra.' ELSE '' END,
      updated_at = v_now
    WHERE c.id = p_campaign_id AND c.runtime_claim_token = p_runtime_claim_token AND c.status = 'đang chạy';
    -- The existing server pause trigger preserves the parent tuple on a status
    -- transition. Clear it separately, under the same row lock/transaction.
    UPDATE public.auto_campaigns c
    SET runtime_claim_token = NULL, runtime_claim_target = NULL,
      runtime_claim_vietnam_date = NULL, runtime_claimed_at = NULL, updated_at = v_now
    WHERE c.id = p_campaign_id AND c.runtime_claim_token = p_runtime_claim_token;
  END IF;
  IF v_account_token = p_runtime_claim_token THEN
    UPDATE public.auto_accounts a
    SET status = CASE WHEN a.status = 'đang chạy' THEN COALESCE(p_account_status, 'chờ xử lý') ELSE a.status END,
      runtime_operation_claim_token = NULL, updated_at = v_now
    WHERE a.id = p_account_id AND a.staff_id = p_staff_id
      AND a.runtime_operation_claim_token = p_runtime_claim_token;
  END IF;
  RETURN QUERY SELECT true, 'cleaned';
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_create_campaign_creation_bundle(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_expected_campaign_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bundle public.auto_campaign_creation_bundles%ROWTYPE;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
    OR p_expected_campaign_count NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'invalid_campaign_creation_bundle';
  END IF;

  INSERT INTO public.auto_campaign_creation_bundles (
    request_id, expected_campaign_count, ready_campaign_count,
    status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), p_expected_campaign_count, 0,
    'staged', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_bundle;
  IF NOT FOUND THEN
    SELECT * INTO v_bundle
    FROM public.auto_campaign_creation_bundles AS bundle
    WHERE bundle.staff_id = p_staff_id
      AND bundle.organization_id = p_organization_id
      AND bundle.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_bundle.expected_campaign_count <> p_expected_campaign_count THEN
      RAISE EXCEPTION 'campaign_creation_bundle_request_conflict';
    END IF;
  END IF;
  RETURN to_jsonb(v_bundle);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_data_group_external_sync(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_source public.auto_data_group_external_sync_sources%ROWTYPE;
  v_config jsonb; v_type_id bigint; v_type text; v_end date; v_hours integer; v_enabled boolean;
  v_result jsonb; v_hash text; v_id bigint;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR COALESCE(p_data->>'groupId','') !~ '^[1-9][0-9]{0,17}$' THEN RAISE EXCEPTION 'sheet_sync_config'; END IF;
  -- The same group-first lock order is used by mutations, claims and ingestion.
  SELECT * INTO v_group FROM public.auto_account_contact_groups
    WHERE id=(p_data->>'groupId')::bigint AND staff_id=p_staff_id AND organization_id=p_organization_id
      AND purpose='data_group' AND NOT is_delete;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;
  IF p_action IN ('save','toggle','delete') THEN
    SELECT * INTO v_group FROM public.auto_account_contact_groups WHERE id=v_group.id AND NOT is_delete FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;
  END IF;
  IF p_action='check' THEN RETURN jsonb_build_object('ok',true); END IF;
  IF p_action='list' THEN
    RETURN jsonb_build_object('sources',COALESCE((SELECT jsonb_agg(to_jsonb(s)-'staff_id'-'organization_id'-'create_request_id'-'create_request_hash'-'run_token'
      ORDER BY s.id) FROM public.auto_data_group_external_sync_sources s WHERE s.group_id=v_group.id AND NOT s.is_delete),'[]'::jsonb),
      'runs',COALESCE((SELECT jsonb_agg(to_jsonb(r)-'token'-'staff_id'-'organization_id'-'result' ORDER BY r.id DESC)
        FROM (SELECT * FROM public.auto_data_group_external_sync_runs WHERE group_id=v_group.id ORDER BY id DESC LIMIT 30) r),'[]'::jsonb));
  END IF;
  IF p_action IN ('save','preview') THEN
    v_config:=p_data->'config'; PERFORM public.aka_agent_sheet_validate_config(v_config);
    v_type:=v_config->>'dataTypeCode';
    SELECT ci.id INTO v_type_id FROM public.category_item ci JOIN public.category_type ct ON ct.id=ci.category_type_id
      WHERE ct.namespace='common' AND ct.code='data_type' AND ci.code=v_type AND ci.is_active AND ct.is_active;
    IF v_type_id IS NULL OR (v_group.data_type_category_item_id IS NOT NULL AND v_group.data_type_category_item_id<>v_type_id)
      OR (v_group.bound_zalo_account_id IS NOT NULL AND (v_type NOT IN ('zalo_person','zalo_group') OR
        NOT public.aka_agent_data_group_account_available(v_group.bound_zalo_account_id,p_staff_id,p_organization_id)))
    THEN RAISE EXCEPTION 'sheet_sync_type'; END IF;
  END IF;
  IF p_action='preview' THEN
    v_result:=public.aka_agent_sheet_classify(v_group.id,v_type,p_data->'rows');
    RETURN v_result-'rows'-'keys';
  END IF;
  IF p_action='save' THEN
    IF COALESCE(p_data->>'requestId','') !~ '^[A-Za-z0-9_-]{1,100}$' OR length(btrim(COALESCE(p_data->>'name',''))) NOT BETWEEN 1 AND 200
      OR COALESCE(p_data->>'everyHours','') !~ '^[0-9]{1,4}$' OR jsonb_typeof(p_data->'isEnabled') IS DISTINCT FROM 'boolean'
    THEN RAISE EXCEPTION 'sheet_sync_config'; END IF;
    v_hours:=(p_data->>'everyHours')::integer; v_end:=NULLIF(p_data->>'endDate','')::date;
    v_enabled:=(p_data->>'isEnabled')::boolean;
    IF v_hours NOT BETWEEN 1 AND 8760 THEN RAISE EXCEPTION 'sheet_sync_config'; END IF;
    IF v_enabled AND v_end<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date THEN RAISE EXCEPTION 'sheet_sync_expired'; END IF;
    v_hash:=md5((p_data-'requestId')::text);
    IF p_data->>'id' IS NULL THEN
      SELECT * INTO v_source FROM public.auto_data_group_external_sync_sources
        WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND create_request_id=p_data->>'requestId';
      IF FOUND THEN
        IF v_source.create_request_hash<>v_hash OR v_source.is_delete THEN RAISE EXCEPTION 'sheet_sync_conflict'; END IF;
        RETURN to_jsonb(v_source)-'staff_id'-'organization_id'-'create_request_id'-'create_request_hash'-'run_token';
      ELSE
        INSERT INTO public.auto_data_group_external_sync_sources(group_id,staff_id,organization_id,create_request_id,create_request_hash,name,config,
          data_type_category_item_id,source_account_id,every_hours,end_date,is_enabled,status,next_run_at)
        VALUES(v_group.id,p_staff_id,p_organization_id,p_data->>'requestId',v_hash,btrim(p_data->>'name'),v_config,
          v_type_id,v_group.bound_zalo_account_id,v_hours,v_end,v_enabled,CASE WHEN v_enabled THEN 'pending' ELSE 'paused' END,now()) RETURNING * INTO v_source;
      END IF;
    ELSE
      UPDATE public.auto_data_group_external_sync_sources SET name=btrim(p_data->>'name'),config=v_config,
        data_type_category_item_id=v_type_id,source_account_id=v_group.bound_zalo_account_id,every_hours=v_hours,end_date=v_end,
        is_enabled=v_enabled,status=CASE WHEN v_enabled THEN 'pending' ELSE 'paused' END,next_run_at=now(),
        revision=revision+1,run_token=NULL,last_error=NULL,failure_count=0,updated_at=now()
      WHERE id=(p_data->>'id')::bigint AND group_id=v_group.id AND NOT is_delete AND revision=(p_data->>'expectedRevision')::bigint RETURNING * INTO v_source;
      IF NOT FOUND THEN RAISE EXCEPTION 'sheet_sync_conflict'; END IF;
    END IF;
    UPDATE public.auto_data_group_external_sync_runs SET status='cancelled',finished_at=now(),error='Nguồn đã được cấu hình lại.'
      WHERE source_id=v_source.id AND status='running';
    RETURN to_jsonb(v_source)-'staff_id'-'organization_id'-'create_request_id'-'create_request_hash'-'run_token';
  END IF;
  IF p_action IN ('toggle','delete') THEN
    SELECT * INTO v_source FROM public.auto_data_group_external_sync_sources WHERE id=(p_data->>'id')::bigint AND group_id=v_group.id AND NOT is_delete FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'sheet_sync_not_found'; END IF;
    IF v_source.revision IS DISTINCT FROM (p_data->>'expectedRevision')::bigint THEN RAISE EXCEPTION 'sheet_sync_conflict'; END IF;
    v_enabled:=p_action='toggle' AND COALESCE((p_data->>'enabled')::boolean,false);
    IF v_enabled AND v_source.status='error' THEN RAISE EXCEPTION 'sheet_sync_requires_save'; END IF;
    IF v_enabled AND v_source.end_date<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date THEN RAISE EXCEPTION 'sheet_sync_expired'; END IF;
    IF v_enabled AND (v_group.bound_zalo_account_id IS DISTINCT FROM v_source.source_account_id
      OR (v_group.data_type_category_item_id IS NOT NULL AND v_group.data_type_category_item_id<>v_source.data_type_category_item_id)) THEN RAISE EXCEPTION 'sheet_sync_type'; END IF;
    UPDATE public.auto_data_group_external_sync_sources SET is_enabled=v_enabled,is_delete=p_action='delete',revision=revision+1,
      status=CASE WHEN v_enabled THEN 'pending' ELSE 'paused' END,next_run_at=now(),run_token=NULL,last_error=NULL,failure_count=0,updated_at=now() WHERE id=v_source.id;
    UPDATE public.auto_data_group_external_sync_runs SET status='cancelled',finished_at=now(),error='Nguồn đã được tắt hoặc thay đổi.' WHERE source_id=v_source.id AND status='running';
    RETURN jsonb_build_object('ok',true);
  END IF;
  RAISE EXCEPTION 'sheet_sync_config';
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_delete_data_group_with_options(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_request_id text, p_detach_automations boolean, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_result jsonb;
  v_request_hash text;
  v_detached_count integer := 0;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );

  IF p_group_id IS NULL OR p_group_id <= 0
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_data_group_delete_request';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'delete_group',
    'groupId', p_group_id,
    'detachAutomations', COALESCE(p_detach_automations, false)
  )::text);

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status,
    staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'delete_group', p_group_id, v_request_hash,
    'processing', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT * INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;

    IF v_batch.operation <> 'delete_group'
      OR v_batch.group_id IS DISTINCT FROM p_group_id
      OR v_batch.request_hash <> v_request_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN
      RETURN v_batch.result;
    END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  -- The implementation overload owns the atomic group/source/membership
  -- lifecycle. Passing NULL avoids creating a second idempotency row because
  -- this wrapper already records the option as part of its request hash.
  v_result := public.aka_agent_delete_data_group(
    p_staff_id, p_organization_id, p_group_id, NULL
  );

  IF COALESCE(p_detach_automations, false) THEN
    UPDATE public.auto_automation AS automation
    SET target_data_group_id = NULL,
        updated_at = clock_timestamp()
    WHERE automation.staff_id = p_staff_id
      AND automation.organization_id = p_organization_id
      AND automation.target_data_group_id = p_group_id
      AND COALESCE(automation.is_delete, false) = false;
    GET DIAGNOSTICS v_detached_count = ROW_COUNT;
  END IF;

  v_result := COALESCE(v_result, '{}'::jsonb) || jsonb_build_object(
    'detach_automations', COALESCE(p_detach_automations, false),
    'detached_automation_count', v_detached_count
  );

  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = v_result, updated_at = clock_timestamp()
  WHERE id = v_batch.id;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_desktop_campaign_detail(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_access jsonb, p_campaign_id bigint, p_part text, p_cursor jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_row jsonb; v_version text; v_log text; v_updated_at timestamptz;
  v_tail text; v_length integer; v_end integer; v_prefix text; v_keep integer;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF p_staff_id IS NULL OR p_organization_id IS NULL OR p_access IS NULL OR p_campaign_id IS NULL OR p_campaign_id <= 0 OR p_part NOT IN ('config','log') OR p_part IS NULL THEN
    RAISE EXCEPTION 'Invalid campaign detail scope';
  END IF;
  IF p_part='config' THEN
    SELECT jsonb_build_object('id',c.id,'name',c.name,'action_id',c.action_id,'account_id',c.account_id,'secondary_account_id',c.secondary_account_id,'status',c.status,'schedule',c.schedule,'original_schedule',c.original_schedule,'schedule_type',c.schedule_type,'schedule_end_date',c.schedule_end_date,'daily_stop_time',c.daily_stop_time,'schedule_days',c.schedule_days,'schedule_week_days',c.schedule_week_days,'continue_next_day',c.continue_next_day,'refresh_data',c.refresh_data,'content',c.content,'extra_settings',c.extra_settings,'images',c.images,'note',c.note,'is_delete',c.is_delete,'staff_id',c.staff_id,'organization_id',c.organization_id,'created_at',c.created_at,'updated_at',c.updated_at,'completed_at',c.completed_at,'last_run_at',c.last_run_at,'data_target_source_mode',c.data_target_source_mode,'data_group_id',c.data_group_id,'provisioning_state',c.provisioning_state,'creation_bundle_id',c.creation_bundle_id,'creation_bundle_child_index',c.creation_bundle_child_index,'primary_account',jsonb_build_object('name',a.name,'flatform_type',a.flatform_type,'is_zalo_show_web',a.is_zalo_show_web,'is_zalo_server',a.is_zalo_server),'auto_campaign_actions',jsonb_build_object('name',ca.name)),public.aka_agent_desktop_campaign_config_version(c) INTO v_row,v_version
    FROM public.auto_campaigns c
    LEFT JOIN public.auto_campaign_actions ca ON ca.id=c.action_id
    JOIN public.auto_accounts a ON a.id = c.account_id
      AND a.staff_id = p_staff_id AND a.organization_id = p_organization_id
    WHERE c.staff_id = p_staff_id AND c.organization_id = p_organization_id AND c.is_delete = false
      AND coalesce((p_access->>CASE
        WHEN c.action_id IN ('sms_send','voice_call') THEN 'sms'
        WHEN c.action_id='email_send' THEN 'email'
        WHEN c.action_id = ANY(ARRAY['zalo_message_phone','zalo_message_friend','zalo_message_birthday','zalo_message_group_member','zalo_message_group_realtime','zalo_message_remarketing_customer','zalo_message_friend_recommendation','zalo_message_group','zalo_add_group_member','zalo_join_group_link','zalo_cancel_sent_friend_request']) THEN 'zalo'
        WHEN c.action_id IN ('facebook_page_post','facebook_page_to_message') THEN 'facebookFanpage'
        ELSE 'facebookCore' END)::boolean,false)
      AND (a.flatform_type<>'zalo' OR coalesce((p_access->>CASE WHEN a.is_zalo_show_web IS TRUE THEN 'web' WHEN a.is_zalo_server IS TRUE THEN 'server' ELSE 'qr' END)::boolean,false))
      AND c.id=p_campaign_id;
    RETURN CASE WHEN v_row IS NULL THEN NULL ELSE jsonb_build_object('row',v_row,'version',v_version) END;
  END IF;
  IF p_cursor IS NOT NULL AND (jsonb_typeof(p_cursor)<>'object'
    OR coalesce(p_cursor->>'version','') !~ '^[a-f0-9]{32}$'
    OR coalesce(p_cursor->>'length','') !~ '^[0-9]{1,7}$'
    OR jsonb_typeof(p_cursor->'tail') IS DISTINCT FROM 'string'
    OR char_length(p_cursor->>'tail')>1024) THEN
    RAISE EXCEPTION 'Invalid campaign log cursor';
  END IF;
  SELECT h.data->>'log',(h.data->>'updatedAt')::timestamptz INTO v_log,v_updated_at
  FROM public.auto_campaigns c
  CROSS JOIN LATERAL (SELECT private.campaign_log_legacy(c.id) AS data) h
    LEFT JOIN public.auto_campaign_actions ca ON ca.id=c.action_id
    JOIN public.auto_accounts a ON a.id = c.account_id
      AND a.staff_id = p_staff_id AND a.organization_id = p_organization_id
    WHERE c.staff_id = p_staff_id AND c.organization_id = p_organization_id AND c.is_delete = false
      AND coalesce((p_access->>CASE
        WHEN c.action_id IN ('sms_send','voice_call') THEN 'sms'
        WHEN c.action_id='email_send' THEN 'email'
        WHEN c.action_id = ANY(ARRAY['zalo_message_phone','zalo_message_friend','zalo_message_birthday','zalo_message_group_member','zalo_message_group_realtime','zalo_message_remarketing_customer','zalo_message_friend_recommendation','zalo_message_group','zalo_add_group_member','zalo_join_group_link','zalo_cancel_sent_friend_request']) THEN 'zalo'
        WHEN c.action_id IN ('facebook_page_post','facebook_page_to_message') THEN 'facebookFanpage'
        ELSE 'facebookCore' END)::boolean,false)
      AND (a.flatform_type<>'zalo' OR coalesce((p_access->>CASE WHEN a.is_zalo_show_web IS TRUE THEN 'web' WHEN a.is_zalo_server IS TRUE THEN 'server' ELSE 'qr' END)::boolean,false))
      AND c.id=p_campaign_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  v_version:=md5(v_log);
  IF v_version=p_cursor->>'version' THEN
    RETURN jsonb_build_object('mode','unchanged','version',v_version,'updatedAt',v_updated_at);
  END IF;
  -- A rolling log can drop its oldest entries. Locate the old suffix, retain
  -- the overlap and send only a small new prefix plus the appended text. The
  -- caller MUST verify the reconstructed MD5 and refetch without a cursor if
  -- an anchor is ambiguous, the log was replaced or a concurrent edit occurred.
  v_tail:=p_cursor->>'tail';
  v_length:=(p_cursor->>'length')::integer;
  IF char_length(v_tail)>0 AND char_length(v_tail)<=v_length THEN
    v_end:=strpos(v_log,v_tail);
    IF v_end>0 THEN
      v_end:=v_end+char_length(v_tail)-1;
      v_prefix:=left(v_log,least(256,v_end));
      v_keep:=v_end-char_length(v_prefix);
      IF v_keep>=0 AND v_keep<=v_length THEN
        RETURN jsonb_build_object('mode','delta','version',v_version,'updatedAt',v_updated_at,
          'prefix',v_prefix,'keepChars',v_keep,'append',substr(v_log,v_end+1));
      END IF;
    END IF;
  END IF;
  RETURN jsonb_build_object('mode','replace','version',v_version,'updatedAt',v_updated_at,'log',v_log);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_device_presence(p_username text, p_password text, p_instance_id uuid, p_device jsonb, p_ended boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE s public.org_staff%ROWTYPE; stamp timestamptz;
BEGIN
  IF p_instance_id IS NULL OR p_ended IS NULL OR jsonb_typeof(p_device) IS DISTINCT FROM 'object'
     OR coalesce(p_device->>'fingerprintHash','') !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid presence request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR UPDATE;
  IF NOT FOUND OR NOT s.is_active OR s.password IS DISTINCT FROM p_password THEN RETURN false; END IF;
  stamp := clock_timestamp();
  -- An end arriving before the first heartbeat inserts a tombstone. A late
  -- heartbeat cannot resurrect it; a new login always uses another instance_id.
  INSERT INTO public.auto_staff_device_presence AS presence
    (instance_id,staff_id,organization_id,device_fingerprint_hash,device_label,device_platform,app_version,started_at,last_seen_at,ended_at)
  VALUES (p_instance_id,s.id,s.organization_id,p_device->>'fingerprintHash',left(p_device->>'label',255),
    left(p_device->>'platform',20),left(p_device->>'appVersion',50),stamp,stamp,CASE WHEN p_ended THEN stamp END)
  ON CONFLICT (instance_id) DO UPDATE SET
    last_seen_at = CASE WHEN p_ended THEN presence.last_seen_at ELSE stamp END,
    ended_at = CASE WHEN p_ended THEN stamp ELSE NULL END
  WHERE presence.staff_id = s.id AND presence.organization_id = s.organization_id
    AND presence.device_fingerprint_hash = p_device->>'fingerprintHash' AND presence.ended_at IS NULL;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_duplicate_data_group(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_name text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source public.auto_account_contact_groups%ROWTYPE;
  v_target public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_request_hash text;
  v_member_count integer := 0;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  SELECT * INTO v_source
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;
  IF p_name IS NOT NULL AND length(btrim(p_name)) NOT BETWEEN 1 AND 255 THEN
    RAISE EXCEPTION 'invalid_data_group_name';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'duplicate_group', 'groupId', p_group_id,
    'name', COALESCE(NULLIF(btrim(COALESCE(p_name, '')), ''), v_source.name || ' (Bản sao)')
  )::text);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NOT NULL THEN
    INSERT INTO public.auto_data_ingest_batches (
      request_id, operation, group_id, request_hash, status, staff_id, organization_id
    ) VALUES (
      btrim(p_request_id), 'duplicate_group', p_group_id, v_request_hash, 'processing',
      p_staff_id, p_organization_id
    )
    ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
    RETURNING * INTO v_batch;
    IF NOT FOUND THEN
      SELECT * INTO v_batch
      FROM public.auto_data_ingest_batches
      WHERE staff_id = p_staff_id AND organization_id = p_organization_id
        AND request_id = btrim(p_request_id)
      FOR UPDATE;
      IF v_batch.operation <> 'duplicate_group' OR v_batch.request_hash <> v_request_hash THEN
        RAISE EXCEPTION 'data_group_request_id_conflict';
      END IF;
      IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
      RAISE EXCEPTION 'data_group_request_incomplete';
    END IF;
  END IF;

  INSERT INTO public.auto_account_contact_groups (
    account_id, contact_type, name, purpose, color, sort_order, revision,
    data_type_category_item_id, bound_zalo_account_id, dataset_sync_mode, dataset_sync_key, is_delete, staff_id, organization_id
  ) VALUES (
    NULL, NULL,
    COALESCE(NULLIF(btrim(COALESCE(p_name, '')), ''), v_source.name || ' (Bản sao)'),
    'data_group', v_source.color,
    COALESCE((
      SELECT max(contact_group.sort_order) + 1
      FROM public.auto_account_contact_groups AS contact_group
      WHERE contact_group.staff_id = p_staff_id
        AND contact_group.organization_id = p_organization_id
        AND contact_group.purpose = 'data_group'
        AND contact_group.is_delete = false
    ), 0),
    CASE WHEN EXISTS (
      SELECT 1 FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_source.id AND member.is_delete = false
    ) THEN 1 ELSE 0 END,
    v_source.data_type_category_item_id, v_source.bound_zalo_account_id, 'manual', NULL,
    false, p_staff_id, p_organization_id
  ) RETURNING * INTO v_target;

  INSERT INTO public.auto_account_contact_group_members (
    group_id, contact_id, is_delete, change_revision, created_at, updated_at
  )
  SELECT v_target.id, member.contact_id, false, v_target.revision, now(), now()
  FROM public.auto_account_contact_group_members AS member
  WHERE member.group_id = v_source.id AND member.is_delete = false;
  GET DIAGNOSTICS v_member_count = ROW_COUNT;

  INSERT INTO public.auto_account_contact_group_member_origins (
    membership_id, kind, dataset_id, batch_id, source_account_id, automation_detail_id,
    source_name_snapshot, relationship_kind, data_type_category_item_id, is_current, created_at, updated_at
  )
  SELECT
    target_member.id, origin.kind, origin.dataset_id, origin.batch_id,
    origin.source_account_id, origin.automation_detail_id,
    origin.source_name_snapshot, origin.relationship_kind, origin.data_type_category_item_id, true, now(), now()
  FROM public.auto_account_contact_group_members AS source_member
  JOIN public.auto_account_contact_group_members AS target_member
    ON target_member.group_id = v_target.id
   AND target_member.contact_id = source_member.contact_id
  JOIN public.auto_account_contact_group_member_origins AS origin
    ON origin.membership_id = source_member.id AND origin.is_current = true
  WHERE source_member.group_id = v_source.id AND source_member.is_delete = false
  ON CONFLICT DO NOTHING;

  PERFORM public.aka_agent_sync_copied_data_group_origins(
    source_member.id,
    target_member.id,
    true
  )
  FROM public.auto_account_contact_group_members AS source_member
  JOIN public.auto_account_contact_group_members AS target_member
    ON target_member.group_id = v_target.id
   AND target_member.contact_id = source_member.contact_id
  WHERE source_member.group_id = v_source.id
    AND source_member.is_delete = false
  ORDER BY source_member.id;

  IF v_batch.id IS NOT NULL THEN
    UPDATE public.auto_data_ingest_batches
    SET target_group_id = v_target.id,
        status = 'completed',
        result = to_jsonb(v_target) || public.aka_agent_data_type_json(v_target.data_type_category_item_id) || jsonb_build_object('active_membership_count', v_member_count),
        updated_at = now()
    WHERE id = v_batch.id
    RETURNING result INTO v_batch.result;
    RETURN v_batch.result;
  END IF;
  RETURN to_jsonb(v_target) || public.aka_agent_data_type_json(v_target.data_type_category_item_id) || jsonb_build_object('active_membership_count', v_member_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_facebook_account_operation(p_account_id bigint, p_staff_id bigint, p_previous_status text, p_claim_token uuid, p_generation bigint, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a public.auto_accounts%ROWTYPE; org_id bigint; result jsonb;
BEGIN
  IF p_account_id IS NULL OR p_account_id<=0 OR p_staff_id IS NULL OR p_staff_id<=0
    OR p_claim_token IS NULL OR p_generation IS NULL OR p_generation<0 OR p_generation>9007199254740991
    OR p_previous_status IS NULL OR p_previous_status NOT IN ('chờ xử lý','tạm dừng')
    OR p_action IS NULL OR p_action NOT IN ('claim','cleanup') THEN
    RAISE EXCEPTION 'invalid_facebook_operation_identity';
  END IF;
  -- Same staff -> account lock order as the existing claim, cleanup and recovery.
  -- Cleanup remains possible after staff deactivation/expiry or soft deletion.
  SELECT organization_id INTO org_id FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') WHERE id=p_staff_id ;
  IF NOT FOUND OR org_id IS NULL THEN
    RETURN CASE WHEN p_action='claim' THEN jsonb_build_object('claimed',false,'reason','staff_not_active')
      ELSE jsonb_build_object('ok',false,'reason','staff_not_found') END;
  END IF;
  SELECT * INTO a FROM public.auto_accounts WHERE id=p_account_id AND staff_id=p_staff_id
    AND (organization_id IS NULL OR organization_id=org_id) AND lower(btrim(coalesce(flatform_type,'')))='facebook'
    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN CASE WHEN p_action='claim' THEN jsonb_build_object('claimed',false,'reason','account_not_found')
      ELSE jsonb_build_object('ok',true,'reason','not_owner') END;
  END IF;
  IF p_action='claim' THEN
    -- The trigger increments once on acquisition. A retry may still observe
    -- that same owned token, but a closed generation can never acquire it again.
    IF a.facebook_login_claim_generation<>p_generation AND NOT (
      a.runtime_operation_claim_token IS NOT DISTINCT FROM p_claim_token
      AND a.facebook_login_claim_generation=p_generation+1) THEN
      RETURN jsonb_build_object('claimed',false,'reason','claim_closed');
    END IF;
    RETURN public.aka_agent_claim_account_operation(p_account_id,p_staff_id,'facebook','desktop',
      p_previous_status,p_claim_token,false,'operation');
  END IF;

  result:=public.aka_agent_cleanup_account_operation(p_account_id,p_staff_id,'facebook','desktop',
    p_previous_status,p_claim_token);
  IF coalesce((result->>'ok')::boolean,false) AND result->>'reason' IN ('cleaned','not_owner','already_cleaned') THEN
    -- If cleanup wins the row lock BEFORE claim, close its generation even
    -- though no token is present yet. Do not alter status or another token.
    UPDATE public.auto_accounts SET facebook_login_claim_generation=facebook_login_claim_generation+1
      WHERE id=p_account_id AND facebook_login_claim_generation=p_generation;
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_facebook_login(p_staff_id bigint, p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE
  access jsonb; org_id bigint; a public.auto_accounts%ROWTYPE;
  s public.auto_facebook_login_sessions%ROWTYPE; secret jsonb; result jsonb;
  reservation public.auto_facebook_login_imports%ROWTYPE;
  uid text; import_request uuid; account_id_input bigint; secret_id_input uuid;
  limit_value text; batch_limit integer:=10; account_limit integer; product_count integer; used_count integer;
BEGIN
  IF p_action IS NULL OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>2000000 THEN
    RAISE EXCEPTION 'facebook_invalid_input';
  END IF;
  access:=public.aka_agent_staff_access(p_staff_id,p_username,p_password);
  SELECT organization_id INTO org_id FROM public.org_staff WHERE id=p_staff_id;
  -- Cleanup/read-after-commit stay available to the same authenticated owner after entitlement expiry.
  IF p_action NOT IN ('abort','request_status') THEN
    IF NOT coalesce((access->>'isActive')::boolean,false) OR NOT coalesce((access->>'timeAllowed')::boolean,false) THEN
      RAISE EXCEPTION 'facebook_access_denied';
    END IF;
    SELECT count(*),CASE WHEN bool_or(max_accounts IS NULL OR max_accounts<=0) THEN NULL ELSE max(max_accounts) END
    INTO product_count,account_limit FROM public.org_organization_product
    WHERE organization_id=org_id AND product_id IN (3,10) AND is_deleted=false
      AND expiration_date >= (date_trunc('day',now() AT TIME ZONE 'Asia/Ho_Chi_Minh') AT TIME ZONE 'Asia/Ho_Chi_Minh');
    IF product_count=0 THEN RAISE EXCEPTION 'facebook_access_denied'; END IF;
  END IF;
  SELECT value INTO limit_value FROM public.auto_system_settings
    WHERE key='facebook.account_import.max_accounts_per_batch' AND is_active=true;
  IF limit_value ~ '^[0-9]{1,6}$' AND limit_value::integer>0 THEN batch_limit:=limit_value::integer; END IF;

  IF p_action='preview' THEN
    SELECT coalesce(jsonb_agg(DISTINCT facebook_uid),'[]') INTO result FROM public.auto_accounts
    WHERE staff_id=p_staff_id AND organization_id=org_id AND flatform_type='facebook' AND is_delete=false
      AND facebook_uid IN (SELECT jsonb_array_elements_text(p_data->'uids'));
    RETURN jsonb_build_object('limit',batch_limit,'duplicates',result);
  END IF;
  IF p_action='pending' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',i.account_id,'requestId',i.request_id)),'[]') INTO result
    FROM public.auto_facebook_login_imports i WHERE i.staff_id=p_staff_id AND i.organization_id=org_id
      AND i.created_at < now()-interval '5 minutes';
    RETURN result;
  END IF;
  IF p_action IN ('reserve','finish','abort','request_status') THEN
    import_request:=(p_data->>'requestId')::uuid;
    IF import_request IS NULL THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
    -- Serialize only account creation per staff, including quota check. UID is NOT a global constraint.
    PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR UPDATE;
    SELECT a1.* INTO a FROM public.auto_accounts a1 JOIN public.auto_facebook_login_sessions s1 ON s1.account_id=a1.id
      WHERE s1.import_request_id=import_request AND a1.staff_id=p_staff_id AND a1.organization_id=org_id;
    IF FOUND THEN
      SELECT * INTO s FROM public.auto_facebook_login_sessions WHERE account_id=a.id;
      RETURN jsonb_build_object('accountId',a.id,'state','ready','ready',true,'revision',s.revision);
    END IF;
    SELECT * INTO reservation FROM public.auto_facebook_login_imports
      WHERE request_id=(p_data->>'requestId')::uuid AND staff_id=p_staff_id AND organization_id=org_id FOR UPDATE;
    IF p_action='request_status' THEN
      IF reservation.account_id IS NULL THEN RETURN NULL; END IF;
      RETURN jsonb_build_object('accountId',reservation.account_id,'state','initializing');
    END IF;
    IF p_action='abort' THEN
      DELETE FROM public.auto_facebook_login_imports WHERE request_id=(p_data->>'requestId')::uuid AND staff_id=p_staff_id AND organization_id=org_id;
      RETURN jsonb_build_object('removed',true);
    END IF;
    IF p_action='reserve' AND reservation.account_id IS NOT NULL THEN
      RETURN jsonb_build_object('accountId',reservation.account_id,'state','initializing');
    END IF;
    IF (p_data->>'batchSize') IS NULL OR (p_data->>'batchSize')::integer NOT BETWEEN 1 AND batch_limit THEN RAISE EXCEPTION 'facebook_batch_limit'; END IF;
    secret:=p_data->'secret'; uid:=secret->>'uid';
    IF uid IS NULL OR uid !~ '^[0-9]{5,24}$' OR jsonb_typeof(secret->'cookies') IS DISTINCT FROM 'array'
      OR length(coalesce(secret->>'password',''))>1024 OR length(coalesce(secret->>'twoFactorSecret',''))>256
      OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(secret->'cookies') c WHERE c->>'name'='c_user' AND c->>'value'=uid)
      THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
    IF EXISTS(SELECT 1 FROM public.auto_accounts WHERE staff_id=p_staff_id AND flatform_type='facebook'
      AND is_delete=false AND facebook_uid=uid) THEN
      DELETE FROM public.auto_facebook_login_imports WHERE request_id=(p_data->>'requestId')::uuid AND staff_id=p_staff_id AND organization_id=org_id;
      RETURN jsonb_build_object('skipped',true);
    END IF;
    SELECT count(*) INTO used_count FROM public.auto_accounts WHERE staff_id=p_staff_id AND flatform_type='facebook' AND is_delete=false;
    IF account_limit IS NOT NULL AND used_count>=account_limit THEN RAISE EXCEPTION 'facebook_account_quota'; END IF;
    IF p_data->>'accountGroupId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.auto_account_groups
      WHERE id=(p_data->>'accountGroupId')::bigint AND staff_id=p_staff_id AND organization_id=org_id AND flatform_type='facebook' AND is_delete=false AND is_active=true) THEN
      RAISE EXCEPTION 'facebook_invalid_group'; END IF;
    IF p_data->>'proxyId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.auto_proxies
      WHERE id=(p_data->>'proxyId')::bigint AND staff_id=p_staff_id AND organization_id=org_id AND is_delete=false) THEN RAISE EXCEPTION 'facebook_invalid_proxy'; END IF;
    IF p_action='reserve' THEN
      INSERT INTO public.auto_facebook_login_imports(request_id,account_id,staff_id,organization_id)
        VALUES(import_request,nextval('public.auto_accounts_id_seq'),p_staff_id,org_id) RETURNING * INTO reservation;
      RETURN jsonb_build_object('accountId',reservation.account_id,'state','initializing');
    END IF;
    IF reservation.account_id IS NULL OR reservation.account_id IS DISTINCT FROM (p_data->>'accountId')::bigint THEN RAISE EXCEPTION 'facebook_conflict'; END IF;
    INSERT INTO public.auto_accounts(id,name,flatform_type,login_status,status,is_active,is_delete,staff_id,organization_id,
      account_group_id,proxy_id,is_zalo_show_web,is_zalo_server,facebook_uid,facebook_login_managed)
    OVERRIDING SYSTEM VALUE VALUES (reservation.account_id,coalesce(nullif(p_data->>'name',''),uid),'facebook','đã đăng nhập','chờ xử lý',true,false,p_staff_id,org_id,
      (p_data->>'accountGroupId')::bigint,(p_data->>'proxyId')::bigint,false,false,uid,true) RETURNING * INTO a;
    secret_id_input:=vault.create_secret(secret::text,'akaagent_facebook_'||a.id,'Facebook session managed by akaAgent');
    INSERT INTO public.auto_facebook_login_sessions(account_id,secret_id,import_request_id,last_verified_at)
      VALUES(a.id,secret_id_input,import_request,now());
    DELETE FROM public.auto_facebook_login_imports WHERE request_id=(p_data->>'requestId')::uuid AND staff_id=p_staff_id AND organization_id=org_id;
    RETURN jsonb_build_object('accountId',a.id,'state','ready','ready',true,'revision',1);
  END IF;

  account_id_input:=(p_data->>'accountId')::bigint;
  SELECT * INTO a FROM public.auto_accounts WHERE id=account_id_input AND staff_id=p_staff_id AND organization_id=org_id
    AND flatform_type='facebook' AND is_delete=false FOR UPDATE;
  IF NOT FOUND THEN
    IF p_action='abort' THEN RETURN jsonb_build_object('removed',true); END IF;
    RAISE EXCEPTION 'facebook_not_found';
  END IF;
  SELECT * INTO s FROM public.auto_facebook_login_sessions WHERE account_id=a.id FOR UPDATE;
  -- Existing manual accounts expose only metadata until an explicit verified login.
  IF p_action='metadata' AND s.account_id IS NULL THEN
    RETURN jsonb_build_object('uid',a.facebook_uid,'revision',0,
      'hasPassword',false,'hasTwoFactor',false,'hasCookie',false);
  END IF;
  IF p_action='login' THEN
    IF coalesce(s.revision,0) IS DISTINCT FROM (p_data->>'revision')::bigint THEN RAISE EXCEPTION 'facebook_conflict'; END IF;
    secret:=p_data->'secret'; uid:=secret->>'uid';
    IF jsonb_typeof(secret) IS DISTINCT FROM 'object' OR uid IS NULL OR uid !~ '^[0-9]{5,24}$'
      OR jsonb_typeof(secret->'cookies') IS DISTINCT FROM 'array'
      OR length(coalesce(secret->>'password','')) NOT BETWEEN 1 AND 1024
      OR length(coalesce(secret->>'twoFactorSecret','')) NOT BETWEEN 16 AND 256 THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(secret->'cookies') c WHERE c->>'name'='c_user' AND c->>'value'=uid)
      OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(secret->'cookies') c WHERE c->>'name'='xs' AND coalesce(c->>'value','')<>'')
      THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
    secret:=jsonb_build_object('uid',uid,'password',secret->>'password','twoFactorSecret',secret->>'twoFactorSecret','cookies',secret->'cookies');
    -- Reuse this account; duplicate UID filtering and creation quota belong to import only.
    IF s.account_id IS NULL THEN
      secret_id_input:=vault.create_secret(secret::text,'akaagent_facebook_'||a.id,'Facebook session managed by akaAgent');
      INSERT INTO public.auto_facebook_login_sessions(account_id,secret_id,import_request_id,last_verified_at)
        VALUES(a.id,secret_id_input,gen_random_uuid(),now()) RETURNING * INTO s;
    ELSE
      PERFORM vault.update_secret(s.secret_id,secret::text);
      UPDATE public.auto_facebook_login_sessions SET revision=revision+1,last_verified_at=now(),updated_at=now()
        WHERE account_id=a.id RETURNING * INTO s;
    END IF;
    UPDATE public.auto_accounts SET facebook_login_managed=true,facebook_uid=uid,login_status='đã đăng nhập',updated_at=now() WHERE id=a.id;
    RETURN jsonb_build_object('revision',s.revision);
  END IF;
  IF p_action='observe' AND s.account_id IS NULL THEN
    IF a.facebook_uid IS DISTINCT FROM (p_data->>'expectedUid') THEN RAISE EXCEPTION 'facebook_conflict'; END IF;
    IF p_data->>'state'='authenticated' THEN
      uid:=p_data->>'uid'; IF uid IS NULL OR uid !~ '^[0-9]{5,24}$' THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
      UPDATE public.auto_accounts SET facebook_uid=uid,login_status='đã đăng nhập',updated_at=now() WHERE id=a.id;
    ELSIF p_data->>'state' IN ('logged_out','challenge') THEN
      UPDATE public.auto_accounts SET login_status=CASE WHEN p_data->>'state'='challenge' THEN 'checkpoint' ELSE 'chưa đăng nhập' END,
        updated_at=now() WHERE id=a.id;
    END IF;
    RETURN jsonb_build_object('revision',0);
  END IF;
  IF s.account_id IS NULL THEN RAISE EXCEPTION 'facebook_not_managed'; END IF;
  SELECT decrypted_secret::jsonb INTO secret FROM vault.decrypted_secrets WHERE id=s.secret_id;
  IF p_action='get' THEN RETURN jsonb_build_object('secret',secret,'revision',s.revision); END IF;
  IF p_action='metadata' THEN RETURN jsonb_build_object('uid',secret->>'uid','revision',s.revision,
    'hasPassword',coalesce(secret->>'password','')<>'','hasTwoFactor',coalesce(secret->>'twoFactorSecret','')<>'',
    'hasCookie',jsonb_array_length(coalesce(secret->'cookies','[]'))>0); END IF;
  IF s.revision IS DISTINCT FROM (p_data->>'revision')::bigint THEN RAISE EXCEPTION 'facebook_conflict'; END IF;
  IF p_action='observe' THEN
    IF p_data->>'state'='authenticated' THEN
      uid:=p_data->>'uid';
      IF uid IS NULL OR uid !~ '^[0-9]{5,24}$' OR jsonb_typeof(p_data->'cookies') IS DISTINCT FROM 'array'
        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_data->'cookies') c WHERE c->>'name'='c_user' AND c->>'value'=uid)
        THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
      IF secret->>'uid' IS DISTINCT FROM uid THEN secret:=jsonb_build_object('uid',uid); END IF;
      secret:=secret||jsonb_build_object('cookies',p_data->'cookies');
      PERFORM vault.update_secret(s.secret_id,secret::text);
      UPDATE public.auto_accounts SET facebook_uid=uid,login_status='đã đăng nhập',updated_at=now() WHERE id=a.id;
      UPDATE public.auto_facebook_login_sessions SET revision=revision+1,last_verified_at=now(),updated_at=now() WHERE account_id=a.id;
    ELSIF p_data->>'state' IN ('logged_out','challenge') THEN
      UPDATE public.auto_accounts SET login_status=CASE WHEN p_data->>'state'='challenge' THEN 'checkpoint' ELSE 'chưa đăng nhập' END,
        updated_at=now() WHERE id=a.id;
    ELSE RAISE EXCEPTION 'facebook_invalid_input'; END IF;
  ELSIF p_action='save' THEN
    uid:=p_data->>'uid';
    IF uid IS NULL OR uid !~ '^[0-9]{5,24}$' THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
    IF coalesce(p_data->>'observedState','') NOT IN ('authenticated','logged_out') THEN RAISE EXCEPTION 'facebook_unverified'; END IF;
    IF length(coalesce(p_data->>'password',''))>1024 OR length(coalesce(p_data->>'twoFactorSecret',''))>256 THEN RAISE EXCEPTION 'facebook_invalid_input'; END IF;
    IF p_data->>'observedState'='authenticated' AND uid IS DISTINCT FROM (p_data->>'observedUid') THEN RAISE EXCEPTION 'facebook_uid_mismatch'; END IF;
    IF secret->>'uid' IS DISTINCT FROM uid THEN secret:=jsonb_build_object('uid',uid,'cookies','[]'::jsonb); END IF;
    IF p_data ? 'password' THEN secret:=secret||jsonb_build_object('password',p_data->>'password'); END IF;
    IF p_data ? 'twoFactorSecret' THEN secret:=secret||jsonb_build_object('twoFactorSecret',p_data->>'twoFactorSecret'); END IF;
    PERFORM vault.update_secret(s.secret_id,secret::text);
    UPDATE public.auto_facebook_login_sessions SET revision=revision+1,updated_at=now() WHERE account_id=a.id;
  ELSE RAISE EXCEPTION 'facebook_invalid_action'; END IF;
  SELECT revision INTO s.revision FROM public.auto_facebook_login_sessions WHERE account_id=a.id;
  RETURN jsonb_build_object('revision',s.revision);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_facebook_random_run(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_account_id bigint, p_operation text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE a public.auto_accounts%ROWTYPE; d public.auto_account_random_run_days%ROWTYPE;
 cfg jsonb; rev integer; rule jsonb; choice jsonb; turns jsonb; t jsonb; result jsonb; c record;
 day date:=timezone('Asia/Ho_Chi_Minh',clock_timestamp())::date;
 idx integer; round_no integer; row_no integer; total integer; page integer; claim uuid; turn_id uuid;
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF p_operation NOT IN ('get','save','toggle','dates','day','plan','claim','finish','progress') THEN RAISE EXCEPTION 'random_invalid_operation'; END IF;
 SELECT * INTO a FROM public.auto_accounts WHERE id=p_account_id AND staff_id=p_staff_id AND organization_id=p_organization_id AND flatform_type='facebook' AND NOT is_delete;
 IF NOT FOUND THEN RAISE EXCEPTION 'random_account_not_found'; END IF;
 -- Runtime claim must acquire staff/admission/campaign/account locks through v2 first.
 IF p_operation='claim' THEN
   claim:=(p_input->>'claimToken')::uuid;turn_id:=(p_input->>'turnId')::uuid;
   PERFORM set_config('aka.facebook_random_turn',turn_id::text,true);
   SELECT to_jsonb(r) INTO result FROM public.aka_agent_claim_campaign_runtime_v2((p_input->>'campaignId')::bigint,p_account_id,p_staff_id,'desktop',claim) r;
   PERFORM set_config('aka.facebook_random_turn','',true);
   IF (result->>'ok')::boolean THEN
     -- Existing exact-token retry is retained even after stop or midnight.
     SELECT * INTO d FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND run_date=(result->>'runtime_claim_vietnam_date')::date FOR UPDATE;
     SELECT x INTO t FROM jsonb_array_elements(d.state->'turns') x WHERE x->>'id'=turn_id::text AND (x->>'campaignId')::bigint=(p_input->>'campaignId')::bigint;
     IF t IS NULL OR (t->>'status'<>'planned' AND NOT(t->>'status'='running' AND t->>'claimToken'=claim::text)) THEN RAISE EXCEPTION 'random_turn_claim_mismatch'; END IF;
     UPDATE public.auto_account_random_run_days SET state=jsonb_set(state,ARRAY['turns',((t->>'order')::int-1)::text],
       t||jsonb_build_object('status','running','claimToken',claim,'startedAt',coalesce(t->'startedAt',result->'runtime_claimed_at'))),updated_at=clock_timestamp() WHERE id=d.id;
   END IF;
   RETURN result;
 END IF;
 IF p_operation IN ('save','toggle','plan','finish') THEN
   PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR SHARE;
   SELECT * INTO a FROM public.auto_accounts WHERE id=p_account_id AND staff_id=p_staff_id AND organization_id=p_organization_id AND NOT is_delete FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'random_account_not_found'; END IF;
 END IF;
 cfg:=a.facebook_random_run_config; rev:=coalesce((cfg->>'revision')::int,0);
 IF p_operation='save' THEN
   cfg:=p_input->'config';
   IF (cfg->>'revision')::int IS DISTINCT FROM rev THEN RAISE EXCEPTION 'random_config_conflict'; END IF;
   IF jsonb_typeof(cfg) IS DISTINCT FROM 'object' OR cfg->>'version' IS DISTINCT FROM '1' OR jsonb_typeof(cfg->'rules') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'random_invalid_config'; END IF;
   IF jsonb_array_length(cfg->'rules') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'random_invalid_rules'; END IF;
   FOR rule IN SELECT x FROM jsonb_array_elements(cfg->'rules') x LOOP
     IF jsonb_typeof(rule) IS DISTINCT FROM 'object' OR jsonb_typeof(rule->'quantity') IS DISTINCT FROM 'number'
       OR coalesce(rule->>'quantity','') !~ '^[1-9][0-9]*$' OR (rule->>'quantity')::numeric>2147483647
       OR rule->>'unit' IS DISTINCT FROM (CASE rule->>'campaignActionId' WHEN 'facebook_timeline_post' THEN 'run' WHEN 'facebook_newsfeed_interaction' THEN 'minute' ELSE 'data' END)
       OR (rule->>'campaignActionId'='facebook_timeline_post' AND rule->>'quantity'<>'1')
       OR NOT EXISTS(SELECT 1 FROM public.auto_campaign_actions ca WHERE ca.id=rule->>'campaignActionId' AND ca.flatform_type='facebook' AND ca.is_active AND NOT ca.is_delete)
     THEN RAISE EXCEPTION 'random_invalid_rule'; END IF;
   END LOOP;
   cfg:=jsonb_build_object('version',1,'revision',rev+1,'rules',cfg->'rules');
   UPDATE public.auto_accounts SET facebook_random_run_config=cfg,updated_at=clock_timestamp() WHERE id=p_account_id;
 ELSIF p_operation='toggle' THEN
   IF (p_input->>'revision')::int IS DISTINCT FROM rev THEN RAISE EXCEPTION 'random_config_conflict'; END IF;
   IF jsonb_typeof(p_input->'enabled') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'random_invalid_enabled'; END IF;
   IF (p_input->>'enabled')::boolean AND cfg IS NULL THEN RAISE EXCEPTION 'random_rules_required'; END IF;
   a.facebook_random_run_enabled:=(p_input->>'enabled')::boolean;
   UPDATE public.auto_accounts SET facebook_random_run_enabled=a.facebook_random_run_enabled,updated_at=clock_timestamp() WHERE id=p_account_id;
   IF NOT a.facebook_random_run_enabled THEN
     UPDATE public.auto_account_random_run_days dd SET state=jsonb_set(state,'{turns}',(
       SELECT jsonb_agg(CASE WHEN x->>'status'='planned' THEN x||jsonb_build_object('status','skipped','reason','Đã dừng chạy ngẫu nhiên','endedAt',clock_timestamp()) ELSE x END ORDER BY n)
       FROM jsonb_array_elements(dd.state->'turns') WITH ORDINALITY q(x,n))),updated_at=clock_timestamp()
     WHERE dd.account_id=p_account_id AND dd.status='open';
   END IF;
 END IF;
 IF p_operation IN ('get','save','toggle') THEN RETURN jsonb_build_object('enabled',a.facebook_random_run_enabled,'config',cfg); END IF;
 IF p_operation='dates' THEN
   RETURN coalesce((SELECT jsonb_agg(run_date ORDER BY run_date DESC) FROM (SELECT run_date FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND (p_input->>'before' IS NULL OR run_date<(p_input->>'before')::date) ORDER BY run_date DESC LIMIT 100) q),'[]');
 END IF;
 IF p_operation='day' THEN
   day:=(p_input->>'date')::date;page:=greatest(1,least(1000000,coalesce((p_input->>'page')::int,1)));
   SELECT * INTO d FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND run_date=day;
   SELECT count(*)::int INTO total FROM jsonb_array_elements(coalesce(d.state->'turns','[]')) x WHERE p_input->>'campaignId' IS NULL OR x->>'campaignId'=p_input->>'campaignId';
   SELECT coalesce(jsonb_agg(x ORDER BY n),'[]') INTO turns FROM (
     SELECT (x-'claimToken'-'unitToken'-'lastUnitToken')||CASE WHEN x->>'status'='running' AND x->>'unit'='minute' AND x->>'unitStartedAt' IS NOT NULL
       THEN jsonb_build_object('elapsedSeconds',least((x->>'quantity')::bigint*60,greatest(0,floor(extract(epoch FROM clock_timestamp()-(x->>'unitStartedAt')::timestamptz))))) ELSE '{}'::jsonb END x,n
     FROM jsonb_array_elements(coalesce(d.state->'turns','[]')) WITH ORDINALITY q(x,n)
     WHERE p_input->>'campaignId' IS NULL OR x->>'campaignId'=p_input->>'campaignId' ORDER BY n LIMIT 100 OFFSET (page-1)*100) q;
   RETURN jsonb_build_object('accountId',p_account_id,'date',day,'status',coalesce(d.status,'open'),'turns',turns,'total',total,'page',page);
 END IF;
 IF p_operation='progress' THEN
   SELECT x INTO t FROM public.auto_account_random_run_days dd, jsonb_array_elements(dd.state->'turns') x
   WHERE dd.account_id=p_account_id AND dd.status='open' AND x->>'claimToken'=p_input->>'claimToken' AND x->>'id'=p_input->>'turnId';
   IF t IS NULL THEN
     SELECT x INTO t FROM public.auto_account_random_run_days dd,jsonb_array_elements(dd.state->'turns') x
     WHERE dd.account_id=p_account_id AND dd.status='closed' AND x->>'claimToken'=p_input->>'claimToken' AND x->>'id'=p_input->>'turnId';
   END IF;
   IF t IS NULL THEN RAISE EXCEPTION 'random_turn_not_found'; END IF;
   RETURN t;
 END IF;
 IF p_operation='finish' THEN
   SELECT * INTO d FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND status='open'
     AND EXISTS(SELECT 1 FROM jsonb_array_elements(state->'turns') x WHERE x->>'id'=p_input->>'turnId') FOR UPDATE;
   IF NOT FOUND THEN
     SELECT * INTO d FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND status='closed'
       AND EXISTS(SELECT 1 FROM jsonb_array_elements(state->'turns') x WHERE x->>'id'=p_input->>'turnId') FOR UPDATE;
     IF NOT FOUND THEN RAISE EXCEPTION 'random_turn_not_found'; END IF;
   END IF;
   SELECT x INTO t FROM jsonb_array_elements(d.state->'turns') x WHERE x->>'id'=p_input->>'turnId';
   IF t->>'status' NOT IN ('planned','running') THEN RETURN t; END IF;
   IF t->>'claimToken' IS DISTINCT FROM p_input->>'claimToken' THEN RAISE EXCEPTION 'random_turn_not_owner'; END IF;
   IF EXISTS(SELECT 1 FROM public.auto_campaigns cc WHERE cc.account_id=p_account_id AND (cc.runtime_unit_token IS NOT NULL OR cc.runtime_claim_token IS NOT NULL OR cc.status='đang chạy')) THEN RAISE EXCEPTION 'random_runtime_still_owned'; END IF;
   t:=t||jsonb_build_object('status',CASE WHEN t->>'status'='planned' THEN 'skipped' WHEN p_input->>'reason' IS NOT NULL THEN 'stopped' ELSE 'completed' END,'reason',p_input->>'reason','endedAt',clock_timestamp());
   UPDATE public.auto_account_random_run_days SET state=jsonb_set(state,ARRAY['turns',((t->>'order')::int-1)::text],t),updated_at=clock_timestamp() WHERE id=d.id;
   IF d.run_date<day THEN
     UPDATE public.auto_account_random_run_days dd SET status='closed',state=jsonb_set(state,'{turns}',(
       SELECT jsonb_agg(CASE WHEN x->>'status'='planned' THEN x||jsonb_build_object('status','expired','reason','Hết ngày','endedAt',clock_timestamp()) ELSE x END ORDER BY n)
       FROM jsonb_array_elements(dd.state->'turns') WITH ORDINALITY q(x,n))) WHERE dd.id=d.id;
   END IF;
   RETURN t;
 END IF;
 -- Plan/recovery does not clear runtime ownership; wait until existing recovery/drain has done so.
 IF EXISTS(SELECT 1 FROM public.auto_campaigns cc WHERE cc.account_id=p_account_id AND (cc.runtime_unit_token IS NOT NULL OR cc.runtime_claim_token IS NOT NULL OR cc.status='đang chạy')) THEN
   RETURN jsonb_build_object('enabled',a.facebook_random_run_enabled,'config',cfg,'date',day,'turns','[]'::jsonb);
 END IF;
 FOR d IN SELECT * FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND status='open' ORDER BY run_date FOR UPDATE LOOP
   SELECT coalesce(jsonb_agg(CASE WHEN x->>'status'='planned' AND (d.run_date<day OR (x->>'revision')::int<>rev OR NOT a.facebook_random_run_enabled) THEN x||jsonb_build_object('status',CASE WHEN d.run_date<day THEN 'expired' ELSE 'skipped' END,'reason',CASE WHEN d.run_date<day THEN 'Hết ngày' WHEN NOT a.facebook_random_run_enabled THEN 'Đã dừng chạy ngẫu nhiên' ELSE 'Cấu hình đã thay đổi' END,'endedAt',clock_timestamp()) ELSE x END ORDER BY n),'[]') INTO turns
   FROM jsonb_array_elements(d.state->'turns') WITH ORDINALITY q(x,n);
   UPDATE public.auto_account_random_run_days SET state=jsonb_set(state,'{turns}',turns),status=CASE WHEN d.run_date<day AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(turns) x WHERE x->>'status'='running') THEN 'closed' ELSE 'open' END,updated_at=clock_timestamp() WHERE id=d.id;
 END LOOP;
 SELECT * INTO d FROM public.auto_account_random_run_days WHERE account_id=p_account_id AND run_date=day;
 SELECT coalesce(jsonb_agg(x ORDER BY n),'[]') INTO turns FROM jsonb_array_elements(coalesce(d.state->'turns','[]')) WITH ORDINALITY q(x,n) WHERE x->>'status'='planned';
 IF EXISTS(SELECT 1 FROM public.auto_account_random_run_days dd,jsonb_array_elements(dd.state->'turns') x WHERE dd.account_id=p_account_id AND dd.status='open' AND x->>'status'='running') THEN
   RETURN jsonb_build_object('enabled',a.facebook_random_run_enabled,'config',cfg,'date',day,'turns','[]'::jsonb);
 END IF;
 IF jsonb_array_length(turns)>0 OR NOT a.facebook_random_run_enabled OR cfg IS NULL OR (p_input->>'revision')::int IS DISTINCT FROM rev THEN
   RETURN jsonb_build_object('enabled',a.facebook_random_run_enabled,'config',cfg,'date',day,'turns',turns);
 END IF;
 IF a.status<>'chờ xử lý' OR NOT a.is_active OR a.login_status<>'đã đăng nhập' OR timezone('Asia/Ho_Chi_Minh',clock_timestamp())::time>=time '23:59' THEN
   RETURN jsonb_build_object('enabled',a.facebook_random_run_enabled,'config',cfg,'date',day,'turns','[]'::jsonb);
 END IF;
 turns:='[]';round_no:=coalesce((d.state->>'round')::int,0)+1;row_no:=jsonb_array_length(coalesce(d.state->'turns','[]'));
 IF jsonb_typeof(p_input->'choices') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'choices')>100 THEN RAISE EXCEPTION 'random_invalid_choices'; END IF;
 -- Server orders and validates every selected campaign against the saved rule snapshot.
 FOR choice IN SELECT x FROM jsonb_array_elements(p_input->'choices') x ORDER BY (x->>'ruleIndex')::int LOOP
   idx:=(choice->>'ruleIndex')::int;rule:=cfg->'rules'->idx;
   IF idx<0 OR rule IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(turns) x WHERE (x->>'ruleIndex')::int=idx) THEN RAISE EXCEPTION 'random_invalid_choice'; END IF;
   SELECT cc.* INTO c FROM public.auto_campaigns cc WHERE cc.id=(choice->>'campaignId')::bigint AND cc.account_id=p_account_id AND cc.staff_id=p_staff_id AND cc.organization_id=p_organization_id
     AND cc.action_id=rule->>'campaignActionId' AND NOT cc.is_delete AND cc.status='chờ xử lý'
     AND coalesce(cc.provisioning_state,'ready')='ready'
     AND private.campaign_dispatch_schedule_allowed(
       cc.schedule,cc.data_target_source_mode,cc.schedule_end_date,cc.daily_stop_time,clock_timestamp(),false);
   IF FOUND THEN
     row_no:=row_no+1;
     turns:=turns||jsonb_build_array(rule||jsonb_build_object('id',gen_random_uuid(),'order',row_no,'round',round_no,'ruleIndex',idx,'revision',rev,'campaignId',c.id,'campaignName',c.name,'processed',0,'elapsedSeconds',0,'status','planned'));
   END IF;
 END LOOP;
 IF jsonb_array_length(turns)>0 THEN
   INSERT INTO public.auto_account_random_run_days(account_id,staff_id,organization_id,run_date,state)
   VALUES(p_account_id,p_staff_id,p_organization_id,day,jsonb_build_object('round',round_no,'turns',turns,'configs',jsonb_build_object(rev::text,cfg)))
   ON CONFLICT(account_id,run_date) DO UPDATE SET state=jsonb_build_object('round',round_no,'turns',auto_account_random_run_days.state->'turns'||turns,'configs',coalesce(auto_account_random_run_days.state->'configs','{}')||jsonb_build_object(rev::text,cfg)),updated_at=clock_timestamp();
 END IF;
 RETURN jsonb_build_object('enabled',a.facebook_random_run_enabled,'config',cfg,'date',day,'turns',turns);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_facebook_web_enrichment_settings(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_account_id bigint, p_operation text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE a public.auto_accounts%ROWTYPE; cfg jsonb; rev integer; enabled boolean;
 key text; item jsonb; items jsonb; text_value text; authority text; url_path text; urls jsonb:='[]';
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF p_operation IS NULL OR p_operation NOT IN ('get','save') THEN RAISE EXCEPTION 'web_enrichment_operation'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id AND is_active) THEN RAISE EXCEPTION 'web_enrichment_identity'; END IF;
 IF p_operation='save' THEN PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR SHARE; END IF;
 SELECT * INTO a FROM public.auto_accounts WHERE id=p_account_id AND staff_id=p_staff_id
   AND organization_id=p_organization_id AND flatform_type='facebook' AND NOT is_delete;
 IF NOT FOUND THEN RAISE EXCEPTION 'web_enrichment_account'; END IF;
 IF p_operation='save' THEN
   SELECT * INTO a FROM public.auto_accounts WHERE id=p_account_id AND staff_id=p_staff_id
     AND organization_id=p_organization_id AND flatform_type='facebook' AND NOT is_delete FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'web_enrichment_account'; END IF;
 END IF;
 cfg:=a.facebook_web_enrichment_config; rev:=coalesce((cfg->>'revision')::integer,0);
 enabled:=a.facebook_web_enrichment_enabled;
 -- Reading and disabling remain available to the owning staff after entitlement expiry.
 IF p_operation='save' THEN
   IF jsonb_typeof(p_input->'enabled') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'web_enrichment_enabled'; END IF;
   enabled:=(p_input->>'enabled')::boolean; cfg:=p_input->'config';
   IF jsonb_typeof(cfg) IS DISTINCT FROM 'object' OR cfg->>'version' IS DISTINCT FROM '1'
     OR jsonb_typeof(cfg->'revision') IS DISTINCT FROM 'number' OR cfg->>'revision' !~ '^[0-9]+$'
     OR (cfg->>'revision')::numeric IS DISTINCT FROM rev THEN RAISE EXCEPTION 'web_enrichment_conflict'; END IF;
   IF rev=2147483647 OR octet_length(cfg::text)>100000 THEN RAISE EXCEPTION 'web_enrichment_size'; END IF;
   IF jsonb_typeof(cfg->'industry') IS DISTINCT FROM 'string' OR length(cfg->>'industry')>8000 THEN RAISE EXCEPTION 'web_enrichment_industry'; END IF;
   FOREACH key IN ARRAY ARRAY['keywords','websites','hobbies','slots'] LOOP
     items:=cfg->key;
     IF jsonb_typeof(items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'web_enrichment_list'; END IF;
     IF jsonb_array_length(items)>(CASE key WHEN 'keywords' THEN 200 WHEN 'websites' THEN 5 WHEN 'hobbies' THEN 100 ELSE 48 END)
       OR EXISTS(SELECT 1 FROM jsonb_array_elements(items) x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}')>2048) THEN RAISE EXCEPTION 'web_enrichment_list'; END IF;
     SELECT coalesce(jsonb_agg(v ORDER BY n),'[]') INTO items FROM (
       SELECT DISTINCT ON (CASE WHEN key='websites' THEN btrim(x#>>'{}') ELSE lower(btrim(x#>>'{}')) END) btrim(x#>>'{}') v,n FROM jsonb_array_elements(items) WITH ORDINALITY t(x,n)
       WHERE btrim(x#>>'{}')<>'' ORDER BY CASE WHEN key='websites' THEN btrim(x#>>'{}') ELSE lower(btrim(x#>>'{}')) END,n) q;
     cfg:=jsonb_set(cfg,ARRAY[key],items);
   END LOOP;
   IF enabled THEN
     IF NOT EXISTS(SELECT 1 FROM public.org_organization_product WHERE organization_id=p_organization_id AND NOT is_deleted
       AND product_id IN (3,10) AND expiration_date>=date_trunc('day',timezone('Asia/Ho_Chi_Minh',clock_timestamp())) AT TIME ZONE 'Asia/Ho_Chi_Minh') THEN
       RAISE EXCEPTION 'web_enrichment_feature'; END IF;
     IF btrim(cfg->>'industry')='' OR jsonb_array_length(cfg->'keywords')<3 OR jsonb_array_length(cfg->'websites')<>3
       OR jsonb_array_length(cfg->'slots')<1 THEN RAISE EXCEPTION 'web_enrichment_required'; END IF;
     IF jsonb_typeof(cfg->'minutesPerSession') IS DISTINCT FROM 'number' OR cfg->>'minutesPerSession' !~ '^[0-9]+$'
       OR (cfg->>'minutesPerSession')::numeric NOT BETWEEN 5 AND 240 OR (cfg->>'minutesPerSession')::numeric%5<>0 THEN RAISE EXCEPTION 'web_enrichment_minutes'; END IF;
     IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(cfg->'slots') x WHERE x !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') THEN RAISE EXCEPTION 'web_enrichment_slots'; END IF;
     IF cfg->>'stopDate' IS NOT NULL AND (cfg->>'stopDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR (cfg->>'stopDate')::date::text<>cfg->>'stopDate') THEN RAISE EXCEPTION 'web_enrichment_date'; END IF;
     FOR text_value IN SELECT jsonb_array_elements_text(cfg->'websites') LOOP
       IF text_value !~* '^[a-z][a-z0-9+.-]*:' OR text_value ~* '^[a-z0-9.-]+:[0-9]+([/?#]|$)' THEN text_value:='https://'||text_value; END IF;
       IF text_value !~* '^https?://[^/?#[:space:]@]+([/?#][^[:space:]]*)?$' THEN RAISE EXCEPTION 'web_enrichment_url'; END IF;
       authority:=lower(substring(text_value FROM '(?i)^https?://([^/?#]+)'));
       IF authority !~ '^([a-z0-9]([a-z0-9.-]*[a-z0-9])?|\[[0-9a-f:]+\])(:[0-9]{1,5})?$'
         OR (authority ~ ':[0-9]+$' AND substring(authority FROM ':([0-9]+)$')::integer NOT BETWEEN 1 AND 65535) THEN RAISE EXCEPTION 'web_enrichment_url'; END IF;
       url_path:=regexp_replace(text_value,'(?i)^https?://[^/?#]+',''); url_path:=split_part(url_path,'#',1);
       IF url_path='' OR left(url_path,1)='?' THEN url_path:='/'||url_path; END IF;
       text_value:=lower(split_part(text_value,'://',1))||'://'||authority||url_path;
       IF urls ? text_value THEN RAISE EXCEPTION 'web_enrichment_duplicate_url'; END IF;
       urls:=urls||jsonb_build_array(text_value);
     END LOOP;
     cfg:=jsonb_set(cfg,'{websites}',urls);
   END IF;
   cfg:=jsonb_build_object('version',1,'revision',rev+1,'industry',btrim(cfg->>'industry'),
     'keywords',cfg->'keywords','websites',cfg->'websites','hobbies',cfg->'hobbies',
     'minutesPerSession',CASE WHEN jsonb_typeof(cfg->'minutesPerSession')='number' THEN cfg->'minutesPerSession' ELSE '30'::jsonb END,
     'slots',(SELECT coalesce(jsonb_agg(x ORDER BY x),'[]') FROM jsonb_array_elements_text(cfg->'slots') x),'stopDate',cfg->'stopDate');
   UPDATE public.auto_accounts SET facebook_web_enrichment_enabled=enabled,facebook_web_enrichment_config=cfg,updated_at=clock_timestamp() WHERE id=p_account_id;
 END IF;
 RETURN jsonb_build_object('enabled',enabled,'config',cfg);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_finalize_contact_dataset(p_staff_id bigint, p_organization_id bigint, p_account_id bigint, p_scan_type text, p_contact_type text, p_source_key text, p_name text, p_link text, p_description text, p_status text, p_contact_uids text[], p_extra_data jsonb, p_data_type_category_item_id bigint DEFAULT NULL::bigint)
 RETURNS SETOF auto_account_contacts_dataset
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_previous_context text :=
    current_setting('aka_agent.data_type_category_item_id', true);
  v_flatform_type text;
  v_effective_data_type_category_item_id bigint :=
    p_data_type_category_item_id;
BEGIN
  SELECT lower(btrim(COALESCE(account.flatform_type, '')))
  INTO v_flatform_type
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND account.organization_id IS NOT DISTINCT FROM p_organization_id;

  IF v_effective_data_type_category_item_id IS NULL THEN
    v_effective_data_type_category_item_id :=
      public.aka_agent_derive_dataset_data_type(
        'scan',
        v_flatform_type,
        p_contact_type,
        p_scan_type,
        COALESCE(p_extra_data, '{}'::jsonb)
      );
  END IF;
  IF v_effective_data_type_category_item_id IS NULL THEN
    RAISE EXCEPTION 'scan_data_type_unresolved';
  END IF;
  IF NOT public.aka_agent_is_data_type_category_item(
    v_effective_data_type_category_item_id, true
  ) THEN
    RAISE EXCEPTION 'invalid_data_type_category_item';
  END IF;

  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    v_effective_data_type_category_item_id::text,
    true
  );
  RETURN QUERY
  SELECT *
  FROM public.aka_agent_finalize_contact_dataset_v205_internal(
    p_staff_id,
    p_organization_id,
    p_account_id,
    p_scan_type,
    p_contact_type,
    p_source_key,
    p_name,
    p_link,
    p_description,
    p_status,
    p_contact_uids,
    p_extra_data
  );
  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_previous_context, ''),
    true
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_previous_context, ''),
    true
  );
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_finalize_zalo_server_campaign(p_campaign_id bigint, p_staff_id bigint, p_note text, p_update_note boolean)
 RETURNS TABLE(ok boolean, reason text, campaign_id bigint, account_id bigint, campaign_status text, account_status text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_account_id bigint;
  v_campaign_status text;
  v_account_status text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Campaign and staff IDs must be positive integers';
  END IF;
  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_campaign_id, NULL::bigint, NULL::text, NULL::text;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Serialize the final pending-input decision with Control pause/resume and
  -- run-unit claims. The campaign/account lock is deliberately taken only
  -- after every live input row is stable for the rest of this transaction.
  PERFORM input_data.id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
  ORDER BY input_data.id
  FOR UPDATE OF input_data;

  SELECT campaign.account_id, campaign.status, account.status
  INTO v_account_id, v_campaign_status, v_account_status
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF campaign, account;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found', p_campaign_id, NULL::bigint, NULL::text, NULL::text;
    RETURN;
  END IF;

  IF v_campaign_status IS DISTINCT FROM 'đang chạy' THEN
    RETURN QUERY SELECT true, 'campaign_control_won', p_campaign_id, v_account_id, v_campaign_status, v_account_status;
    RETURN;
  END IF;
  IF v_account_status IS DISTINCT FROM 'đang chạy' THEN
    UPDATE public.auto_campaigns
    SET status = 'chờ xử lý', note = NULL, updated_at = now()
    WHERE id = p_campaign_id AND status = 'đang chạy';
    RETURN QUERY SELECT true, 'account_control_won', p_campaign_id, v_account_id, 'chờ xử lý', v_account_status;
    RETURN;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false
      AND input_data.status = 'chờ xử lý'
  ) THEN
    UPDATE public.auto_campaigns
    SET status = 'chờ xử lý', note = NULL, updated_at = now()
    WHERE id = p_campaign_id AND status = 'đang chạy';
    RETURN QUERY SELECT true, 'pending_input_remaining', p_campaign_id, v_account_id, 'chờ xử lý', v_account_status;
    RETURN;
  END IF;

  UPDATE public.auto_campaigns AS campaign
  SET status = 'hoàn thành',
    note = CASE WHEN COALESCE(p_update_note, false) THEN p_note ELSE campaign.note END,
    updated_at = now()
  WHERE campaign.id = p_campaign_id AND campaign.status = 'đang chạy';
  RETURN QUERY SELECT true, 'completed', p_campaign_id, v_account_id, 'hoàn thành', v_account_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_finalize_zalo_server_contact_dataset(p_staff_id bigint, p_organization_id bigint, p_account_id bigint, p_scan_type text, p_contact_type text, p_source_key text, p_name text, p_link text, p_description text, p_status text, p_contact_uids text[], p_extra_data jsonb, p_data_type_category_item_id bigint, p_claim_token uuid)
 RETURNS SETOF auto_account_contacts_dataset
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_capabilities record;
  v_expected_type bigint;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_claim_token IS NULL
  THEN
    RAISE EXCEPTION 'server_contact_dataset_claim_required';
  END IF;
  IF p_scan_type IS DISTINCT FROM 'zalo_group_members'
    OR p_contact_type IS DISTINCT FROM 'person'
  THEN
    RAISE EXCEPTION 'server_contact_dataset_scan_not_supported';
  END IF;

  -- Match claim lock order: staff, entitlement barrier, account.
  PERFORM 1 FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
    AND staff.organization_id = p_organization_id
    AND staff.is_active = true
  FOR SHARE OF staff;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'server_contact_dataset_staff_invalid';
  END IF;
  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(p_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
  THEN
    RAISE EXCEPTION 'server_contact_dataset_runtime_not_owner';
  END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND account.organization_id = p_organization_id
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF account;
  IF NOT FOUND
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
    OR v_account.is_zalo_server IS NOT TRUE
    OR v_account.is_zalo_show_web IS TRUE
    OR v_account.status IS DISTINCT FROM 'đang chạy'
    OR v_account.runtime_operation_claim_token IS DISTINCT FROM p_claim_token
  THEN
    RAISE EXCEPTION 'server_contact_dataset_claim_invalid';
  END IF;

  v_expected_type := public.aka_agent_data_type_category_item_id('zalo_person', true);
  IF v_expected_type IS NULL OR (p_data_type_category_item_id IS NOT NULL
    AND p_data_type_category_item_id <> v_expected_type)
  THEN
    RAISE EXCEPTION 'server_contact_dataset_data_type_invalid';
  END IF;

  -- Reuse the live v244 semantic core and v205 snapshot behavior. In particular,
  -- partial results merge, completed snapshots replace, and failed scans preserve members.
  RETURN QUERY SELECT * FROM public.aka_agent_finalize_contact_dataset(
    p_staff_id, p_organization_id, p_account_id,
    p_scan_type, p_contact_type, p_source_key, p_name, p_link, p_description,
    p_status, p_contact_uids, p_extra_data, v_expected_type
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_finalize_zalo_server_maintenance_campaign(p_staff_id bigint, p_organization_id bigint, p_expected_mode_revision text, p_campaign_id bigint, p_note text, p_update_note boolean)
 RETURNS TABLE(completed boolean, reason text, campaign_id bigint, campaign_status text, pending_input_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_authorized_campaign_id bigint;
  v_action_id text;
  v_schedule timestamptz;
  v_original_schedule timestamptz;
  v_schedule_type text;
  v_schedule_days text;
  v_schedule_week_days text;
  v_schedule_end_date timestamptz;
  v_schedule_time time without time zone;
  v_today date := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
  v_candidate_date date;
  v_next_schedule timestamptz;
  v_allowed_days integer[] := ARRAY[]::integer[];
  v_day_token text;
  v_day_numeric numeric;
  v_day_number integer;
  v_day_offset integer;
  v_is_birthday_maintenance boolean := false;
  v_is_schedule_end_maintenance boolean := false;
  v_maintenance_note text;
BEGIN
  PERFORM public.aka_agent_internal_require_zalo_server_runtime(
    p_staff_id,
    p_organization_id,
    p_expected_mode_revision
  );

  IF p_campaign_id IS NULL OR p_campaign_id <= 0 THEN
    RAISE EXCEPTION 'zalo_server_maintenance_campaign_invalid';
  END IF;

  -- Avoid locking rows for a local or cross-tenant campaign through this
  -- SECURITY DEFINER surface. The full schedule/candidate proof is repeated
  -- with campaign/account row locks after the input-first barrier.
  PERFORM campaign.id
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = p_organization_id
    )
    AND COALESCE(campaign.data_target_source_mode, 'direct') = 'direct'
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND (
      account.organization_id IS NULL
      OR account.organization_id = p_organization_id
    )
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND COALESCE(account.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false,
      'not_found',
      p_campaign_id,
      NULL::text,
      0::bigint;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Maintenance may complete the campaign based on its current input set.
  -- Stabilize that set before the schedule proof locks campaign/account.
  PERFORM input_data.id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
  ORDER BY input_data.id
  FOR UPDATE OF input_data;

  SELECT
    campaign.id,
    campaign.action_id,
    campaign.schedule,
    campaign.original_schedule,
    COALESCE(NULLIF(campaign.schedule_type, ''), 'daily'),
    campaign.schedule_days,
    campaign.schedule_week_days,
    campaign.schedule_end_date
  INTO
    v_authorized_campaign_id,
    v_action_id,
    v_schedule,
    v_original_schedule,
    v_schedule_type,
    v_schedule_days,
    v_schedule_week_days,
    v_schedule_end_date
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = p_organization_id
    )
    AND COALESCE(campaign.data_target_source_mode, 'direct') = 'direct'
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND campaign.schedule IS NOT NULL
    AND campaign.schedule < (
      date_trunc('day', now() AT TIME ZONE 'Asia/Ho_Chi_Minh')
      AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )
    AND campaign.status IN ('chờ xử lý', 'hoàn thành')
    AND (
      account.organization_id IS NULL
      OR account.organization_id = p_organization_id
    )
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF campaign, account;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false,
      'not_found',
      p_campaign_id,
      NULL::text,
      0::bigint;
    RETURN;
  END IF;

  -- Mirror resolveNextSchedule() in campaignRepository.ts. The capability
  -- revision is a freshness/CAS boundary rather than a secret, so the public
  -- Server RPC independently proves this is a real maintenance candidate.
  v_schedule_time := (
    date_trunc(
      'second',
      COALESCE(v_original_schedule, v_schedule)
        AT TIME ZONE 'Asia/Ho_Chi_Minh'
    )
  )::time;

  IF v_schedule_type = 'daily' THEN
    v_candidate_date := v_today;
  ELSIF v_schedule_type IN ('weekly', 'monthly') THEN
    FOREACH v_day_token IN ARRAY string_to_array(
      CASE
        WHEN v_schedule_type = 'weekly' THEN COALESCE(v_schedule_week_days, '')
        ELSE COALESCE(v_schedule_days, '')
      END,
      ','
    )
    LOOP
      BEGIN
        v_day_numeric := btrim(v_day_token)::numeric;
        IF v_day_numeric = trunc(v_day_numeric)
          AND (
            (v_schedule_type = 'weekly' AND v_day_numeric BETWEEN 2 AND 8)
            OR (v_schedule_type = 'monthly' AND v_day_numeric BETWEEN 1 AND 31)
          )
        THEN
          v_day_number := v_day_numeric::integer;
          IF NOT v_day_number = ANY(v_allowed_days) THEN
            v_allowed_days := array_append(v_allowed_days, v_day_number);
          END IF;
        END IF;
      EXCEPTION
        WHEN invalid_text_representation OR numeric_value_out_of_range THEN
          NULL;
      END;
    END LOOP;

    IF cardinality(v_allowed_days) > 0 THEN
      FOR v_day_offset IN 0..(
        CASE WHEN v_schedule_type = 'weekly' THEN 13 ELSE 369 END
      )
      LOOP
        v_candidate_date := v_today + v_day_offset;
        IF (
          v_schedule_type = 'weekly'
          AND (extract(isodow FROM v_candidate_date)::integer + 1) = ANY(v_allowed_days)
        ) OR (
          v_schedule_type = 'monthly'
          AND extract(day FROM v_candidate_date)::integer = ANY(v_allowed_days)
        ) THEN
          EXIT;
        END IF;
        v_candidate_date := NULL;
      END LOOP;
    END IF;
  END IF;

  IF v_candidate_date IS NOT NULL THEN
    v_next_schedule := (
      v_candidate_date + v_schedule_time
    ) AT TIME ZONE 'Asia/Ho_Chi_Minh';
  END IF;

  v_is_birthday_maintenance := (
    v_schedule_type = 'daily'
    AND v_action_id = 'zalo_message_birthday'
  );
  v_is_schedule_end_maintenance := (
    v_schedule_end_date IS NOT NULL
    AND v_next_schedule IS NOT NULL
    AND v_next_schedule > v_schedule_end_date
  );

  IF NOT v_is_birthday_maintenance AND NOT v_is_schedule_end_maintenance THEN
    RETURN QUERY SELECT
      false,
      'not_found',
      p_campaign_id,
      NULL::text,
      0::bigint;
    RETURN;
  END IF;

  v_maintenance_note := CASE
    WHEN v_is_schedule_end_maintenance THEN 'Chiến dịch đã hết ngày kết thúc'
    ELSE 'Chiến dịch chúc mừng sinh nhật không chạy bù qua ngày'
  END;

  RETURN QUERY
  SELECT
    result.completed,
    result.reason,
    result.campaign_id,
    result.campaign_status,
    result.pending_input_count
  FROM public.aka_agent_internal_finalize_zalo_server_maintenance_guard(
    p_staff_id,
    p_organization_id,
    v_authorized_campaign_id,
    v_maintenance_note,
    true,
    'chờ xử lý'
  ) AS result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_get_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_get_campaign_data_group_source(
      p_staff_id, p_organization_id, p_campaign_id
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_get_data_group_account_options(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_data_type_category_item_id bigint, p_auth_username text, p_auth_password text)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE v_group public.auto_account_contact_groups%ROWTYPE;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id,p_organization_id);
  IF p_group_id IS NOT NULL THEN
    SELECT * INTO v_group FROM public.auto_account_contact_groups
    WHERE id=p_group_id AND staff_id=p_staff_id AND organization_id=p_organization_id
      AND purpose='data_group' AND NOT is_delete;
    IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;
    IF v_group.dataset_sync_mode='dataset_auto'
      AND p_data_type_category_item_id IS DISTINCT FROM v_group.data_type_category_item_id THEN
      RAISE EXCEPTION 'dataset_auto_data_group_type_read_only';
    END IF;
  ELSE
    v_group.staff_id:=p_staff_id; v_group.organization_id:=p_organization_id;
    v_group.purpose:='data_group'; v_group.dataset_sync_mode:='manual';
  END IF;
  v_group.data_type_category_item_id:=p_data_type_category_item_id;
  RETURN QUERY SELECT to_jsonb(o) FROM public.aka_agent_data_group_account_options_internal(v_group) o;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_get_zalo_server_run_control_state(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint)
 RETURNS TABLE(campaign_id bigint, account_id bigint, campaign_status text, account_status text, account_login_status text, account_is_active boolean, account_is_delete boolean, campaign_is_delete boolean, pause_requested boolean, should_stop boolean, hard_stop_reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_campaign_status text;
  v_account_status text;
  v_account_login_status text;
  v_account_is_active boolean;
  v_account_is_delete boolean;
  v_campaign_is_delete boolean;
  v_pause_requested boolean := false;
  v_hard_stop_reason text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Campaign, account and staff IDs must be positive integers'; END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_profile AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
    AND (public.aka_agent_staff_time_allowed(staff.id) OR EXISTS (
      SELECT 1 FROM public.auto_campaigns held WHERE held.id=p_campaign_id
        AND held.account_id=p_account_id AND held.staff_id=p_staff_id AND held.runtime_unit_token IS NOT NULL
    ));
  IF NOT FOUND OR v_organization_id IS NULL THEN
    v_hard_stop_reason := 'runtime_not_owner';
  END IF;

  SELECT campaign.status, account.status, account.login_status,
    COALESCE(account.is_active, false), COALESCE(account.is_delete, false),
    COALESCE(campaign.is_delete, false)
  INTO v_campaign_status, v_account_status, v_account_login_status,
    v_account_is_active, v_account_is_delete, v_campaign_is_delete
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true;

  IF NOT FOUND THEN
    v_hard_stop_reason := COALESCE(v_hard_stop_reason, 'not_found');
  ELSE
    v_pause_requested := v_campaign_status IS DISTINCT FROM 'đang chạy'
      OR v_account_status IS DISTINCT FROM 'đang chạy';
    IF v_hard_stop_reason IS NULL AND v_campaign_is_delete THEN
      v_hard_stop_reason := 'campaign_deleted';
    ELSIF v_hard_stop_reason IS NULL AND v_account_is_delete THEN
      v_hard_stop_reason := 'account_deleted';
    ELSIF v_hard_stop_reason IS NULL AND NOT v_account_is_active THEN
      v_hard_stop_reason := 'account_inactive';
    ELSIF v_hard_stop_reason IS NULL AND v_account_login_status IS DISTINCT FROM 'đã đăng nhập' THEN
      v_hard_stop_reason := 'account_logged_out';
    END IF;
  END IF;

  RETURN QUERY SELECT p_campaign_id, p_account_id, v_campaign_status,
    v_account_status, v_account_login_status, v_account_is_active,
    v_account_is_delete, v_campaign_is_delete, v_pause_requested,
    v_pause_requested OR v_hard_stop_reason IS NOT NULL, v_hard_stop_reason;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_group_sharing(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_kind text := p_data->>'kind';
  v_id bigint := NULLIF(p_data->>'groupId','')::bigint;
  v_access jsonb;
  v_scope text;
  v_revision bigint;
  v_recipients bigint[];
  v_owner bigint;
  v_result jsonb;
  v_row record;
  v_ids bigint[];
  v_template_id bigint;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF NOT EXISTS(SELECT 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id
    AND is_active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;

  IF p_action='staff' THEN
    RETURN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',s.id,'name',COALESCE(NULLIF(s.name,''),'Nhân viên #'||s.id)) ORDER BY s.name,s.id),'[]'::jsonb)
      FROM public.org_staff s WHERE s.organization_id=p_organization_id AND s.deleted_at IS NULL AND s.is_active AND s.id<>p_staff_id);
  ELSIF p_action='data_groups' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(g)||jsonb_build_object(
      'access',private.group_access('data',g.id,p_staff_id,p_organization_id),
      'bound_zalo_account_id',cg.bound_zalo_account_id,
      'bound_zalo_account_name',CASE WHEN cg.staff_id=p_staff_id THEN a.name END)),'[]'::jsonb)
    INTO v_result FROM private.list_shared_data_groups(
      p_staff_id,p_organization_id,p_data->>'search',p_data->>'compatibleActionId',
      (p_data->>'compatibleDataTypeCategoryItemId')::bigint,
      CASE WHEN jsonb_typeof(p_data->'dataTypeCategoryItemIds')='array' AND jsonb_array_length(p_data->'dataTypeCategoryItemIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'dataTypeCategoryItemIds')::bigint) END,
      COALESCE((p_data->>'offset')::integer,0),LEAST(500,COALESCE((p_data->>'limit')::integer,50)),
      COALESCE((p_data->>'unrestrictedOnly')::boolean,false),COALESCE((p_data->>'ownedOnly')::boolean,false)
    ) g JOIN public.auto_account_contact_groups cg ON cg.id=g.id LEFT JOIN public.auto_accounts a ON a.id=cg.bound_zalo_account_id;
    RETURN v_result;
  ELSIF p_action='content_groups' THEN
    RETURN (SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'id')::bigint),'[]'::jsonb) FROM (
      SELECT to_jsonb(g)||jsonb_build_object('access',private.group_access('content',g.id,p_staff_id,p_organization_id)) row_data
      FROM public.auto_content_groups g WHERE g.organization_id=p_organization_id AND NOT g.is_delete
        AND g.id>COALESCE((p_data->>'afterId')::bigint,0)
        AND private.group_access('content',g.id,p_staff_id,p_organization_id) IS NOT NULL
        AND (NOT COALESCE((p_data->>'ownedOnly')::boolean,false) OR g.staff_id=p_staff_id)
      ORDER BY g.id LIMIT 500
    ) page);
  ELSIF p_action='content_templates' THEN
    RETURN (SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'id')::bigint),'[]'::jsonb) FROM (
      SELECT to_jsonb(t)||jsonb_build_object('content_group',jsonb_build_object('name',g.name),
        'access',CASE WHEN t.staff_id=p_staff_id THEN jsonb_build_object('role','owner','ownerStaffId',p_staff_id,'canManage',true,'canUse',true,'canCopy',true)
          ELSE private.group_access('content',g.id,p_staff_id,p_organization_id) END) row_data
      FROM public.auto_content_templates t LEFT JOIN public.auto_content_groups g ON g.id=t.group_id
      WHERE t.organization_id=p_organization_id AND NOT t.is_delete
        AND t.id>COALESCE((p_data->>'afterId')::bigint,0)
        AND (t.staff_id=p_staff_id OR (g.staff_id=t.staff_id AND g.organization_id=t.organization_id
          AND g.is_active AND private.group_access('content',g.id,p_staff_id,p_organization_id) IS NOT NULL))
      ORDER BY t.id LIMIT 500
    ) page);
  END IF;

  IF v_kind NOT IN ('data','content') OR v_kind IS NULL OR v_id IS NULL THEN
    RAISE EXCEPTION 'invalid_group_sharing_request';
  END IF;
  -- Lock writes/copies with the source group; all affected destinations are locked in ID order by copy RPC.
  IF p_action='save' THEN
    IF v_kind='data' THEN PERFORM id FROM public.auto_account_contact_groups WHERE id=v_id FOR UPDATE;
    ELSE PERFORM id FROM public.auto_content_groups WHERE id=v_id FOR UPDATE; END IF;
  END IF;
  v_access:=private.group_access(v_kind,v_id,p_staff_id,p_organization_id);
  IF v_access IS NULL THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;
  v_owner:=(v_access->>'ownerStaffId')::bigint;

  IF p_action IN ('get','save') THEN
    IF NOT (v_access->>'canManage')::boolean THEN
      IF p_action='save' THEN RAISE EXCEPTION 'group_sharing_owner_required'; END IF;
      RETURN jsonb_build_object('scope',v_access->>'scope','revision',v_access->>'revision','recipientIds','[]'::jsonb,'access',v_access);
    END IF;
    IF p_action='save' THEN
      v_scope:=p_data->>'scope';
      IF v_scope IS NULL OR v_scope NOT IN ('private','organization','selected') THEN RAISE EXCEPTION 'invalid_group_sharing_scope'; END IF;
      IF p_data->>'expectedRevision' IS DISTINCT FROM v_access->>'revision' THEN RAISE EXCEPTION 'group_sharing_conflict'; END IF;
      IF jsonb_typeof(p_data->'recipientIds') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid_group_sharing_recipients'; END IF;
      SELECT COALESCE(array_agg(DISTINCT x::bigint),'{}'::bigint[]) INTO v_recipients FROM jsonb_array_elements_text(p_data->'recipientIds') x;
      IF v_scope<>'selected' THEN v_recipients:='{}'::bigint[]; END IF;
      IF v_scope='selected' AND cardinality(v_recipients)=0 THEN RAISE EXCEPTION 'group_sharing_recipients_required'; END IF;
      IF EXISTS(SELECT 1 FROM unnest(v_recipients) r(id) LEFT JOIN public.org_staff s
        ON s.id=r.id AND s.organization_id=p_organization_id AND s.deleted_at IS NULL AND s.is_active
        WHERE s.id IS NULL OR s.id=p_staff_id) THEN RAISE EXCEPTION 'invalid_group_sharing_recipients'; END IF;
      IF v_kind='data' THEN
        DELETE FROM public.auto_data_group_recipients WHERE group_id=v_id;
        INSERT INTO public.auto_data_group_recipients SELECT v_id,unnest(v_recipients);
        UPDATE public.auto_account_contact_groups SET sharing_scope=v_scope,sharing_revision=sharing_revision+1 WHERE id=v_id;
        -- No campaign pause, deletion or input reset. A new grant never reactivates stopped sources.
        FOR v_row IN SELECT source.id,source.campaign_id FROM public.auto_campaign_data_group_sources source
          WHERE source.group_id=v_id AND source.staff_id<>p_staff_id AND source.status IN ('active','baselining')
          AND NOT private.can_read_data_group(v_id,source.staff_id,source.organization_id)
          ORDER BY source.campaign_id,source.id
        LOOP
          PERFORM public.aka_agent_lock_campaign_input_serialization(v_row.campaign_id);
          UPDATE public.auto_campaign_data_group_sources SET status='stopped',stop_reason='sharing_revoked',stopped_at=now(),updated_at=now()
            WHERE id=v_row.id AND status IN ('active','baselining');
        END LOOP;
      ELSE
        DELETE FROM public.auto_content_group_recipients WHERE group_id=v_id;
        INSERT INTO public.auto_content_group_recipients SELECT v_id,unnest(v_recipients);
        UPDATE public.auto_content_groups SET sharing_scope=v_scope,sharing_revision=sharing_revision+1 WHERE id=v_id;
      END IF;
      v_access:=private.group_access(v_kind,v_id,p_staff_id,p_organization_id);
    END IF;
    IF v_kind='data' THEN SELECT COALESCE(array_agg(staff_id ORDER BY staff_id),'{}'::bigint[]) INTO v_recipients FROM public.auto_data_group_recipients WHERE group_id=v_id;
    ELSE SELECT COALESCE(array_agg(staff_id ORDER BY staff_id),'{}'::bigint[]) INTO v_recipients FROM public.auto_content_group_recipients WHERE group_id=v_id; END IF;
    RETURN jsonb_build_object('scope',v_access->>'scope','revision',v_access->>'revision','recipientIds',to_jsonb(v_recipients),'access',v_access);
  ELSIF p_action='validate_content_selection' AND v_kind='content' THEN
    PERFORM id FROM public.auto_content_groups WHERE id=v_id AND is_active FOR SHARE;
    IF NOT FOUND OR private.group_access('content',v_id,p_staff_id,p_organization_id) IS NULL THEN
      RAISE EXCEPTION 'group_sharing_access_denied';
    END IF;
    RETURN jsonb_build_object('allowed',true);
  ELSIF p_action='copy' THEN
    RETURN private.copy_shared_group(p_staff_id,p_organization_id,v_kind,v_id,p_data);
  ELSIF p_action='data_members' AND v_kind='data' THEN
    IF jsonb_typeof(p_data->'ids')='array' THEN SELECT array_agg(x::bigint) INTO v_ids FROM jsonb_array_elements_text(p_data->'ids') x; END IF;
    IF jsonb_typeof(p_data->'sourceCodes')='array' AND jsonb_array_length(p_data->'sourceCodes')>0 THEN
      IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_data->'sourceCodes') code
        WHERE code NOT IN ('upload','scan','automation','dynamic_filter','external_sync')) THEN
        RAISE EXCEPTION 'invalid_data_group_source_filter';
      END IF;
      SELECT COALESCE(array_agg(m.id),ARRAY[-1]::bigint[]) INTO v_ids
      FROM public.auto_account_contact_group_members m WHERE m.group_id=v_id AND NOT m.is_delete
        AND (v_ids IS NULL OR m.id=ANY(v_ids))
        AND EXISTS(SELECT 1 FROM public.auto_account_contact_group_member_origins o JOIN public.category_item c ON c.id=o.source_category_item_id
          WHERE o.membership_id=m.id AND o.is_current AND c.code IN (SELECT jsonb_array_elements_text(p_data->'sourceCodes')));
    END IF;
    RETURN (SELECT COALESCE(jsonb_agg(CASE WHEN v_owner=p_staff_id THEN to_jsonb(m) ELSE to_jsonb(m)||jsonb_build_object(
      'source_automation_id',NULL,'source_automation_name',NULL,
      'dataset_ids','[]'::jsonb,'dataset_names','[]'::jsonb,'provenance','[]'::jsonb) END),'[]'::jsonb)
    FROM private.read_shared_group_members(
      v_owner,p_organization_id,v_id,p_data->>'search',
      CASE WHEN jsonb_typeof(p_data->'accountIds')='array' AND jsonb_array_length(p_data->'accountIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'accountIds')::bigint) END,
      COALESCE((p_data->>'includeAccountless')::boolean,true),
      CASE WHEN jsonb_typeof(p_data->'contactTypes')='array' AND jsonb_array_length(p_data->'contactTypes')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'contactTypes')) END,
      CASE WHEN jsonb_typeof(p_data->'flatformTypes')='array' AND jsonb_array_length(p_data->'flatformTypes')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'flatformTypes')) END,
      COALESCE(p_data->>'status','all'),
      CASE WHEN jsonb_typeof(p_data->'datasetIds')='array' AND jsonb_array_length(p_data->'datasetIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'datasetIds')::bigint) END,
      CASE WHEN jsonb_typeof(p_data->'dataTypeCategoryItemIds')='array' AND jsonb_array_length(p_data->'dataTypeCategoryItemIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'dataTypeCategoryItemIds')::bigint) END,
      v_ids,CASE WHEN jsonb_typeof(p_data->'excludeIds')='array' AND jsonb_array_length(p_data->'excludeIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'excludeIds')::bigint) END,
      COALESCE((p_data->>'offset')::integer,0),LEAST(1000,COALESCE((p_data->>'limit')::integer,100))) m);
  ELSIF p_action='data_datasets' AND v_kind='data' THEN
    IF v_owner<>p_staff_id THEN RETURN '[]'::jsonb; END IF;
    RETURN (SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::jsonb) FROM public.aka_agent_list_data_group_datasets(p_staff_id,p_organization_id,v_id) d);
  ELSIF p_action='data_panel' AND v_kind='data' THEN
    IF v_owner=p_staff_id THEN RETURN public.aka_agent_get_data_group_panel(p_staff_id,p_organization_id,v_id,p_auth_username,p_auth_password); END IF;
    RETURN (SELECT jsonb_build_object('group',jsonb_build_object('id',g.id,'name',g.name,'color',g.color,'note',g.note,
        'created_at',g.created_at,'updated_at',g.updated_at,'data_type_category_item_id',g.data_type_category_item_id,
        'bound_zalo_account_id',g.bound_zalo_account_id)||public.aka_agent_data_type_json(g.data_type_category_item_id)
        ||jsonb_build_object('creator_name',v_access->>'ownerName','access',v_access),
      'summary',jsonb_build_object('active_membership_count',(SELECT count(*) FROM public.auto_account_contact_group_members WHERE group_id=v_id AND NOT is_delete)),
      'quality','{}'::jsonb,'source_breakdown','[]'::jsonb,'data_type_breakdown','[]'::jsonb,
      'account_breakdown','[]'::jsonb,'tags','[]'::jsonb,'history','[]'::jsonb,'campaigns','[]'::jsonb)
      FROM public.auto_account_contact_groups g WHERE g.id=v_id);
  END IF;
  RAISE EXCEPTION 'invalid_group_sharing_action';
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_ingest_data_group(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_group_id bigint, p_kind text, p_rows jsonb, p_dataset_id bigint, p_dataset_name text, p_import_source text, p_source_account_id bigint, p_source_name text, p_payload_hash text, p_data_type_category_item_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_group_type bigint;
  v_effective_type bigint := p_data_type_category_item_id;
  v_previous_context text :=
    current_setting('aka_agent.data_type_category_item_id', true);
  v_semantic_payload_hash text;
  v_result jsonb;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF p_data_type_category_item_id IS NOT NULL
    AND NOT public.aka_agent_is_data_type_category_item(
      p_data_type_category_item_id, true
    )
  THEN
    RAISE EXCEPTION 'invalid_data_type_category_item';
  END IF;

  SELECT contact_group.data_type_category_item_id
  INTO v_group_type
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;

  IF p_dataset_id IS NOT NULL AND v_effective_type IS NULL THEN
    SELECT dataset.data_type_category_item_id
    INTO v_effective_type
    FROM public.auto_account_contacts_dataset AS dataset
    WHERE dataset.id = p_dataset_id
      AND dataset.staff_id = p_staff_id
      AND dataset.organization_id = p_organization_id
      AND dataset.is_delete = false;
  END IF;

  IF v_group_type IS NOT NULL
    AND v_effective_type IS DISTINCT FROM v_group_type
  THEN
    RAISE EXCEPTION 'data_group_ingest_semantic_type_mismatch';
  END IF;

  v_semantic_payload_hash := md5(
    COALESCE(
      NULLIF(btrim(COALESCE(p_payload_hash, '')), ''),
      md5(COALESCE(p_rows, 'null'::jsonb)::text)
    )
    || ':data_type:'
    || COALESCE(v_effective_type::text, 'null')
  );

  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_effective_type::text, 'null'),
    true
  );
  v_result := public.aka_agent_ingest_data_group(
    p_staff_id,
    p_organization_id,
    p_request_id,
    p_group_id,
    p_kind,
    p_rows,
    p_dataset_id,
    p_dataset_name,
    p_import_source,
    p_source_account_id,
    p_source_name,
    v_semantic_payload_hash
  );
  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_previous_context, ''),
    true
  );
  RETURN v_result;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_previous_context, ''),
    true
  );
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_list_campaign_details_page_v2(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_search text, p_status text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_offset integer, p_limit integer, p_sort text, p_auth_username text, p_auth_password text, p_engagement_filter text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_sort text := COALESCE(p_sort, 'created_desc');
  v_search text := NULLIF(btrim(left(p_search, 200)), '');
  v_status text := NULLIF(btrim(left(p_status, 120)), '');
  v_where text := 'd.campaign_id = $1 AND d.is_delete = false';
  v_direction text;
  v_status_ids bigint[];
  v_search_ids bigint[];
  v_count_sql text;
  v_page_sql text;
  v_branch_order text;
  v_result jsonb;
BEGIN
  -- Same credential + campaign ownership guard as the live detail provenance RPC.
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR COALESCE(p_offset, 0) < 0 OR COALESCE(p_limit, 100) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'invalid_campaign_details_page';
  END IF;
  IF v_sort NOT IN ('created_asc', 'created_desc') THEN
    RAISE EXCEPTION 'invalid_campaign_details_sort';
  END IF;
  IF p_date_from IS NOT NULL AND p_date_to IS NOT NULL AND p_date_from > p_date_to THEN
    RAISE EXCEPTION 'invalid_campaign_details_date_range';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.auto_campaigns AS campaign
    WHERE campaign.id = p_campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'campaign_not_found';
  END IF;

  -- Only fixed SQL fragments are concatenated. All user values are bound.
  -- Omitting inactive predicates avoids generic OR plans scanning wide rows.
  -- Resolve the small catalog once, not once per matching detail. STABLE
  -- keeps these reads in the caller's snapshot, including the payload below.
  -- Keep historical/inactive catalog entries and the exact legacy comparisons.
  IF v_status IS NOT NULL THEN
    v_status_ids := ARRAY(SELECT s.id FROM public.auto_status s
      WHERE s.status_value=v_status OR lower(s.name)=lower(v_status));
  END IF;
  IF p_date_from IS NOT NULL THEN v_where := v_where || ' AND d.created_at >= $3'; END IF;
  IF p_date_to IS NOT NULL THEN v_where := v_where || ' AND d.created_at <= $4'; END IF;
  IF v_search IS NOT NULL THEN
    v_search_ids := ARRAY(SELECT s.id FROM public.auto_status s
      WHERE s.name ILIKE '%' || v_search || '%' OR s.status_value ILIKE '%' || v_search || '%');
    v_where := v_where || ' AND (d.action_name ILIKE $5 OR d.action_code ILIKE $5
      OR d.status ILIKE $5 OR d.error_code ILIKE $5 OR d.log ILIKE $5 OR d.post_url ILIKE $5';
    IF cardinality(v_search_ids)>0 THEN
      v_where := v_where || ' OR d.status_id=ANY($9) OR d.sub_status_id=ANY($9)';
    END IF;
    v_where := v_where || ')';
  END IF;
  IF COALESCE(p_engagement_filter, 'all') NOT IN ('all','seen','responded','reacted','friended','none') THEN
    RAISE EXCEPTION 'invalid_engagement_filter';
  END IF;
  IF p_engagement_filter IN ('seen','responded','reacted','friended','none') THEN
    v_where := v_where || ' AND EXISTS (SELECT 1 FROM public.auto_campaign_detail_zalo_engagement e WHERE e.campaign_detail_id=d.id AND ' ||
      CASE p_engagement_filter WHEN 'seen' THEN 'e.seen_at IS NOT NULL' WHEN 'responded' THEN 'e.responded_at IS NOT NULL'
        WHEN 'reacted' THEN 'e.reacted_at IS NOT NULL' WHEN 'friended' THEN 'e.friended_at IS NOT NULL'
        ELSE 'e.seen_at IS NULL AND e.responded_at IS NULL AND e.reacted_at IS NULL AND e.friended_at IS NULL' END || ')';
  END IF;
  v_direction := CASE WHEN v_sort = 'created_asc' THEN 'ASC' ELSE 'DESC' END;
  -- Count text matches with the existing covering status index. The second
  -- branch only counts additional main/sub-status matches: no double counting,
  -- even when both IDs match, or when the legacy text is NULL.
  v_count_sql := 'SELECT count(*) FROM public.auto_campaign_details AS d WHERE ' || v_where;
  v_page_sql := 'SELECT d.id, d.created_at FROM public.auto_campaign_details AS d WHERE ' || v_where;
  IF v_status IS NOT NULL THEN
    v_count_sql := 'SELECT (' || v_count_sql || ' AND d.status = $2)';
    v_page_sql := v_page_sql || ' AND d.status = $2';
    IF cardinality(v_status_ids)>0 THEN
      v_count_sql := v_count_sql || ' + (SELECT count(*) FROM public.auto_campaign_details AS d WHERE '
        || v_where || ' AND d.status IS DISTINCT FROM $2 AND (d.status_id=ANY($8) OR d.sub_status_id=ANY($8)))';
      -- The same disjoint branches avoid a full campaign scan when a status
      -- has no matches. Each ordered prefix is sufficient for the final page;
      -- only the outer query applies OFFSET. bigint prevents integer overflow.
      v_branch_order := ' ORDER BY d.created_at ' || v_direction || ', d.id ' || v_direction
        || ' LIMIT ($6::bigint + $7::bigint)';
      v_page_sql := '(' || v_page_sql || v_branch_order || ') UNION ALL (SELECT d.id, d.created_at'
        || ' FROM public.auto_campaign_details AS d WHERE ' || v_where
        || ' AND d.status IS DISTINCT FROM $2 AND (d.status_id=ANY($8) OR d.sub_status_id=ANY($8))'
        || v_branch_order || ')';
    END IF;
  END IF;

  -- Both keys are NOT NULL in the live schema (checked by preflight). Default
  -- NULL placement is therefore equivalent to NULLS LAST for both directions,
  -- and allows one index to support forward and backward index-only scans.
  -- MATERIALIZED limits the narrow ID set before any full-row payload lookup.
  -- Count, page IDs and payload are read by one statement / MVCC snapshot;
  -- count remains available even when the requested page has no items.
  EXECUTE format($query$
    WITH page_ids AS MATERIALIZED (
      SELECT d.id, d.created_at
      FROM (%1$s) AS d
      ORDER BY d.created_at %2$s, d.id %2$s
      LIMIT $6 OFFSET $7
    )
    SELECT jsonb_build_object(
      'items', COALESCE((
        SELECT jsonb_agg(((to_jsonb(detail) || jsonb_build_object(
          'status_presentation', CASE WHEN main_status.id IS NULL THEN NULL ELSE jsonb_build_object('code',main_status.code,'name',main_status.name,'color',main_status.color,'statusValue',main_status.status_value) END,
          'sub_status_presentation', CASE WHEN sub_status.id IS NULL THEN NULL ELSE jsonb_build_object('code',sub_status.code,'name',sub_status.name,'color',sub_status.color,'statusValue',sub_status.status_value) END)) || jsonb_build_object('zalo_engagement', to_jsonb(engagement), 'zalo_engagement_applicable',
          engagement.campaign_detail_id IS NOT NULL OR (account.flatform_type='zalo' AND NOT COALESCE(account.is_zalo_show_web,false)
            AND detail.status='thành công' AND detail.action_code IN ('zalo_message_friend','zalo_message_stranger','zalo_add_friend')
            AND detail.data->'partialSend' IS NULL))) ORDER BY page.created_at %2$s, page.id %2$s)
        FROM page_ids AS page
        JOIN public.auto_campaign_details AS detail ON detail.id = page.id
        LEFT JOIN public.auto_status main_status ON main_status.id=detail.status_id
        LEFT JOIN public.auto_status sub_status ON sub_status.id=detail.sub_status_id
        LEFT JOIN public.auto_campaign_detail_zalo_engagement engagement ON engagement.campaign_detail_id=page.id
        LEFT JOIN public.auto_accounts account ON account.id=detail.account_id
      ), '[]'::jsonb),
      'total', (%3$s)
    )
  $query$, v_page_sql, v_direction, v_count_sql)
  INTO v_result
  USING p_campaign_id, v_status, p_date_from, p_date_to,
    '%' || v_search || '%', COALESCE(p_limit,100), COALESCE(p_offset,0), v_status_ids, v_search_ids;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_list_message_opt_out_customers(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_search text DEFAULT ''::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '10s'
AS $function$
DECLARE
  v_search text := left(btrim(COALESCE(p_search, '')), 200);
  v_pattern text;
  v_page integer := greatest(1, least(COALESCE(p_page, 1), 1000000));
  v_total bigint;
  v_items jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id, p_organization_id, p_auth_username, p_auth_password);
  IF NOT EXISTS (SELECT 1 FROM public.org_staff WHERE id = p_staff_id AND organization_id = p_organization_id
    AND is_active = true AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Không có quyền truy cập danh sách.';
  END IF;
  v_pattern := '%' || replace(replace(replace(v_search, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';
  SELECT count(*) INTO v_total FROM public.auto_zalo_message_opt_outs o
  WHERE o.staff_id = p_staff_id AND o.organization_id = p_organization_id AND o.confirmed_at IS NOT NULL
    AND (v_search = '' OR o.zalo_name ILIKE v_pattern OR o.phone ILIKE v_pattern OR o.email ILIKE v_pattern
      OR o.zalo_global_id ILIKE v_pattern OR o.source_campaign_name ILIKE v_pattern);
  v_page := least(v_page, greatest(1, ceil(v_total::numeric / 50)::integer));
  SELECT COALESCE(jsonb_agg(x.item ORDER BY x.confirmed_at DESC, x.id DESC), '[]'::jsonb) INTO v_items
  FROM (
    SELECT o.id, o.confirmed_at, jsonb_build_object(
      'id', o.id, 'phone', o.phone, 'email', o.email, 'zaloGlobalId', o.zalo_global_id,
      'zaloName', o.zalo_name, 'zaloAvatar', o.zalo_avatar, 'confirmedAt', o.confirmed_at,
      'sourceCampaignId', o.source_campaign_id, 'sourceCampaignName', o.source_campaign_name,
      'sourceDetailId', o.source_detail_id, 'sourceSentAt', o.source_sent_at,
      'sourceActionName', o.source_action_name, 'sourceStatus', o.source_status
    ) AS item
    FROM public.auto_zalo_message_opt_outs o
    WHERE o.staff_id = p_staff_id AND o.organization_id = p_organization_id AND o.confirmed_at IS NOT NULL
      AND (v_search = '' OR o.zalo_name ILIKE v_pattern OR o.phone ILIKE v_pattern OR o.email ILIKE v_pattern
        OR o.zalo_global_id ILIKE v_pattern OR o.source_campaign_name ILIKE v_pattern)
    ORDER BY o.confirmed_at DESC, o.id DESC LIMIT 50 OFFSET (v_page - 1) * 50
  ) x;
  RETURN jsonb_build_object('items', v_items, 'total', v_total, 'page', v_page, 'pageSize', 50);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_move_data_group_members(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_group_id bigint, p_membership_ids bigint[], p_target_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_group public.auto_account_contact_groups%ROWTYPE;
  v_target_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_request_hash text;
  v_requested integer;
  v_count integer := 0;
  v_source_member record;
  v_target_member public.auto_account_contact_group_members%ROWTYPE;
  v_target_primary_before bigint;
  v_bound_source record;
  v_result jsonb;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR p_group_id IS NOT DISTINCT FROM p_target_group_id
    OR COALESCE(cardinality(p_membership_ids), 0) = 0
    OR EXISTS (SELECT 1 FROM unnest(p_membership_ids) AS value(id) WHERE id IS NULL OR id <= 0)
  THEN RAISE EXCEPTION 'invalid_data_group_member_move'; END IF;
  SELECT count(DISTINCT id)::integer INTO v_requested FROM unnest(p_membership_ids) AS value(id);

  -- Stable lock order avoids inverse source/destination move deadlocks.
  PERFORM contact_group.id
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id IN (p_group_id, p_target_group_id)
  ORDER BY contact_group.id
  FOR UPDATE;

  SELECT * INTO v_source_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false;
  SELECT * INTO v_target_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_target_group_id AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false;
  IF v_source_group.id IS NULL OR v_target_group.id IS NULL THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;

  IF v_target_group.data_type_category_item_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_source_group.id
        AND member.id = ANY(p_membership_ids)
        AND member.is_delete = false
        AND (
          NOT EXISTS (
            SELECT 1
            FROM public.auto_account_contact_group_member_origins AS origin
            WHERE origin.membership_id = member.id
              AND origin.is_current = true
          )
          OR EXISTS (
            SELECT 1
            FROM public.auto_account_contact_group_member_origins AS origin
            WHERE origin.membership_id = member.id
              AND origin.is_current = true
              AND origin.data_type_category_item_id IS DISTINCT FROM
                v_target_group.data_type_category_item_id
          )
        )
    )
  THEN
    RAISE EXCEPTION 'data_group_move_semantic_type_mismatch';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'move_members', 'groupId', p_group_id,
    'targetGroupId', p_target_group_id,
    'membershipIds', (SELECT jsonb_agg(id ORDER BY id) FROM (
      SELECT DISTINCT id FROM unnest(p_membership_ids) AS value(id)
    ) AS sorted)
  )::text);
  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, target_group_id, kind, request_hash,
    status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'move_members', p_group_id, p_target_group_id, 'manual',
    v_request_hash, 'processing', p_staff_id, p_organization_id
  ) ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;
  IF NOT FOUND THEN
    SELECT * INTO v_batch FROM public.auto_data_ingest_batches
    WHERE staff_id = p_staff_id AND organization_id = p_organization_id
      AND request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'move_members' OR v_batch.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  IF (
    SELECT count(DISTINCT member.id)
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_source_group.id AND member.id = ANY(p_membership_ids)
  ) <> v_requested THEN
    RAISE EXCEPTION 'data_group_membership_not_found';
  END IF;
  SELECT count(*)::integer INTO v_count
  FROM public.auto_account_contact_group_members AS member
  WHERE member.group_id = v_source_group.id AND member.id = ANY(p_membership_ids)
    AND member.is_delete = false;

  IF v_count > 0 THEN
    UPDATE public.auto_account_contact_groups
    SET revision = revision + 1, updated_at = now()
    WHERE id = v_target_group.id RETURNING * INTO v_target_group;
    UPDATE public.auto_account_contact_groups
    SET revision = revision + 1, updated_at = now()
    WHERE id = v_source_group.id RETURNING * INTO v_source_group;

    -- Activate destination memberships and provenance first.
    FOR v_source_member IN
      SELECT member.*
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_source_group.id
        AND member.id = ANY(p_membership_ids) AND member.is_delete = false
      ORDER BY member.id
    LOOP
      SELECT member.primary_origin_id
      INTO v_target_primary_before
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_target_group.id
        AND member.contact_id = v_source_member.contact_id
      FOR UPDATE;

      INSERT INTO public.auto_account_contact_group_members AS existing_member (
        group_id, contact_id, is_delete, change_revision, created_at, updated_at
      ) VALUES (
        v_target_group.id, v_source_member.contact_id, false,
        v_target_group.revision, now(), now()
      )
      ON CONFLICT (group_id, contact_id) DO UPDATE SET
        is_delete = false,
        change_revision = EXCLUDED.change_revision,
        updated_at = now()
      RETURNING * INTO v_target_member;

      INSERT INTO public.auto_account_contact_group_member_origins (
        membership_id, kind, dataset_id, batch_id, source_account_id, automation_detail_id,
        source_name_snapshot, relationship_kind, data_type_category_item_id, is_current, created_at, updated_at
      )
      SELECT
        v_target_member.id, origin.kind, origin.dataset_id, origin.batch_id,
        origin.source_account_id, origin.automation_detail_id,
        origin.source_name_snapshot, origin.relationship_kind, origin.data_type_category_item_id, true, now(), now()
      FROM public.auto_account_contact_group_member_origins AS origin
      WHERE origin.membership_id = v_source_member.id AND origin.is_current = true
      ON CONFLICT DO NOTHING;

      PERFORM public.aka_agent_sync_copied_data_group_origins(
        v_source_member.id,
        v_target_member.id,
        v_target_primary_before IS NULL
      );

      INSERT INTO public.auto_account_contact_group_member_origins (
        membership_id, kind, batch_id, source_name_snapshot, is_current,
        data_type_category_item_id
      ) VALUES (
        v_target_member.id, 'manual', v_batch.id,
        'move:' || v_source_group.name, true,
        (
          SELECT min(origin.data_type_category_item_id)
          FROM public.auto_account_contact_group_member_origins AS origin
          WHERE origin.membership_id = v_source_member.id
            AND origin.is_current = true
          HAVING count(*) > 0
            AND count(origin.data_type_category_item_id) = count(*)
            AND count(DISTINCT origin.data_type_category_item_id) = 1
        )
      ) ON CONFLICT DO NOTHING;

      FOR v_bound_source IN
        SELECT source.id FROM public.auto_campaign_data_group_sources AS source
        WHERE source.group_id = v_target_group.id AND source.status IN ('baselining', 'active')
        ORDER BY source.campaign_id
      LOOP
        PERFORM public.aka_agent_internal_route_data_group_member(
          v_bound_source.id, v_target_member.id, v_batch.id, v_target_group.revision
        );
      END LOOP;
    END LOOP;

    -- Source is soft-deleted only after all destination activations/fanout.
    UPDATE public.auto_account_contact_group_members
    SET is_delete = true, change_revision = v_source_group.revision, updated_at = now()
    WHERE group_id = v_source_group.id AND id = ANY(p_membership_ids) AND is_delete = false;
    UPDATE public.auto_account_contact_group_member_origins AS origin
    SET is_current = false, updated_at = now()
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_source_group.id AND member.id = ANY(p_membership_ids)
      AND origin.membership_id = member.id AND origin.is_current = true;
  END IF;

  v_result := jsonb_build_object(
    'success', true, 'count', v_count, 'group_revision', v_source_group.revision,
    'target_group_revision', v_target_group.revision
  );
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = v_result, updated_at = now()
  WHERE id = v_batch.id;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_preflight_campaign_data_group_change(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_group_id bigint, p_auth_username text, p_auth_password text)
 RETURNS TABLE(allowed boolean, reason text, canonical_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    RETURN QUERY
    SELECT *
    FROM public.aka_agent_preflight_campaign_data_group_change(
      p_staff_id, p_organization_id, p_campaign_id, p_group_id
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_preflight_campaign_data_group_change(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_group_id bigint)
 RETURNS TABLE(allowed boolean, reason text, canonical_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  canonical_count := 0;

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false) THEN
    allowed := false;
    reason := 'data_group_campaign_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  -- Ownership precedes every early-return branch, including `unchanged`, so a
  -- service caller cannot reuse a source after its Zalo account becomes local.
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts AS account
    WHERE account.id = v_campaign.account_id
      AND account.staff_id = p_staff_id
      AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
      AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
  ) THEN
    allowed := false;
    reason := 'data_group_campaign_account_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT count(*)::bigint INTO canonical_count
  FROM public.auto_campaign_input_data AS input_row
  WHERE input_row.campaign_id = v_campaign.id
    AND input_row.canonical_target_key IS NOT NULL
    AND COALESCE(input_row.is_delete, false) = false;

  IF p_group_id IS NULL OR p_group_id <= 0 OR NOT EXISTS (
    SELECT 1
    FROM public.auto_account_contact_groups AS contact_group
    WHERE contact_group.id = p_group_id
      AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
      AND contact_group.organization_id = p_organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false
  ) THEN
    allowed := false;
    reason := 'data_group_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_campaign.data_target_source_mode = 'data_group'
    AND v_campaign.data_group_id IS NOT DISTINCT FROM p_group_id
  THEN
    allowed := true;
    reason := 'unchanged';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_campaign.status IN ('đang chạy', 'hoàn thành')
    OR (v_campaign.schedule_end_date IS NOT NULL
      AND v_campaign.schedule_end_date <= now())
  THEN
    allowed := false;
    reason := 'data_group_campaign_not_bindable';
    RETURN NEXT;
    RETURN;
  END IF;
  IF v_campaign.action_id NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    allowed := false;
    reason := 'data_group_campaign_action_incompatible';
    RETURN NEXT;
    RETURN;
  END IF;
  IF canonical_count > 0 THEN
    allowed := false;
    reason := 'campaign_data_group_source_immutable_after_intake';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT source.* INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = v_campaign.id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF FOUND AND v_source.bundle_id IS NOT NULL THEN
    allowed := false;
    reason := 'campaign_data_group_source_immutable';
    RETURN NEXT;
    RETURN;
  END IF;

  allowed := true;
  reason := 'allowed';
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reactivate_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_reactivate_campaign_data_group_source(
      p_staff_id, p_organization_id, p_campaign_id, p_request_id, p_reason
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reactivate_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_hash text;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_data_group_source_request';
  END IF;

  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = p_campaign_id AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_data_group_source_not_found'; END IF;
  SELECT * INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = v_source.group_id AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  -- Reactivation routes the existing group snapshot after locking campaign and
  -- source rows. Join the common campaign/input barrier before either of those
  -- row locks so the nested legacy router can re-enter it without inversion.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
  FOR UPDATE OF campaign, account;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false)
    OR v_campaign.data_group_id IS DISTINCT FROM v_source.group_id
    OR v_campaign.data_target_source_mode <> 'data_group'
    OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now()) THEN
    RAISE EXCEPTION 'data_group_campaign_terminal';
  END IF;
  -- Re-lock in the shared group -> campaign -> source order used by bind and
  -- intake, then verify the optimistic source read did not change underneath.
  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = v_source.id
    AND source.campaign_id = p_campaign_id
    AND source.group_id = v_group.id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_data_group_source_changed'; END IF;
  IF v_source.status <> 'stopped' THEN RETURN to_jsonb(v_source); END IF;

  v_hash := md5(jsonb_build_object(
    'operation', 'reactivate_source', 'campaignId', p_campaign_id,
    'groupId', v_source.group_id
  )::text);
  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'reactivate_source', v_source.group_id, v_hash,
    'processing', p_staff_id, p_organization_id
  ) ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;
  IF NOT FOUND THEN
    SELECT * INTO v_batch FROM public.auto_data_ingest_batches
    WHERE staff_id = p_staff_id AND organization_id = p_organization_id
      AND request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'reactivate_source' OR v_batch.request_hash <> v_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  UPDATE public.auto_campaign_data_group_sources
  SET status = 'baselining', stopped_at = NULL, stop_reason = NULL, updated_at = now()
  WHERE id = v_source.id RETURNING * INTO v_source;
  PERFORM public.aka_agent_internal_route_group_snapshot(
    v_source.id, v_batch.id, v_group.revision
  );
  UPDATE public.auto_campaign_data_group_sources
  SET status = 'active', baseline_revision = v_group.revision,
      started_at = COALESCE(started_at, now()), last_ingest_at = now(), updated_at = now()
  WHERE id = v_source.id RETURNING * INTO v_source;
  UPDATE public.auto_campaigns
  SET status = CASE WHEN status = 'hoàn thành' THEN 'chờ xử lý' ELSE status END,
      completed_at = CASE WHEN status = 'hoàn thành' THEN NULL ELSE completed_at END,
      note = CASE WHEN status = 'hoàn thành' THEN 'Chờ data mới' ELSE note END,
      updated_at = now()
  WHERE id = v_campaign.id;
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
  WHERE id = v_batch.id;
  RETURN to_jsonb(v_source);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_read_filtered_contacts_v1(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_source text, p_query jsonb)
