), rollup AS MATERIALIZED (
 SELECT lower(uid) uid_key,count(*) sent_count,(array_agg(id ORDER BY created_at DESC,id DESC))[1] latest_id,
 (array_agg(uid ORDER BY created_at DESC,id DESC))[1] uid,
 (array_agg(fallback_name ORDER BY created_at DESC,id DESC) FILTER (WHERE fallback_name IS NOT NULL AND fallback_name<>uid))[1] fallback_name,
 (array_agg(fallback_phone ORDER BY created_at DESC,id DESC) FILTER (WHERE fallback_phone IS NOT NULL))[1] fallback_phone,
 (array_agg(original_name ORDER BY created_at DESC,id DESC) FILTER (WHERE original_name IS NOT NULL))[1] original_name
 FROM history WHERE uid IS NOT NULL GROUP BY lower(uid)
), candidate AS NOT MATERIALIZED (
 SELECT d.id,d.created_at,($3->>'accountId')::bigint account_id,CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END is_friend,c.akabiz_tag_ids,
 COALESCE(c.extra_data,'{}'::jsonb)||jsonb_build_object('source','zalo_remarketing_customers','latestCampaignId',campaign.id,'latestCampaignName',campaign.name,'latestCampaignActionId',campaign.action_id,'latestCampaignActionName',COALESCE(NULLIF(action.name,''),campaign.action_id),'latestErrorCode',d.error_code,'originalName',COALESCE(NULLIF(btrim(u.zalo_name),''),NULLIF(btrim(u.display_name),''),NULLIF(btrim(r.original_name),'')),'gender',u.gender) extra_data,
 COALESCE(NULLIF(btrim(c.name),''),NULLIF(btrim(u.display_name),''),NULLIF(btrim(u.zalo_name),''),NULLIF(btrim(r.fallback_name),''),NULLIF(btrim(r.uid),'')) AS "f_name",
r.uid AS "f_uid",
COALESCE(private.column_filter_phone_v1(COALESCE(NULLIF(btrim(u.phone_number),''),NULLIF(btrim(u.raw_payload->>'phoneNumber'),''),NULLIF(btrim(u.raw_payload->>'phone_number'),''),NULLIF(btrim(u.raw_payload->>'phone'),''))),private.column_filter_phone_v1(COALESCE(NULLIF(btrim(c.extra_data->>'phone'),''),NULLIF(btrim(c.extra_data->>'phoneNumber'),''),NULLIF(btrim(c.extra_data->>'phone_number'),''),NULLIF(btrim(c.extra_data->>'mobilePhone'),''),NULLIF(btrim(c.extra_data->>'mobile_phone'),''))),r.fallback_phone) AS "f_phone",
g.name AS "f_groupName",
campaign.action_id AS "f_latestAction",
r.sent_count AS "f_sentCount",
d.created_at AS "f_latestSentAt",
(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-(d.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AS "f_daysSinceLatest",
d.status AS "f_latestStatus",
d.log AS "f_latestLog",
CASE WHEN (CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END) THEN 'Bạn bè' WHEN NOT (CASE WHEN u.is_fr=1 OR c.is_friend IS TRUE THEN true WHEN (u.zalo_uid IS NOT NULL AND COALESCE(u.is_fr,0)=0) OR c.is_friend IS FALSE THEN false END) THEN 'Chưa kết bạn' END AS "f_recipientStatus",
private.column_filter_zalo_tags_v1(c.extra_data) AS "f_zaloTags",
c.akabiz_tag_ids::text[] AS "f_akaBizTags"
 FROM rollup r JOIN public.auto_campaign_details d ON d.id=r.latest_id JOIN public.auto_campaigns campaign ON campaign.id=d.campaign_id
 LEFT JOIN public.auto_campaign_actions action ON action.id=campaign.action_id
 LEFT JOIN public.auto_account_contacts c ON c.account_id=campaign.account_id AND c.staff_id=$1 AND c.organization_id=$2 AND c.uid=r.uid AND c.contact_type='person' AND NOT c.is_delete
 LEFT JOIN public.zalo_users u ON u.account_id=campaign.account_id AND u.staff_id=$1 AND u.organization_id=$2 AND u.zalo_uid=r.uid
 LEFT JOIN LATERAL (SELECT m.zalo_group_id FROM public.zalo_group_members m WHERE m.account_id=campaign.account_id AND m.staff_id=$1 AND m.organization_id=$2 AND m.zalo_uid=r.uid ORDER BY m.is_current DESC,m.last_seen_at DESC,m.updated_at DESC,m.id DESC LIMIT 1) member ON nullif(btrim(COALESCE(c.extra_data->>'zaloGroupId',c.extra_data->>'zalo_group_id')),'') IS NULL
 LEFT JOIN public.zalo_groups g ON g.account_id=campaign.account_id AND g.staff_id=$1 AND g.organization_id=$2 AND g.zalo_group_id=COALESCE(NULLIF(btrim(c.extra_data->>'zaloGroupId'),''),NULLIF(btrim(c.extra_data->>'zalo_group_id'),''),NULLIF(btrim(member.zalo_group_id),''))
), filtered AS NOT MATERIALIZED (SELECT * FROM candidate WHERE %1$s
 AND (NOT ($3 ? 'ids') OR id IN (SELECT jsonb_array_elements_text($3->'ids')::bigint))
 AND (NOT ($3 ? 'excludeIds') OR id NOT IN (SELECT jsonb_array_elements_text($3->'excludeIds')::bigint))
 AND (NULLIF(btrim($3->>'search'),'') IS NULL OR strpos(lower(normalize(concat_ws(' ',f_name,f_uid,f_phone,extra_data->>'phoneNumber',extra_data->>'phone_number',extra_data->>'mobilePhone',extra_data->>'mobile_phone'),NFC)),lower(normalize(btrim($3->>'search'),NFC)))>0)
 AND ((COALESCE(jsonb_array_length($3->'zaloTagIds'),0)=0 AND NOT COALESCE(($3->>'zaloNoTag')::boolean,false)) OR "f_zaloTags" && ARRAY(SELECT jsonb_array_elements_text($3->'zaloTagIds')) OR (COALESCE(($3->>'zaloNoTag')::boolean,false) AND cardinality("f_zaloTags")=0))
 AND ((COALESCE(jsonb_array_length($3->'akaBizTagIds'),0)=0 AND NOT COALESCE(($3->>'akaBizNoTag')::boolean,false)) OR COALESCE(akabiz_tag_ids,'{}'::bigint[]) && ARRAY(SELECT jsonb_array_elements_text($3->'akaBizTagIds')::bigint) OR (COALESCE(($3->>'akaBizNoTag')::boolean,false) AND COALESCE(cardinality(akabiz_tag_ids),0)=0))
 ), matched AS %4$s (SELECT id,created_at FROM filtered),
 page AS MATERIALIZED (SELECT * FROM matched WHERE %2$s ORDER BY created_at DESC,id DESC OFFSET $5 LIMIT $6)
 SELECT jsonb_build_object('version',1,'total',%3$s,'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'account_id',c.account_id,'contact_type','person','name',c.f_name,'uid',c.f_uid,'url','','is_delete',false,'is_friend',c.is_friend,'akabiz_tag_ids',c.akabiz_tag_ids,
 'extra_data',c.extra_data||jsonb_build_object('phone',c.f_phone,'groupName',c."f_groupName",'sentCount',c."f_sentCount",'latestSentAt',c."f_latestSentAt",'latestSentDate',to_char(c."f_latestSentAt" AT TIME ZONE 'Asia/Ho_Chi_Minh','DD/MM/YYYY'),'daysSinceLatest',c."f_daysSinceLatest",'latestStatus',c."f_latestStatus",'latestLog',c."f_latestLog",'recipientStatus',c."f_recipientStatus")) ORDER BY p.created_at DESC,p.id DESC) FROM page p JOIN filtered c ON c.id=p.id),'[]'::jsonb),
 'after',(SELECT jsonb_build_object('createdAt',created_at,'id',id::text) FROM page ORDER BY created_at,id LIMIT 1),'hasMore',(SELECT count(*) FROM page)=$6)
 $query$;
 sql:=format(sql,predicate,cursor_clause,count_sql,CASE WHEN p_query->>'countMode'='none' THEN 'NOT MATERIALIZED' ELSE 'MATERIALIZED' END);
 EXECUTE sql INTO result USING p_staff_id,p_organization_id,p_query,actions,page_offset,page_limit;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_read_report_page(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_source text := p_query->>'source';
  v_view text := p_query->>'view';
  v_accounts bigint[];
  v_campaigns bigint[];
  v_actions text[];
  v_from timestamptz := (p_query->>'startIso')::timestamptz;
  v_to timestamptz := (p_query->>'endIso')::timestamptz;
  v_limit integer := coalesce((p_query->>'limit')::integer,1000);
  v_offset integer := coalesce((p_query->>'offset')::integer,0);
  v_count boolean := coalesce((p_query->>'count')::boolean,false);
  v_head boolean := coalesce((p_query->>'head')::boolean,false);
  v_filter jsonb := p_query->'filter';
  v_where text;
  v_table text;
  v_select text;
  v_order text;
  v_rows jsonb := '[]';
  v_total bigint;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF p_staff_id IS NULL OR p_organization_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id AND is_active=true
  ) THEN RAISE EXCEPTION 'report_access_denied' USING ERRCODE='42501'; END IF;
  IF v_source IS NULL OR v_source NOT IN ('results','pending') OR v_view IS NULL OR v_view NOT IN ('summary','details')
    OR v_from IS NULL OR v_to IS NULL OR v_from>=v_to OR v_limit<0 OR v_limit>1000 OR v_offset<0
    OR jsonb_typeof(p_query->'accountIds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_query->'accountIds')>10000
    OR (p_query ? 'campaignIds' AND (jsonb_typeof(p_query->'campaignIds') IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_query->'campaignIds')>200)) THEN
    RAISE EXCEPTION 'invalid_report_query' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(array_agg(value::bigint),'{}') INTO v_accounts FROM jsonb_array_elements_text(p_query->'accountIds');
  SELECT array_agg(value::bigint) INTO v_campaigns FROM jsonb_array_elements_text(p_query->'campaignIds');
  SELECT coalesce(array_agg(value),'{}') INTO v_actions FROM jsonb_array_elements_text(p_query->'actionCodes');
  IF EXISTS (SELECT 1 FROM unnest(v_accounts) requested(id) WHERE NOT EXISTS (
    SELECT 1 FROM public.auto_accounts a WHERE a.id=requested.id AND a.staff_id=p_staff_id
      AND a.organization_id=p_organization_id AND a.is_delete=false
  )) THEN RAISE EXCEPTION 'report_account_access_denied' USING ERRCODE='42501'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_campaigns) requested(id) WHERE NOT EXISTS (
    SELECT 1 FROM public.auto_campaigns c WHERE c.id=requested.id AND c.staff_id=p_staff_id AND c.organization_id=p_organization_id
  )) THEN RAISE EXCEPTION 'report_campaign_access_denied' USING ERRCODE='42501'; END IF;
  IF cardinality(v_accounts)=0 OR (p_query ? 'campaignIds' AND v_campaigns IS NULL) THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'count',CASE WHEN v_count OR v_head THEN 0 ELSE NULL END);
  END IF;

  -- All dynamic fragments below are fixed SQL; every caller value stays a bound parameter.
  IF v_source='results' THEN
    v_table := 'public.auto_campaign_details d';
    v_where := 'd.is_delete=false AND d.account_id=ANY($3) AND d.action_code=ANY($5) AND d.created_at >= $6 AND d.created_at < $7';
    IF v_campaigns IS NOT NULL THEN v_where:=v_where||' AND d.campaign_id=ANY($4)'; END IF;
    IF coalesce((p_query->>'requireCampaign')::boolean,false) THEN
      v_where:=v_where||' AND EXISTS (SELECT 1 FROM public.auto_campaigns c WHERE c.id=d.campaign_id AND c.staff_id=$1 AND c.organization_id=$2)';
    END IF;
    IF v_filter->>'kind'='group' THEN
      IF v_filter->>'group' IS NULL OR v_filter->>'group' NOT IN ('all','success','failure','skipped','pending') THEN
        RAISE EXCEPTION 'invalid_report_group' USING ERRCODE='22023';
      END IF;
      v_where:=v_where||' AND ((($8#>>''{filter,group}'')=''all'' AND d.report_group IN (''success'',''failure'',''skipped'',''pending''))
        OR d.report_group=($8#>>''{filter,group}'') OR (d.report_group IS NULL AND d.status IN
          (SELECT jsonb_array_elements_text($8#>''{filter,legacyStatuses}''))))';
    ELSIF v_filter->>'kind' IN ('status','legacy') THEN
      v_where:=v_where||' AND d.report_group IS DISTINCT FROM ''pending''';
      IF v_filter->>'kind'='status' THEN
        IF (v_filter->>'statusId')::bigint IS NULL OR (v_filter->>'statusId')::bigint<=0 THEN
          RAISE EXCEPTION 'invalid_report_status' USING ERRCODE='22023';
        END IF;
        v_where:=v_where||' AND (d.status_id=($8#>>''{filter,statusId}'')::bigint OR (d.status_id IS NULL
          AND d.status=($8#>>''{filter,legacyStatus}'')))';
      ELSE
        IF jsonb_typeof(v_filter->'status') IS DISTINCT FROM 'string' THEN
          RAISE EXCEPTION 'invalid_report_legacy_status' USING ERRCODE='22023';
        END IF;
        v_where:=v_where||' AND d.status_id IS NULL AND d.status=($8#>>''{filter,status}'')';
      END IF;
    ELSIF v_filter IS NOT NULL AND v_filter<>'null'::jsonb THEN
      RAISE EXCEPTION 'invalid_report_filter' USING ERRCODE='22023';
    END IF;
    v_order:=CASE WHEN v_view='summary' THEN 'd.created_at ASC,d.id ASC' ELSE 'd.created_at DESC,d.id DESC' END;
    IF p_query ? 'afterCreatedAt' THEN
      IF p_query->>'afterId' IS NULL THEN RAISE EXCEPTION 'invalid_report_cursor'; END IF;
      v_where:=v_where||' AND (d.created_at,d.id)'||CASE WHEN v_view='summary' THEN '>' ELSE '<' END
        ||'(($8->>''afterCreatedAt'')::timestamptz,($8->>''afterId'')::bigint)';
    END IF;
    IF v_view='summary' THEN
      v_select:='d.id,d.input_data_id,d.account_id,d.action_code,d.status,d.status_id,d.report_group,d.created_at';
    ELSE
      v_select:='d.id,d.input_data_id,d.campaign_id,d.account_id,d.action_code,d.action_name,d.status,d.error_code,d.log,d.data,d.post_url,d.created_at,
        (SELECT jsonb_build_object(''name'',s.name) FROM public.auto_status s WHERE s.id=d.status_id) AS main_status,
        (SELECT jsonb_build_object(''name'',s.name) FROM public.auto_status s WHERE s.id=d.sub_status_id) AS sub_status,
        (SELECT jsonb_build_object(''id'',c.id,''name'',c.name,''staff_id'',c.staff_id,''organization_id'',c.organization_id)
          FROM public.auto_campaigns c WHERE c.id=d.campaign_id AND c.staff_id=$1 AND c.organization_id=$2) AS auto_campaigns,
        (SELECT jsonb_build_object(''name'',i.name,''uid'',i.uid,''phone'',i.phone,''email'',i.email)
          FROM public.auto_campaign_input_data i JOIN public.auto_campaigns c ON c.id=i.campaign_id
          WHERE i.id=d.input_data_id AND c.staff_id=$1 AND c.organization_id=$2) AS report_input';
    END IF;
  ELSE
    IF v_campaigns IS NULL THEN RAISE EXCEPTION 'report_campaign_scope_required' USING ERRCODE='22023'; END IF;
    v_table:='public.auto_campaign_input_data d JOIN public.auto_campaigns c ON c.id=d.campaign_id';
    v_where:='d.campaign_id=ANY($4) AND d.is_delete=false AND d.status=''chờ xử lý'' AND c.is_delete=false
      AND c.staff_id=$1 AND c.organization_id=$2 AND c.account_id=ANY($3)';
    IF v_view='summary' THEN
      IF p_query->>'ownSchedule' IS NULL THEN RAISE EXCEPTION 'report_schedule_branch_required'; END IF;
      v_where:=v_where||CASE WHEN (p_query->>'ownSchedule')::boolean
        THEN ' AND d.schedule >= $6 AND d.schedule < $7'
        ELSE ' AND d.schedule IS NULL AND c.schedule >= $6 AND c.schedule < $7' END;
      v_select:='d.id,d.campaign_id,d.schedule';
    ELSE
      v_where:=v_where||' AND ((d.schedule >= $6 AND d.schedule < $7) OR (d.schedule IS NULL AND c.schedule >= $6 AND c.schedule < $7))';
      IF cardinality(v_accounts)<>1 OR cardinality(v_actions)<>1 THEN RAISE EXCEPTION 'report_pending_cell_required'; END IF;
      v_where:=v_where||' AND NOT EXISTS (SELECT 1 FROM public.auto_campaign_details r WHERE r.input_data_id=d.id
        AND r.account_id=ANY($3) AND r.action_code=ANY($5) AND r.is_delete=false AND r.report_group=''pending''
        AND r.created_at >= $6 AND r.created_at < $7)';
      v_select:='d.id,d.campaign_id,d.name,d.phone,d.uid,d.email,d.note,d.schedule,d.created_at';
    END IF;
    v_order:='d.campaign_id ASC,d.id ASC';
    IF p_query ? 'afterId' THEN
      IF p_query->>'afterCampaignId' IS NULL THEN RAISE EXCEPTION 'invalid_report_pending_cursor'; END IF;
      v_where:=v_where||' AND (d.campaign_id,d.id)>(($8->>''afterCampaignId'')::bigint,($8->>''afterId'')::bigint)';
    END IF;
  END IF;
  IF v_count OR v_head THEN
    EXECUTE 'SELECT count(*) FROM '||v_table||' WHERE '||v_where INTO v_total
      USING p_staff_id,p_organization_id,v_accounts,v_campaigns,v_actions,v_from,v_to,p_query;
  END IF;
  IF NOT v_head AND v_limit>0 THEN
    EXECUTE 'SELECT coalesce(jsonb_agg(to_jsonb(r)),''[]''::jsonb) FROM (SELECT '||v_select||' FROM '||v_table
      ||' WHERE '||v_where||' ORDER BY '||v_order||' LIMIT $9 OFFSET $10) r' INTO v_rows
      USING p_staff_id,p_organization_id,v_accounts,v_campaigns,v_actions,v_from,v_to,p_query,v_limit,v_offset;
  END IF;
  RETURN jsonb_build_object('rows',v_rows,'count',v_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_recover_campaign_runtime_unit_leases(p_staff_id bigint, p_runtime_target text, p_platform_scope text DEFAULT 'all'::text)
 RETURNS TABLE(ok boolean, reason text, recovered_lease_count bigint, requeued_input_count bigint, db_now timestamp with time zone, vietnam_date_key date)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_random record;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_platform_scope text := lower(btrim(COALESCE(p_platform_scope, '')));
  v_organization_id bigint;
  v_candidate record;
  v_locked_token uuid;
  v_locked_input_data_ids bigint[];
  v_recovered_lease_count bigint := 0;
  v_requeued_input_count bigint := 0;
  v_row_count bigint := 0;
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'staff ID must be a positive integer';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF v_platform_scope NOT IN ('all', 'zalo') THEN
    RAISE EXCEPTION 'platform scope must be all or zalo';
  END IF;

  -- Startup recovery is cleanup and therefore remains available for an
  -- inactive staff row. The caller must invoke it only after its existing
  -- runtime-specific recovery has proved the scheduler process idle.
  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', 0::bigint, 0::bigint,
      v_now, v_vietnam_date;
    RETURN;
  END IF;

  FOR v_candidate IN
    SELECT campaign.id AS campaign_id,
      campaign.account_id,
      campaign.runtime_unit_token,
      campaign.runtime_unit_input_data_ids
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_accounts AS account
      ON account.id = campaign.account_id
     AND account.staff_id = campaign.staff_id
    WHERE campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
      AND (
        v_platform_scope = 'all'
        OR lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      )
      AND (
        campaign.organization_id IS NULL
        OR campaign.organization_id = v_organization_id
      )
      AND (
        account.organization_id IS NULL
        OR account.organization_id = v_organization_id
      )
      AND (
        (
          v_runtime_target = 'server'
          AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
          AND COALESCE(account.is_zalo_show_web, false) = false
          AND COALESCE(account.is_zalo_server, false) = true
        )
        OR (
          v_runtime_target = 'desktop'
          AND NOT (
            lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
            AND COALESCE(account.is_zalo_server, false) = true
          )
        )
      )
    ORDER BY campaign.id
  LOOP
    PERFORM public.aka_agent_lock_campaign_input_serialization(
      v_candidate.campaign_id
    );

    IF cardinality(COALESCE(
      v_candidate.runtime_unit_input_data_ids,
      ARRAY[]::bigint[]
    )) > 0 THEN
      PERFORM input_data.id
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.id = ANY(v_candidate.runtime_unit_input_data_ids)
        AND input_data.campaign_id = v_candidate.campaign_id
      ORDER BY input_data.id
      FOR UPDATE OF input_data;
    END IF;

    SELECT campaign.runtime_unit_token,
      campaign.runtime_unit_input_data_ids
    INTO v_locked_token, v_locked_input_data_ids
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_accounts AS account
      ON account.id = campaign.account_id
     AND account.staff_id = campaign.staff_id
    WHERE campaign.id = v_candidate.campaign_id
      AND campaign.account_id = v_candidate.account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token = v_candidate.runtime_unit_token
      AND (
        v_platform_scope = 'all'
        OR lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      )
      AND (
        campaign.organization_id IS NULL
        OR campaign.organization_id = v_organization_id
      )
      AND (
        account.organization_id IS NULL
        OR account.organization_id = v_organization_id
      )
      AND (
        (
          v_runtime_target = 'server'
          AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
          AND COALESCE(account.is_zalo_show_web, false) = false
          AND COALESCE(account.is_zalo_server, false) = true
        )
        OR (
          v_runtime_target = 'desktop'
          AND NOT (
            lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
            AND COALESCE(account.is_zalo_server, false) = true
          )
        )
      )
    FOR UPDATE OF campaign, account;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    PERFORM private.facebook_random_unit_recover(v_candidate.campaign_id,v_candidate.account_id,v_locked_token);

    IF cardinality(COALESCE(v_locked_input_data_ids, ARRAY[]::bigint[])) > 0 THEN
      UPDATE public.auto_campaign_input_data AS input_data
      SET status = 'chờ xử lý', date_action = NULL
      WHERE input_data.id = ANY(v_locked_input_data_ids)
        AND input_data.campaign_id = v_candidate.campaign_id
        AND input_data.status = 'đang chạy';
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_requeued_input_count := v_requeued_input_count + v_row_count;
    END IF;

    v_now := clock_timestamp();
    UPDATE public.auto_campaigns AS campaign
    SET runtime_unit_token = NULL,
      runtime_unit_vietnam_date = NULL,
      runtime_unit_claimed_at = NULL,
      runtime_unit_input_data_ids = NULL,
      updated_at = v_now
    WHERE campaign.id = v_candidate.campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token = v_locked_token;

    IF FOUND THEN
      v_recovered_lease_count := v_recovered_lease_count + 1;
    END IF;
  END LOOP;

  -- Same startup recovery proof/locks; includes orphan turns when mode is off.
  IF v_runtime_target='desktop' AND v_platform_scope='all' THEN
    FOR v_random IN SELECT * FROM private.facebook_random_orphan_turns(p_staff_id,v_organization_id) ORDER BY id
    LOOP
      PERFORM public.aka_agent_lock_campaign_input_serialization(v_random.id);
      PERFORM 1 FROM public.auto_campaigns cc JOIN public.auto_accounts aa ON aa.id=cc.account_id AND aa.staff_id=cc.staff_id
        WHERE cc.id=v_random.id AND cc.account_id=v_random.account_id AND cc.staff_id=p_staff_id AND aa.flatform_type='facebook'
          AND (cc.organization_id IS NULL OR cc.organization_id=v_organization_id)
          AND (aa.organization_id IS NULL OR aa.organization_id=v_organization_id)
          AND cc.runtime_claim_token IS NULL AND cc.runtime_unit_token IS NULL AND cc.status<>'đang chạy'
        FOR UPDATE OF cc,aa;
      IF FOUND THEN PERFORM private.facebook_random_finalize_turn(v_random.id,v_random.account_id,v_random.claim::uuid,v_random.unit::uuid,true); END IF;
    END LOOP;
  END IF;
  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  RETURN QUERY SELECT
    true, 'recovered', v_recovered_lease_count, v_requeued_input_count,
    v_now, v_vietnam_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_recover_staff_credentials(p_secret text, p_fingerprint_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '8s'
AS $function$
DECLARE s public.org_staff%ROWTYPE; r private.aka_agent_staff_recovery%ROWTYPE; lock_key bigint;
BEGIN
  IF coalesce(p_secret,'') !~ '^[a-f0-9]{64}$' OR coalesce(p_fingerprint_hash,'') !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'staff_recovery_invalid';
  END IF;
  SELECT * INTO r FROM private.aka_agent_staff_recovery
    WHERE secret_hash=encode(extensions.digest(p_secret,'sha256'),'hex') AND fingerprint_hash=p_fingerprint_hash;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_recovery_invalid'; END IF;
  IF (SELECT count(*) FROM private.aka_agent_staff_recovery WHERE secret_hash=r.secret_hash AND fingerprint_hash=p_fingerprint_hash)<>1 THEN
    RAISE EXCEPTION 'staff_recovery_invalid';
  END IF;
  -- Same hash -> staff -> proof order as enrollment; no recovery concurrent with a new collision.
  FOR lock_key IN SELECT DISTINCT hashtextextended(k,73103) FROM unnest(ARRAY['2:'||p_fingerprint_hash,'3:'||p_fingerprint_hash]) k ORDER BY 1 LOOP PERFORM pg_advisory_xact_lock(lock_key); END LOOP;
  SELECT * INTO s FROM public.org_staff WHERE id=r.staff_id FOR SHARE;
  -- Recheck the token after locking staff, following the same staff -> recovery
  -- order as registration/password changes. A removed/rebound token cannot win.
  IF NOT FOUND OR NOT s.is_active OR s.deleted_at IS NOT NULL OR s.organization_id<>r.organization_id
    OR s.aka_agent_device_fingerprint_hash IS DISTINCT FROM p_fingerprint_hash
    OR NOT public.aka_agent_staff_time_allowed(s.id)
    OR encode(extensions.digest(s.password,'sha256'),'hex') IS DISTINCT FROM r.credential_hash
    OR NOT EXISTS (SELECT 1 FROM private.aka_agent_staff_recovery x WHERE x.staff_id=r.staff_id AND x.secret_hash=r.secret_hash)
    THEN
    RAISE EXCEPTION 'staff_recovery_invalid';
  END IF;
  IF private.aka_agent_device_ambiguous(s.aka_agent_device_identity_version,p_fingerprint_hash,s.id,false) THEN
    RETURN jsonb_build_object('status','manual_login_required');
  END IF;
  RETURN jsonb_build_object('username',s.username,'password',s.password);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_remove_data_group_members(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_group_id bigint, p_membership_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_request_hash text;
  v_requested integer;
  v_count integer := 0;
  v_result jsonb;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR COALESCE(cardinality(p_membership_ids), 0) = 0
    OR EXISTS (SELECT 1 FROM unnest(p_membership_ids) AS value(id) WHERE id IS NULL OR id <= 0)
  THEN RAISE EXCEPTION 'invalid_data_group_member_mutation'; END IF;
  SELECT count(DISTINCT id)::integer INTO v_requested FROM unnest(p_membership_ids) AS value(id);

  SELECT * INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'remove_members', 'groupId', p_group_id,
    'membershipIds', (SELECT jsonb_agg(id ORDER BY id) FROM (
      SELECT DISTINCT id FROM unnest(p_membership_ids) AS value(id)
    ) AS sorted)
  )::text);
  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, kind, request_hash, status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'remove_members', p_group_id, 'manual', v_request_hash,
    'processing', p_staff_id, p_organization_id
  ) ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;
  IF NOT FOUND THEN
    SELECT * INTO v_batch FROM public.auto_data_ingest_batches
    WHERE staff_id = p_staff_id AND organization_id = p_organization_id
      AND request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'remove_members' OR v_batch.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  IF (
    SELECT count(DISTINCT member.id)
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id AND member.id = ANY(p_membership_ids)
  ) <> v_requested THEN
    RAISE EXCEPTION 'data_group_membership_not_found';
  END IF;

  SELECT count(*)::integer INTO v_count
  FROM public.auto_account_contact_group_members AS member
  WHERE member.group_id = v_group.id AND member.id = ANY(p_membership_ids)
    AND member.is_delete = false;
  IF v_count > 0 THEN
    UPDATE public.auto_account_contact_groups
    SET revision = revision + 1, updated_at = now()
    WHERE id = v_group.id RETURNING * INTO v_group;
    UPDATE public.auto_account_contact_group_members
    SET is_delete = true, change_revision = v_group.revision, updated_at = now()
    WHERE group_id = v_group.id AND id = ANY(p_membership_ids) AND is_delete = false;
    UPDATE public.auto_account_contact_group_member_origins AS origin
    SET is_current = false, updated_at = now()
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id AND member.id = ANY(p_membership_ids)
      AND origin.membership_id = member.id AND origin.is_current = true;
  END IF;

  v_result := jsonb_build_object(
    'success', true, 'count', v_count, 'group_revision', v_group.revision
  );
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = v_result, updated_at = now()
  WHERE id = v_batch.id;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_save_upload_contact_datasets(p_staff_id bigint, p_organization_id bigint, p_account_ids bigint[], p_name text, p_flatform_type text, p_contact_type text, p_action_id text, p_import_source text, p_source_link text, p_description text, p_source_key_prefix text, p_contacts jsonb, p_extra_data jsonb, p_data_type_category_item_id bigint DEFAULT NULL::bigint)
 RETURNS SETOF auto_account_contacts_dataset
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  v_previous_context text :=
    current_setting('aka_agent.data_type_category_item_id', true);
  v_phone_type bigint :=
    public.aka_agent_data_type_category_item_id('phone');
  v_effective_type bigint := p_data_type_category_item_id;
  v_semantic_source_key_prefix text;
BEGIN
  IF p_data_type_category_item_id IS NOT NULL
    AND NOT public.aka_agent_is_data_type_category_item(
      p_data_type_category_item_id, true
    )
  THEN
    RAISE EXCEPTION 'invalid_data_type_category_item';
  END IF;
  IF p_action_id = 'zalo_add_group_member'
    AND (
      p_contact_type IS DISTINCT FROM 'phone'
      OR COALESCE(p_data_type_category_item_id, v_phone_type)
        IS DISTINCT FROM v_phone_type
    )
  THEN
    RAISE EXCEPTION 'zalo_add_group_member_upload_requires_phone';
  END IF;
  IF p_action_id = 'zalo_add_group_member' THEN
    v_effective_type := v_phone_type;
  END IF;
  IF p_action_id = 'facebook_comment_seeding'
    AND p_data_type_category_item_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'facebook_comment_seeding_upload_must_be_unrestricted';
  END IF;
  IF p_action_id = 'facebook_comment_seeding' THEN
    v_effective_type := NULL;
  ELSIF v_effective_type IS NULL THEN
    v_effective_type := public.aka_agent_derive_dataset_data_type(
      'upload',
      p_flatform_type,
      p_contact_type,
      'upload_data',
      COALESCE(p_extra_data, '{}'::jsonb)
        || jsonb_build_object('actionId', p_action_id)
    );
  END IF;

  SELECT btrim(p_source_key_prefix)
    || ':data-type:'
    || COALESCE(category_item.code, 'unrestricted')
  INTO v_semantic_source_key_prefix
  FROM (SELECT 1) AS singleton
  LEFT JOIN public.category_item AS category_item
    ON category_item.id = v_effective_type;

  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_effective_type::text, 'null'),
    true
  );
  RETURN QUERY
  SELECT *
  FROM public.aka_agent_save_upload_contact_datasets_v205_internal(
    p_staff_id,
    p_organization_id,
    p_account_ids,
    p_name,
    p_flatform_type,
    p_contact_type,
    p_action_id,
    p_import_source,
    p_source_link,
    p_description,
    v_semantic_source_key_prefix,
    p_contacts,
    p_extra_data
  );
  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_previous_context, ''),
    true
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'aka_agent.data_type_category_item_id',
    COALESCE(v_previous_context, ''),
    true
  );
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_send_exclusion_groups(p_staff_id bigint, p_organization_id bigint, p_account_id bigint, p_operation text, p_payload jsonb, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '15s'
AS $function$
DECLARE gid bigint; revision bigint; r jsonb; prior jsonb; request_id uuid;
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF NOT EXISTS(SELECT 1 FROM public.auto_accounts WHERE id=p_account_id AND staff_id=p_staff_id AND organization_id=p_organization_id AND flatform_type='zalo' AND NOT is_delete) THEN RAISE EXCEPTION 'send_exclusion_account_not_found'; END IF;
 IF p_operation='list' THEN
  RETURN jsonb_build_object('catalog',public.aka_agent_internal_send_exclusion_catalog(),
   'options',public.aka_agent_internal_send_exclusion_options(p_staff_id,p_organization_id,p_account_id),
   'groups',COALESCE((SELECT jsonb_agg(public.aka_agent_internal_send_exclusion_group(id) ORDER BY name,id) FROM public.auto_campaign_send_exclusion_groups WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND account_id=p_account_id AND NOT is_delete),'[]'),
   'blocklists',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'count',(SELECT count(*) FROM public.auto_account_contact_group_members m JOIN public.auto_account_contacts c ON c.id=m.contact_id WHERE m.group_id=g.id AND NOT m.is_delete AND NOT c.is_delete AND c.account_id=p_account_id AND c.staff_id=p_staff_id AND c.organization_id=p_organization_id)) ORDER BY g.name,g.id)
   FROM public.auto_account_contact_groups g WHERE g.account_id=p_account_id AND g.staff_id=p_staff_id AND g.organization_id=p_organization_id AND NOT g.is_delete AND g.purpose='zalo_friend_blocklist'),'[]'));
 ELSIF p_operation<>'save' THEN RAISE EXCEPTION 'send_exclusion_operation_invalid'; END IF;
 PERFORM public.aka_agent_internal_validate_send_exclusion_rules(p_payload->'rules',p_staff_id,p_organization_id,p_account_id);
 gid:=(p_payload->>'id')::bigint;
 IF gid IS NULL THEN
  request_id:=(p_payload->>'requestId')::uuid;
  IF request_id IS NULL THEN RAISE EXCEPTION 'send_exclusion_request_id_required'; END IF;
  INSERT INTO public.auto_campaign_send_exclusion_groups(staff_id,organization_id,account_id,name,match_mode,create_request_id)
   VALUES(p_staff_id,p_organization_id,p_account_id,btrim(p_payload->>'name'),p_payload->>'matchMode',request_id)
   ON CONFLICT(staff_id,organization_id,account_id,create_request_id) DO NOTHING RETURNING id INTO gid;
  IF gid IS NULL THEN
   SELECT public.aka_agent_internal_send_exclusion_group(id) INTO prior FROM public.auto_campaign_send_exclusion_groups
    WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND account_id=p_account_id AND create_request_id=request_id AND NOT is_delete;
   IF prior IS NULL OR prior->>'name' IS DISTINCT FROM btrim(p_payload->>'name') OR prior->>'matchMode' IS DISTINCT FROM p_payload->>'matchMode'
    OR (SELECT jsonb_agg(v ORDER BY v->>'fieldId') FROM jsonb_array_elements(prior->'rules') v) IS DISTINCT FROM (SELECT jsonb_agg(v ORDER BY v->>'fieldId') FROM jsonb_array_elements(p_payload->'rules') v)
   THEN RAISE EXCEPTION 'send_exclusion_revision_conflict'; END IF;
   RETURN prior;
  END IF;
 ELSE
  UPDATE public.auto_campaign_send_exclusion_groups g SET name=btrim(p_payload->>'name'),match_mode=p_payload->>'matchMode',revision=g.revision+1,updated_at=now()
   WHERE g.id=gid AND g.staff_id=p_staff_id AND g.organization_id=p_organization_id AND g.account_id=p_account_id AND NOT g.is_delete AND g.revision=(p_payload->>'revision')::bigint RETURNING g.revision INTO revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'send_exclusion_revision_conflict'; END IF;
  DELETE FROM public.auto_campaign_send_exclusion_rules WHERE group_id=gid;
 END IF;
 FOR r IN SELECT * FROM jsonb_array_elements(p_payload->'rules') LOOP
  INSERT INTO public.auto_campaign_send_exclusion_rules(group_id,field_id,operator_id,value,is_enabled,sort_order)
  VALUES(gid,(r->>'fieldId')::bigint,(r->>'operatorId')::bigint,COALESCE(r->'value','null'),COALESCE((r->>'isEnabled')::boolean,false),COALESCE((r->>'sortOrder')::integer,0));
 END LOOP;
 RETURN public.aka_agent_internal_send_exclusion_group(gid);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_automation_active(p_staff_id bigint, p_organization_id bigint, p_automation_id bigint, p_is_active boolean, p_auth_username text DEFAULT NULL::text, p_auth_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_rule public.auto_automation%ROWTYPE;
  v_locked_group_id bigint;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'auto_automation_graph:' || p_staff_id::text || ':' || p_organization_id::text,
    0
  ));

  SELECT *
  INTO v_rule
  FROM public.auto_automation AS automation
  WHERE automation.id = p_automation_id
    AND automation.staff_id = p_staff_id
    AND automation.organization_id = p_organization_id
    AND automation.is_delete = false;
  IF NOT FOUND THEN RAISE EXCEPTION 'automation_not_found'; END IF;

  IF v_rule.target_campaign_id IS NOT NULL THEN
    RETURN public.aka_agent_set_automation_active_v201_campaign_internal(
      p_staff_id, p_organization_id, p_automation_id, p_is_active,
      p_auth_username, p_auth_password
    );
  END IF;

  IF COALESCE(p_is_active, false) THEN
    v_locked_group_id := v_rule.target_data_group_id;
    IF v_locked_group_id IS NULL THEN
      RAISE EXCEPTION 'automation_destination_required';
    END IF;
    PERFORM contact_group.id
    FROM public.auto_account_contact_groups AS contact_group
    WHERE contact_group.id = v_locked_group_id
      AND contact_group.staff_id = p_staff_id
      AND contact_group.organization_id = p_organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false
    FOR SHARE OF contact_group;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid_target_data_group';
    END IF;
  END IF;

  SELECT *
  INTO v_rule
  FROM public.auto_automation AS automation
  WHERE automation.id = p_automation_id
    AND automation.staff_id = p_staff_id
    AND automation.organization_id = p_organization_id
    AND automation.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'automation_not_found';
  END IF;

  IF v_rule.target_campaign_id IS NOT NULL THEN
    RETURN public.aka_agent_set_automation_active_v201_campaign_internal(
      p_staff_id, p_organization_id, p_automation_id, p_is_active,
      p_auth_username, p_auth_password
    );
  END IF;

  IF COALESCE(p_is_active, false) THEN
    IF v_rule.target_data_group_id IS NULL
      OR v_rule.target_data_group_id IS DISTINCT FROM v_locked_group_id
    THEN
      RAISE EXCEPTION 'automation_destination_required';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.auto_campaigns AS campaign
      JOIN public.auto_campaign_actions AS campaign_action
        ON campaign_action.id = campaign.action_id
       AND campaign_action.is_active = true
       AND campaign_action.is_delete = false
      JOIN public.auto_accounts AS account
        ON account.id = campaign.account_id
       AND account.staff_id = p_staff_id
       AND account.organization_id = p_organization_id
       AND account.is_delete = false
      JOIN public.auto_automation_data_types AS data_type
        ON data_type.code = v_rule.data_type_code
       AND data_type.is_active = true
       AND data_type.is_delete = false
      JOIN public.auto_campaign_action_data_types AS mapping
        ON mapping.campaign_action_id = campaign.action_id
       AND mapping.data_type_code = v_rule.data_type_code
       AND mapping.can_source = true
       AND mapping.is_active = true
       AND mapping.is_delete = false
      WHERE campaign.id = v_rule.source_campaign_id
        AND campaign.staff_id = p_staff_id
        AND campaign.organization_id = p_organization_id
        AND campaign.is_delete = false
    ) THEN
      RAISE EXCEPTION 'source_campaign_data_type_not_supported';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.auto_automation_trigger_statuses AS trigger_status
      WHERE trigger_status.automation_id = v_rule.id
    ) THEN
      RAISE EXCEPTION 'automation_trigger_status_required';
    END IF;
    IF v_rule.schedule_mode = 'fixed_at'
      AND v_rule.fixed_at <= clock_timestamp()
    THEN
      RAISE EXCEPTION 'invalid_fixed_schedule';
    END IF;
  END IF;

  UPDATE public.auto_automation AS automation
  SET is_active = COALESCE(p_is_active, false),
      activated_at = CASE
        WHEN COALESCE(p_is_active, false) AND NOT automation.is_active
          THEN clock_timestamp()
        ELSE automation.activated_at
      END,
      updated_at = clock_timestamp()
  WHERE automation.id = v_rule.id;

  RETURN public.auto_automation_to_json(
    v_rule.id, p_staff_id, p_organization_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_desktop_campaign_status_v2(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_target_status text)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_target_status text := btrim(COALESCE(p_target_status, ''));
  v_organization_id bigint;
  v_campaign_found boolean := false;
  v_campaign_status text;
  v_account_status text;
  v_campaign_is_delete boolean;
  v_account_is_delete boolean;
  v_account_is_active boolean;
  v_account_platform text;
  v_account_is_zalo_server boolean;
  v_runtime_claim_token uuid;
  v_runtime_claim_target text;
  v_runtime_unit_token uuid;
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_reason text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_target_status NOT IN ('tạm dừng', 'chờ xử lý') THEN
    RAISE EXCEPTION 'target status must be paused or pending';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true
  ;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.status, account.status,
    COALESCE(campaign.is_delete, false),
    COALESCE(account.is_delete, false),
    COALESCE(account.is_active, false),
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_claim_token,
    campaign.runtime_claim_target,
    campaign.runtime_unit_token
  INTO v_campaign_status, v_account_status,
    v_campaign_is_delete, v_account_is_delete, v_account_is_active,
    v_account_platform, v_account_is_zalo_server,
    v_runtime_claim_token, v_runtime_claim_target, v_runtime_unit_token
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;
  v_campaign_found := FOUND;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  IF NOT v_campaign_found THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date;
    RETURN;
  END IF;

  IF v_account_platform = 'zalo' AND v_account_is_zalo_server THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_campaign_is_delete THEN
    v_reason := 'campaign_deleted';
  ELSIF v_account_is_delete AND v_target_status <> 'tạm dừng' THEN
    v_reason := 'account_deleted';
  ELSIF NOT v_account_is_active AND v_target_status <> 'tạm dừng' THEN
    v_reason := 'account_inactive';
  ELSIF v_target_status = 'tạm dừng' THEN
    IF v_campaign_status = 'tạm dừng' THEN
      v_reason := 'already_target';
    ELSIF (v_campaign_status = 'đang chạy' AND NOT v_account_is_delete)
      OR v_runtime_claim_token IS NOT NULL
    THEN
      v_reason := 'runtime_busy';
    ELSIF v_runtime_unit_token IS NOT NULL THEN
      v_reason := 'unit_lease_busy';
    ELSIF v_campaign_status IS DISTINCT FROM 'chờ xử lý'
      AND NOT (v_account_is_delete AND v_campaign_status = 'đang chạy') THEN
      v_reason := 'invalid_transition';
    ELSE
      UPDATE public.auto_campaigns AS campaign
      SET status = 'tạm dừng',
        note = CASE
          WHEN campaign.data_target_source_mode = 'data_group'
            AND campaign.note IN ('Chờ data phù hợp', 'Chờ data mới')
          THEN campaign.note
          ELSE NULL
        END,
        updated_at = v_now
      WHERE campaign.id = p_campaign_id
        AND campaign.account_id = p_account_id
        AND campaign.staff_id = p_staff_id
        AND (campaign.status = 'chờ xử lý'
          OR (v_account_is_delete AND campaign.status = 'đang chạy'))
        AND campaign.runtime_claim_token IS NULL
        AND campaign.runtime_unit_token IS NULL;
      IF FOUND THEN
        v_campaign_status := 'tạm dừng';
        v_reason := 'updated';
      ELSE
        v_reason := 'runtime_busy';
      END IF;
    END IF;
  ELSE
    IF v_campaign_status = 'đang chạy' THEN
      v_reason := 'runtime_busy';
    ELSIF v_runtime_unit_token IS NOT NULL THEN
      v_reason := 'unit_lease_busy';
    ELSIF v_runtime_claim_token IS NOT NULL
      AND v_runtime_claim_target IS DISTINCT FROM 'server'
    THEN
      v_reason := 'runtime_busy';
    ELSIF NOT v_account_is_active THEN
      v_reason := 'account_inactive';
    ELSIF v_campaign_status IS DISTINCT FROM 'tạm dừng' THEN
      v_reason := 'invalid_transition';
    ELSE
      UPDATE public.auto_campaigns AS campaign
      SET status = 'chờ xử lý', note = NULL, updated_at = v_now
      WHERE campaign.id = p_campaign_id
        AND campaign.account_id = p_account_id
        AND campaign.staff_id = p_staff_id
        AND campaign.status = 'tạm dừng'
        AND (
          campaign.runtime_claim_token IS NULL
          OR campaign.runtime_claim_target = 'server'
        )
        AND campaign.runtime_unit_token IS NULL;
      IF FOUND THEN
        v_campaign_status := 'chờ xử lý';
        v_reason := 'updated';
      ELSE
        v_reason := 'runtime_busy';
      END IF;
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_reason IN ('updated', 'already_target'),
    v_reason,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_zalo_server_account_status(p_account_id bigint, p_staff_id bigint, p_status text)
 RETURNS TABLE(ok boolean, reason text, account_id bigint, account_status text, campaign_status text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_status text := lower(btrim(COALESCE(p_status, '')));
  v_organization_id bigint;
  v_capabilities record;
  v_account_status text;
  v_campaign_status text;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_target_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RETURN QUERY SELECT false, 'invalid_transition', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
  THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT account.status INTO v_account_status
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found', p_account_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT campaign.status INTO v_campaign_status
  FROM public.auto_campaigns AS campaign
  WHERE campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = v_organization_id
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND campaign.status IN ('đang chạy', 'tạm dừng', 'chờ xử lý')
  ORDER BY CASE campaign.status WHEN 'đang chạy' THEN 0 WHEN 'tạm dừng' THEN 1 ELSE 2 END,
    campaign.updated_at DESC NULLS LAST, campaign.id DESC
  LIMIT 1;

  IF v_account_status = v_target_status THEN
    RETURN QUERY SELECT true, 'already_target', p_account_id, v_account_status, v_campaign_status;
    RETURN;
  END IF;
  IF (v_target_status = 'tạm dừng' AND v_account_status IN ('chờ xử lý', 'đang chạy'))
    OR (v_target_status = 'chờ xử lý' AND v_account_status = 'tạm dừng')
  THEN
    UPDATE public.auto_accounts SET status = v_target_status, updated_at = now()
    WHERE id = p_account_id;
    RETURN QUERY SELECT true, 'updated', p_account_id, v_target_status, v_campaign_status;
    RETURN;
  END IF;
  RETURN QUERY SELECT false, 'invalid_transition', p_account_id, v_account_status, v_campaign_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_set_zalo_server_campaign_status(p_campaign_id bigint, p_staff_id bigint, p_status text)
 RETURNS TABLE(ok boolean, reason text, campaign_id bigint, campaign_status text, account_status text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_status text := lower(btrim(COALESCE(p_status, '')));
  v_organization_id bigint;
  v_capabilities record;
  v_campaign_status text;
  v_account_status text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Campaign and staff IDs must be positive integers';
  END IF;
  IF v_target_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RETURN QUERY SELECT false, 'invalid_transition', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
  THEN
    RETURN QUERY SELECT false, 'runtime_not_owner', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;

  SELECT campaign.status, account.status
  INTO v_campaign_status, v_account_status
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND campaign.action_id LIKE 'zalo\_%' ESCAPE '\'
    AND COALESCE(campaign.is_delete, false) = false
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND COALESCE(account.is_zalo_server, false) = true
    AND (v_target_status = 'tạm dừng' OR COALESCE(account.is_delete, false) = false)
  FOR UPDATE OF campaign, account;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'not_found', p_campaign_id, NULL::text, NULL::text;
    RETURN;
  END IF;
  IF v_campaign_status = v_target_status THEN
    RETURN QUERY SELECT true, 'already_target', p_campaign_id, v_campaign_status, v_account_status;
    RETURN;
  END IF;
  IF (v_target_status = 'tạm dừng' AND v_campaign_status IN ('chờ xử lý', 'đang chạy'))
    OR (v_target_status = 'chờ xử lý' AND v_campaign_status = 'tạm dừng')
  THEN
    UPDATE public.auto_campaigns AS campaign
    SET
      status = v_target_status,
      note = CASE
        WHEN campaign.data_target_source_mode = 'data_group'
          AND btrim(COALESCE(campaign.note, '')) IN ('Chờ data phù hợp', 'Chờ data mới')
        THEN campaign.note
        ELSE NULL
      END,
      updated_at = now()
    WHERE campaign.id = p_campaign_id;
    RETURN QUERY SELECT true, 'updated', p_campaign_id, v_target_status, v_account_status;
    RETURN;
  END IF;
  RETURN QUERY SELECT false, 'invalid_transition', p_campaign_id, v_campaign_status, v_account_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_settle_action_results_v1(p_staff_id bigint, p_campaign_id bigint, p_account_id bigint, p_claim_token uuid, p_unit_token uuid, p_input_data_id bigint, p_detail_ids bigint[], p_input_patch jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
 c public.auto_campaigns%ROWTYPE;
 i public.auto_campaign_input_data%ROWTYPE;
 d public.auto_campaign_details%ROWTYPE;
 v_ids bigint[];
 v_bad text:='ignore'; v_effect text:='none'; v_committed boolean:=false; v_reset_before boolean:=false;
 v_existing jsonb; v_settlement jsonb; v_count integer; v_status text;
BEGIN
 IF p_claim_token IS NULL OR p_unit_token IS NULL OR (COALESCE(cardinality(p_detail_ids),0)=0 AND (p_input_patch->'suppressedResult' IS NULL))
   OR array_position(p_detail_ids,NULL) IS NOT NULL
   OR (p_input_patch IS NOT NULL AND jsonb_typeof(p_input_patch)<>'object')
 THEN RAISE EXCEPTION 'action_result_settlement_invalid'; END IF;
 PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_scope_invalid'; END IF;
 PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
 IF p_input_data_id IS NOT NULL THEN
   SELECT * INTO i FROM public.auto_campaign_input_data WHERE id=p_input_data_id AND campaign_id=p_campaign_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'action_result_input_invalid'; END IF;
 END IF;
 SELECT x.* INTO c FROM public.auto_campaigns x JOIN public.auto_accounts a ON a.id=p_account_id
   AND a.staff_id=x.staff_id AND a.organization_id IS NOT DISTINCT FROM x.organization_id
 WHERE x.id=p_campaign_id AND x.staff_id=p_staff_id AND p_account_id IN (x.account_id,x.secondary_account_id)
   AND x.runtime_claim_token=p_claim_token AND x.runtime_unit_token=p_unit_token
   AND x.runtime_unit_claimed_at IS NOT NULL FOR UPDATE OF x;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_claim_invalid'; END IF;
 IF p_input_data_id IS NOT NULL AND NOT COALESCE(p_input_data_id=ANY(c.runtime_unit_input_data_ids),false)
 THEN RAISE EXCEPTION 'action_result_input_not_in_unit'; END IF;
 IF p_input_patch ? 'suppressedResult' THEN
   v_effect:=p_input_patch->'suppressedResult'->>'inputEffect';
   IF v_effect IS NULL OR v_effect NOT IN ('complete','pause','requeue','none') THEN RAISE EXCEPTION 'action_result_suppression_invalid'; END IF;
   v_committed:=COALESCE(p_input_patch->'suppressedResult'->>'operationState','unknown')<>'not_committed';
 END IF;
 SELECT coalesce(array_agg(DISTINCT id ORDER BY id),'{}'::bigint[]) INTO v_ids FROM unnest(p_detail_ids) id;
 IF cardinality(v_ids)<>cardinality(p_detail_ids) THEN RAISE EXCEPTION 'action_result_settlement_duplicate_id'; END IF;
 IF (SELECT count(*) FROM public.auto_campaign_details WHERE id=ANY(v_ids) AND campaign_id=p_campaign_id
    AND account_id=p_account_id AND input_data_id IS NOT DISTINCT FROM p_input_data_id
    AND policy_snapshot->>'unitKey'=md5(p_unit_token::text))<>cardinality(v_ids)
 THEN RAISE EXCEPTION 'action_result_settlement_scope_invalid'; END IF;
 IF EXISTS (SELECT 1 FROM public.auto_campaign_details sibling
   WHERE sibling.campaign_id=p_campaign_id
     AND ((p_input_data_id IS NULL AND sibling.input_data_id IS NULL) OR sibling.input_data_id=p_input_data_id)
     AND sibling.policy_snapshot->>'unitKey'=md5(p_unit_token::text) AND NOT sibling.id=ANY(v_ids))
 THEN RAISE EXCEPTION 'action_result_settlement_incomplete'; END IF;
 FOR d IN SELECT * FROM public.auto_campaign_details WHERE id=ANY(v_ids) ORDER BY id FOR UPDATE LOOP
   v_reset_before:=v_reset_before OR COALESCE(d.policy_snapshot->'badTargetResetBefore'='true'::jsonb,false);
   IF d.policy_snapshot->>'badTargetEffect'='increment' THEN v_bad:='increment';
   ELSIF d.policy_snapshot->>'badTargetEffect'='reset' AND v_bad='ignore' THEN v_bad:='reset'; END IF;
   IF d.policy_snapshot->>'inputEffect'='pause' THEN v_effect:='pause';
   ELSIF d.policy_snapshot->>'inputEffect'='requeue' AND v_effect<>'pause' THEN v_effect:='requeue';
   ELSIF d.policy_snapshot->>'inputEffect'='complete' AND v_effect='none' THEN v_effect:='complete'; END IF;
   v_committed:=v_committed OR d.policy_snapshot->>'operationState'<>'not_committed';
   IF d.policy_snapshot ? 'settlement' THEN
     IF v_existing IS NOT NULL AND v_existing IS DISTINCT FROM d.policy_snapshot->'settlement'
     THEN RAISE EXCEPTION 'action_result_settlement_conflict'; END IF;
     v_existing:=d.policy_snapshot->'settlement';
   END IF;
 END LOOP;
 IF v_committed AND v_effect='requeue' THEN v_effect:='pause'; END IF;
 IF v_existing IS NOT NULL THEN
   IF v_existing->'detailIds' IS DISTINCT FROM to_jsonb(v_ids)
   THEN RAISE EXCEPTION 'action_result_settlement_conflict'; END IF;
   v_settlement:=v_existing; v_count:=(v_existing->>'badTargetCount')::integer;
 ELSE
   IF v_bad='increment' THEN
     INSERT INTO public.auto_campaign_error_state(campaign_id,count_consecutive_bad_targets,last_input_data_id,last_reason,last_bad_target_at,updated_at)
     VALUES(p_campaign_id,1,p_input_data_id,left(p_reason,2000),now(),now())
     ON CONFLICT(campaign_id) DO UPDATE SET count_consecutive_bad_targets=CASE WHEN v_reset_before THEN 1 ELSE auto_campaign_error_state.count_consecutive_bad_targets+1 END,
       last_input_data_id=EXCLUDED.last_input_data_id,last_reason=EXCLUDED.last_reason,last_bad_target_at=now(),updated_at=now()
     RETURNING count_consecutive_bad_targets INTO v_count;
   ELSIF v_bad='reset' OR v_reset_before THEN
     INSERT INTO public.auto_campaign_error_state(campaign_id,count_consecutive_bad_targets,last_reason,updated_at)
     VALUES(p_campaign_id,0,NULL,now()) ON CONFLICT(campaign_id) DO UPDATE
       SET count_consecutive_bad_targets=0,last_reason=NULL,updated_at=now() RETURNING count_consecutive_bad_targets INTO v_count;
   ELSE
     SELECT count_consecutive_bad_targets INTO v_count FROM public.auto_campaign_error_state WHERE campaign_id=p_campaign_id;
     v_count:=COALESCE(v_count,0);
   END IF;
   v_settlement:=jsonb_build_object('detailIds',v_ids,'badTargetEffect',v_bad,'badTargetResetBefore',v_reset_before,'badTargetCount',v_count,'inputEffect',v_effect,'inputApplied',false);
 END IF;
 IF p_input_patch IS NOT NULL AND p_input_data_id IS NOT NULL AND NOT COALESCE((p_input_patch->>'deferInput')::boolean,false) AND NOT (v_settlement->>'inputApplied')::boolean THEN
   v_status:=CASE v_effect WHEN 'complete' THEN 'hoàn thành' WHEN 'pause' THEN 'tạm dừng' WHEN 'requeue' THEN 'chờ xử lý' ELSE i.status END;
   -- Existing cancellation/account/opt-out guards may strengthen, never weaken,
   -- the configured decision. A completed/unknown operation cannot be requeued.
   IF p_input_patch->>'status'='tạm dừng' THEN v_status:='tạm dừng'; END IF;
   IF p_input_patch->>'status'='chờ xử lý' AND v_effect<>'pause' THEN v_status:=CASE WHEN v_committed THEN 'tạm dừng' ELSE 'chờ xử lý' END; END IF;
   IF i.status='tạm dừng' THEN v_status:='tạm dừng'; END IF;
   UPDATE public.auto_campaign_input_data SET status=v_status,
     note=CASE WHEN p_input_patch ? 'note' THEN p_input_patch->>'note' ELSE note END,
     date_action=CASE WHEN v_status='hoàn thành' THEN now() ELSE date_action END
   WHERE id=p_input_data_id RETURNING * INTO i;
   v_settlement:=v_settlement || jsonb_build_object('inputApplied',true,'inputStatus',v_status);
 END IF;
 UPDATE public.auto_campaign_details SET policy_snapshot=jsonb_set(policy_snapshot,'{settlement}',v_settlement) WHERE id=ANY(v_ids);
 RETURN jsonb_build_object('settlement',v_settlement,'input',CASE WHEN p_input_data_id IS NULL THEN NULL ELSE to_jsonb(i) END);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_settle_campaign_run_unit_v2(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_unit_token uuid, p_requeue_unstarted boolean)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date, requeued_count integer)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_organization_id bigint;
  v_campaign_found boolean := false;
  v_campaign_status text;
  v_account_status text;
  v_account_platform text;
  v_account_is_zalo_web boolean;
  v_account_is_zalo_server boolean;
  v_runtime_owner_matches boolean;
  v_stored_unit_token uuid;
  v_stored_unit_vietnam_date date;
  v_stored_unit_claimed_at timestamptz;
  v_stored_unit_input_data_ids bigint[];
  v_optimistic_input_data_ids bigint[];
  v_now timestamptz := clock_timestamp();
  v_vietnam_date date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  v_requeued_count integer := 0;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF p_runtime_unit_token IS NULL THEN
    RAISE EXCEPTION 'runtime unit token is required';
  END IF;
  IF p_requeue_unstarted IS NULL THEN
    RAISE EXCEPTION 'requeue-unstarted decision is required';
  END IF;

  -- Settlement is cleanup: an inactive staff/capability must not strand an
  -- exact token, but the staff/organization/account scope remains mandatory.
  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Read the immutable payload after the advisory lock, lock only those rows,
  -- then lock/recheck the campaign. This preserves the canonical input-first
  -- order used by control and run-unit claims.
  SELECT campaign.runtime_unit_input_data_ids
  INTO v_optimistic_input_data_ids
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    );

  IF cardinality(COALESCE(v_optimistic_input_data_ids, ARRAY[]::bigint[])) > 0 THEN
    PERFORM input_data.id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.id = ANY(v_optimistic_input_data_ids)
      AND input_data.campaign_id = p_campaign_id
    ORDER BY input_data.id
    FOR UPDATE OF input_data;
  END IF;

  SELECT
    campaign.status,
    account.status,
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_show_web, false),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_unit_token,
    campaign.runtime_unit_vietnam_date,
    campaign.runtime_unit_claimed_at,
    campaign.runtime_unit_input_data_ids
  INTO
    v_campaign_status,
    v_account_status,
    v_account_platform,
    v_account_is_zalo_web,
    v_account_is_zalo_server,
    v_stored_unit_token,
    v_stored_unit_vietnam_date,
    v_stored_unit_claimed_at,
    v_stored_unit_input_data_ids
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;
  v_campaign_found := FOUND;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
  IF NOT v_campaign_found THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  v_runtime_owner_matches := NOT (
    (v_runtime_target = 'server' AND (
      v_account_platform <> 'zalo'
      OR v_account_is_zalo_web
      OR NOT v_account_is_zalo_server
    ))
    OR (v_runtime_target = 'desktop' AND (
      v_account_platform = 'zalo' AND v_account_is_zalo_server
    ))
  );

  IF v_stored_unit_token IS NULL THEN
    IF NOT v_runtime_owner_matches THEN
      RETURN QUERY SELECT
        false, 'runtime_not_owner', v_campaign_status, v_account_status,
        v_now, v_vietnam_date, 0;
    ELSIF v_stored_unit_vietnam_date IS NOT NULL
      OR v_stored_unit_claimed_at IS NOT NULL
      OR v_stored_unit_input_data_ids IS NOT NULL
    THEN
      RETURN QUERY SELECT
        false, 'unit_lease_corrupt', v_campaign_status, v_account_status,
        v_now, v_vietnam_date, 0;
    ELSE
      -- Idempotent terminal result for a settlement response lost after the
      -- lease was cleared. There is no active token this caller can mutate.
      RETURN QUERY SELECT
        true, 'already_settled', v_campaign_status, v_account_status,
        v_now, v_vietnam_date, 0;
    END IF;
    RETURN;
  END IF;

  IF v_stored_unit_token IS DISTINCT FROM p_runtime_unit_token THEN
    RETURN QUERY SELECT
      false, 'unit_lease_mismatch', v_campaign_status, v_account_status,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;
  -- The exact opaque token remains authorized to clean up after mutable
  -- account subtype/capability/control changes; no other token can cross it.
  IF v_stored_unit_vietnam_date IS NULL
    OR v_stored_unit_claimed_at IS NULL
    OR v_stored_unit_input_data_ids IS NULL
  THEN
    RETURN QUERY SELECT
      false, 'unit_lease_corrupt', v_campaign_status, v_account_status,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  IF v_account_platform='facebook' THEN PERFORM private.facebook_random_unit_settled(p_campaign_id,p_account_id,p_runtime_unit_token,p_requeue_unstarted); END IF;

  -- Win the token CAS before mutating even the stored input set. Both changes
  -- remain one transaction, so callers can never observe a cleared lease with
  -- only a partial requeue.
  UPDATE public.auto_campaigns AS campaign
  SET runtime_unit_token = NULL,
    runtime_unit_vietnam_date = NULL,
    runtime_unit_claimed_at = NULL,
    runtime_unit_input_data_ids = NULL,
    updated_at = v_now
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.runtime_unit_token = p_runtime_unit_token;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false, 'unit_lease_mismatch', v_campaign_status, v_account_status,
      v_now, v_vietnam_date, 0;
    RETURN;
  END IF;

  IF p_requeue_unstarted
    AND cardinality(v_stored_unit_input_data_ids) > 0
  THEN
    UPDATE public.auto_campaign_input_data AS input_data
    SET status = 'chờ xử lý', date_action = NULL
    WHERE input_data.id = ANY(v_stored_unit_input_data_ids)
      AND input_data.campaign_id = p_campaign_id
      AND input_data.status = 'đang chạy';
    GET DIAGNOSTICS v_requeued_count = ROW_COUNT;
  END IF;

  RETURN QUERY SELECT
    true,
    CASE WHEN p_requeue_unstarted
      THEN 'requeued_unstarted'
      ELSE 'settled'
    END,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date,
    v_requeued_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_staff_access(p_staff_id bigint, p_username text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE; o public.org_organization%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE id=p_staff_id AND username=p_username AND password=p_password;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_auth_invalid'; END IF;
  SELECT * INTO STRICT o FROM public.org_organization WHERE id=s.organization_id;
  RETURN jsonb_build_object('isAdmin',s.is_admin IS TRUE AND s.is_active AND s.deleted_at IS NULL,
    'isActive',s.is_active AND s.deleted_at IS NULL,'timeAllowed',public.aka_agent_staff_time_allowed(s.id),
    'expirationDate',s.expiration_date,'useStaffExpiration',o.use_staff_expiration,'useOrganizationExpiration',NOT o.use_staff_expiration);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_staff_client(p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '12s'
AS $function$
DECLARE
  s public.org_staff%ROWTYPE;
  allowed text[];
  stamp timestamptz := clock_timestamp();
  integration jsonb;
  kind text;
  device_result jsonb;
  lock_key bigint;
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('read','bind_device','accept_policy','change_password','set_test_workflow','save_integration','register_recovery','prepare_device_v3','bind_device_v3')
    OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
  allowed := CASE p_action
    WHEN 'prepare_device_v3' THEN ARRAY['staffId','fingerprintHash','legacyHash','source']
    WHEN 'bind_device_v3' THEN ARRAY['staffId','fingerprintHash','legacyHash','source','requestId','expected']
    WHEN 'bind_device' THEN ARRAY['staffId','fingerprintHash']
    WHEN 'change_password' THEN ARRAY['staffId','newPassword']
    WHEN 'set_test_workflow' THEN ARRAY['staffId','enabled']
    WHEN 'save_integration' THEN ARRAY['staffId','kind','integration']
    WHEN 'register_recovery' THEN ARRAY['staffId','fingerprintHash','secretHash']
    ELSE ARRAY['staffId'] END;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_data) k WHERE NOT k=ANY(allowed))
    OR (p_data ? 'staffId' AND (jsonb_typeof(p_data->'staffId') IS DISTINCT FROM 'number' OR p_data->>'staffId' !~ '^[1-9][0-9]*$'))
    OR (p_action NOT IN ('read','prepare_device_v3') AND NOT p_data ? 'staffId') THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
  IF coalesce(btrim(p_username),'')='' OR coalesce(p_password,'')='' THEN RAISE EXCEPTION 'staff_client_auth_invalid'; END IF;

  -- Authenticate before taking a lock, then repeat under that lock. Neither an
  -- ID nor a fingerprint is a credential; no caller selects another staff.
  SELECT * INTO s FROM public.org_staff WHERE username=btrim(p_username) AND password=p_password;
  IF NOT FOUND OR (p_data ? 'staffId' AND s.id IS DISTINCT FROM (p_data->>'staffId')::bigint) THEN RAISE EXCEPTION 'staff_client_auth_invalid'; END IF;
  -- All fingerprint locks precede staff locks, including proof recovery and old API enrollment.
  IF p_action IN ('prepare_device_v3','bind_device_v3','bind_device','register_recovery') THEN
    IF jsonb_typeof(p_data->'fingerprintHash') IS DISTINCT FROM 'string'
      OR p_data->>'fingerprintHash' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
    FOR lock_key IN SELECT DISTINCT hashtextextended(k,73103) FROM unnest(ARRAY[
      s.aka_agent_device_identity_version::text||':'||s.aka_agent_device_fingerprint_hash,
      (CASE WHEN p_action IN ('prepare_device_v3','bind_device_v3') THEN '3' ELSE s.aka_agent_device_identity_version::text END)||':'||(p_data->>'fingerprintHash')
    ]) k WHERE k IS NOT NULL ORDER BY 1 LOOP
      PERFORM pg_advisory_xact_lock(lock_key);
    END LOOP;
  END IF;
  IF p_action='read' THEN
    SELECT * INTO s FROM public.org_staff WHERE id=s.id AND username=btrim(p_username) AND password=p_password FOR SHARE;
  ELSE
    SELECT * INTO s FROM public.org_staff WHERE id=s.id AND username=btrim(p_username) AND password=p_password FOR UPDATE;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'staff_client_auth_invalid'; END IF;
  IF NOT s.is_active OR s.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'staff_client_inactive'; END IF;

  IF p_action IN ('bind_device','accept_policy','register_recovery','prepare_device_v3','bind_device_v3') AND NOT public.aka_agent_staff_time_allowed(s.id) THEN
    RAISE EXCEPTION 'staff_client_expired';
  END IF;
  IF p_action IN ('prepare_device_v3','bind_device_v3') THEN
    device_result := private.aka_agent_device_v3(s.id,p_action,p_data);
    SELECT * INTO s FROM public.org_staff WHERE id=s.id;
  ELSIF p_action='register_recovery' THEN
    IF jsonb_typeof(p_data->'fingerprintHash') IS DISTINCT FROM 'string'
      OR jsonb_typeof(p_data->'secretHash') IS DISTINCT FROM 'string'
      OR p_data->>'fingerprintHash' !~ '^[a-f0-9]{64}$' OR p_data->>'secretHash' !~ '^[a-f0-9]{64}$'
      OR s.aka_agent_device_fingerprint_hash IS DISTINCT FROM p_data->>'fingerprintHash' THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
    IF private.aka_agent_device_ambiguous(s.aka_agent_device_identity_version,s.aka_agent_device_fingerprint_hash,s.id,false) THEN
      DELETE FROM private.aka_agent_staff_recovery WHERE staff_id=s.id;
    ELSE
    INSERT INTO private.aka_agent_staff_recovery AS r (staff_id,organization_id,fingerprint_hash,secret_hash,credential_hash)
      VALUES(s.id,s.organization_id,p_data->>'fingerprintHash',p_data->>'secretHash',encode(extensions.digest(s.password,'sha256'),'hex'))
      ON CONFLICT (staff_id) DO UPDATE SET organization_id=excluded.organization_id,fingerprint_hash=excluded.fingerprint_hash,
        secret_hash=excluded.secret_hash,credential_hash=excluded.credential_hash,created_at=clock_timestamp();
  END IF;
  ELSIF p_action='bind_device' THEN
    IF s.aka_agent_device_identity_version=3 THEN RAISE EXCEPTION 'staff_client_device_locked'; END IF;
    IF jsonb_typeof(p_data->'fingerprintHash') IS DISTINCT FROM 'string'
      OR p_data->>'fingerprintHash' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
    IF s.aka_agent_device_fingerprint_hash IS NOT NULL
      AND s.aka_agent_device_fingerprint_hash IS DISTINCT FROM p_data->>'fingerprintHash' THEN
      RAISE EXCEPTION 'staff_client_device_locked';
    END IF;
    IF s.aka_agent_device_fingerprint_hash IS NULL THEN
      UPDATE public.org_staff SET aka_agent_device_fingerprint_hash=p_data->>'fingerprintHash' WHERE id=s.id RETURNING * INTO s;
    END IF;
    PERFORM private.aka_agent_device_ambiguous(2::smallint,s.aka_agent_device_fingerprint_hash,s.id,false);
  ELSIF p_action='accept_policy' THEN
    IF NOT s.is_policy_accepted THEN
      UPDATE public.org_staff SET is_policy_accepted=true,policy_accepted_at=stamp,updated_at=stamp WHERE id=s.id RETURNING * INTO s;
    END IF;
  ELSIF p_action='change_password' THEN
    IF jsonb_typeof(p_data->'newPassword') IS DISTINCT FROM 'string'
      OR length(p_data->>'newPassword') NOT BETWEEN 1 AND 1024 THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
    UPDATE public.org_staff SET password=p_data->>'newPassword',updated_at=stamp WHERE id=s.id RETURNING * INTO s;
    DELETE FROM private.aka_agent_staff_recovery WHERE staff_id=s.id;
  ELSIF p_action='set_test_workflow' THEN
    IF NOT s.is_admin_akabiz THEN RAISE EXCEPTION 'staff_client_forbidden'; END IF;
    IF jsonb_typeof(p_data->'enabled') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
    UPDATE public.org_staff SET use_test_workflow=(p_data->>'enabled')::boolean,updated_at=stamp WHERE id=s.id RETURNING * INTO s;
  ELSIF p_action='save_integration' THEN
    kind:=p_data->>'kind'; integration:=p_data->'integration';
    IF kind IS NULL OR kind NOT IN ('sms','zaloWeb','akaBizDesktop') OR jsonb_typeof(integration) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'staff_client_invalid_input';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(integration) k WHERE NOT k=ANY(ARRAY['id','staffId','username','name','installPath','dbPath']))
      OR jsonb_typeof(integration->'staffId') IS DISTINCT FROM 'number' OR integration->>'staffId' !~ '^[1-9][0-9]*$'
      OR jsonb_typeof(integration->'username') IS DISTINCT FROM 'string' OR length(btrim(integration->>'username')) NOT BETWEEN 1 AND 255
      OR EXISTS (SELECT 1 FROM jsonb_each(integration) e WHERE e.key IN ('name','installPath','dbPath') AND
        (jsonb_typeof(e.value) NOT IN ('null','string') OR length(e.value#>>'{}')>4096)) THEN RAISE EXCEPTION 'staff_client_invalid_input'; END IF;
    integration:=jsonb_build_object('id',(integration->>'staffId')::bigint,'staffId',(integration->>'staffId')::bigint,
      'username',btrim(integration->>'username'),'name',integration->'name','installPath',integration->'installPath','dbPath',integration->'dbPath','integratedAt',stamp);
    UPDATE public.org_staff SET akabiz_integrations=jsonb_set(coalesce(akabiz_integrations,'{}'),ARRAY[kind],integration,true),updated_at=stamp
      WHERE id=s.id RETURNING * INTO s;
  END IF;

  -- Explicit projection: never return password, CRM permissions, tokens, or
  -- future columns added to org_staff. Mutations never accept tenant/admin data.
  RETURN jsonb_build_object('id',s.id,'organization_id',s.organization_id,'name',s.name,'phone',s.phone,'username',s.username,
    'is_active',s.is_active,'is_admin',s.is_admin,'is_admin_akabiz',s.is_admin_akabiz,'use_test_workflow',s.use_test_workflow,
    'is_policy_accepted',s.is_policy_accepted,'policy_accepted_at',s.policy_accepted_at,
    'aka_agent_device_fingerprint_hash',s.aka_agent_device_fingerprint_hash,
    'aka_agent_device_identity_version',s.aka_agent_device_identity_version,'deviceV3',device_result,
    'device_label',s.device_label,'device_platform',s.device_platform,'device_bound_at',s.device_bound_at,'device_last_seen_at',s.device_last_seen_at,
    'app_notification',s.app_notification,'akabiz_integrations',s.akabiz_integrations,'updated_at',s.updated_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_staff_management(p_actor_id bigint, p_username text, p_password text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '12s'
AS $function$
#variable_conflict use_variable
DECLARE
  actor public.org_staff%ROWTYPE; org public.org_organization%ROWTYPE;
  target public.org_staff%ROWTYPE; grp public.org_group%ROWTYPE;
  request public.auto_staff_management_requests%ROWTYPE;
  result jsonb; obj jsonb; ids bigint[]; id bigint; parent_id bigint; group_id bigint;
  request_id uuid; revision text; phone text; label text; allowed text[];
  root_id bigint; root_count integer;
  mutation boolean; total bigint; offset_rows integer; group_ids bigint[]; stamp timestamptz:=clock_timestamp();
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('list','saveGroup','saveStaff','setStatus','revealPassword','prepareDevices','resetDevices') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
  allowed:=CASE p_action
    WHEN 'list' THEN ARRAY['search','groupId','status','page']
    WHEN 'saveGroup' THEN ARRAY['id','name','parentId','expectedVersion','requestId']
    WHEN 'saveStaff' THEN ARRAY['id','name','phone','groupId','isDepartmentManager','expectedVersion','requestId']
    WHEN 'setStatus' THEN ARRAY['targets','isActive','requestId']
    WHEN 'revealPassword' THEN ARRAY['id']
    WHEN 'prepareDevices' THEN ARRAY['ids']
    ELSE ARRAY['targets','requestId'] END;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_data) k WHERE NOT k=ANY(allowed)) THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
  SELECT s.* INTO actor FROM public.org_staff s WHERE s.id=p_actor_id AND s.username=p_username AND s.password=p_password;
  IF NOT FOUND OR actor.is_admin IS NOT TRUE OR NOT public.aka_agent_staff_time_allowed(actor.id) THEN RAISE EXCEPTION 'staff_access_denied'; END IF;
  mutation:=p_action IN ('saveGroup','saveStaff','setStatus','resetDevices');
  IF mutation THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('aka-agent-staff-management:'||actor.organization_id::text,0));
    IF p_action IN ('saveGroup','saveStaff') THEN
      -- Share Chat's organization lock before actor/group/staff rows, including manager replacement.
      PERFORM pg_advisory_xact_lock(hashtextextended('aka-agent-chat:workspace-staff:'||actor.organization_id::text,0));
    END IF;
  END IF;
  -- Revalidate after waiting. Keep the authorizing row locked through commit.
  SELECT s.* INTO actor FROM public.org_staff s WHERE s.id=p_actor_id AND s.username=p_username AND s.password=p_password FOR SHARE;
  IF NOT FOUND OR actor.is_admin IS NOT TRUE OR NOT public.aka_agent_staff_time_allowed(actor.id) THEN RAISE EXCEPTION 'staff_access_denied'; END IF;
  SELECT o.* INTO STRICT org FROM public.org_organization o WHERE o.id=actor.organization_id FOR SHARE;
  IF mutation THEN
    request_id:=(p_data->>'requestId')::uuid;
    IF request_id IS NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    SELECT * INTO request FROM public.auto_staff_management_requests WHERE auto_staff_management_requests.request_id=request_id;
    IF FOUND THEN
      IF request.actor_id<>actor.id OR request.organization_id<>org.id OR request.action<>p_action OR request.payload IS DISTINCT FROM p_data THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      RETURN request.result;
    END IF;
  END IF;

  IF p_action='list' THEN
    IF length(coalesce(p_data->>'search',''))>200 OR coalesce(p_data->>'status','all') NOT IN ('all','active','locked','expired') THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    offset_rows:=greatest(0,coalesce((p_data->>'page')::integer,0))*100;
    group_id:=(p_data->>'groupId')::bigint;
    IF group_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.org_group WHERE org_group.id=group_id AND organization_id=org.id) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
      WITH RECURSIVE tree AS (SELECT g.id FROM public.org_group g WHERE g.id=group_id AND g.organization_id=org.id
        UNION SELECT g.id FROM public.org_group g JOIN tree t ON g.parent_id=t.id WHERE g.organization_id=org.id)
      SELECT array_agg(t.id) INTO group_ids FROM tree t;
    END IF;
    WITH rows AS MATERIALIZED (SELECT public.aka_agent_staff_management_row(s.id) row FROM public.org_staff s
      WHERE s.organization_id=org.id AND s.deleted_at IS NULL
      AND (coalesce(p_data->>'search','')='' OR strpos(lower(s.name||' '||s.phone||' '||s.username),lower(p_data->>'search'))>0)
      AND (group_id IS NULL OR EXISTS (SELECT 1 FROM public.org_group_staff gs WHERE gs.staff_id=s.id AND gs.organization_id=org.id AND gs.group_id=ANY(group_ids)))),
    filtered AS (SELECT row FROM rows WHERE coalesce(p_data->>'status','all')='all' OR row->>'status'=p_data->>'status'),
    page AS (SELECT row FROM filtered ORDER BY (row->>'id')::bigint OFFSET offset_rows LIMIT 100)
    SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(row ORDER BY (row->>'id')::bigint) FROM page),'[]'::jsonb),
      'total',(SELECT count(*) FROM filtered),'page',offset_rows/100) INTO result;
    SELECT count(*) INTO total FROM public.org_staff s WHERE s.organization_id=org.id AND s.deleted_at IS NULL;
    result:=result||jsonb_build_object('organization',jsonb_build_object('id',org.id,'name',org.name,'maxStaff',org.max_staff,
      'staffCount',total,'staffDurationDays',coalesce(org.staff_duration_days,365),'useStaffExpiration',org.use_staff_expiration,'useOrganizationExpiration',NOT org.use_staff_expiration,
      'expirationDate',(SELECT max(p.expiration_date) FROM public.org_organization_product p WHERE p.organization_id=org.id AND NOT p.is_deleted AND p.product_id IN (3,10,13,16,17,18)),
      'today',timezone('Asia/Ho_Chi_Minh',stamp)::date),
      'groups',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'parentId',g.parent_id,'version',g.xmin::text,
        'managers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'name',m.name) ORDER BY m.id)
          FROM public.org_staff m WHERE m.organization_id=org.id AND m.deleted_at IS NULL
          AND EXISTS(SELECT 1 FROM public.org_group_staff gm WHERE gm.group_id=g.id AND gm.organization_id=org.id AND gm.staff_id=m.id AND gm.is_admin IS TRUE)),'[]'::jsonb),
        'staffCount',(SELECT count(DISTINCT gs.staff_id) FROM public.org_group_staff gs JOIN public.org_staff s ON s.id=gs.staff_id
          WHERE gs.group_id=g.id AND gs.organization_id=org.id AND s.organization_id=org.id AND s.deleted_at IS NULL)) ORDER BY g.id)
        FROM public.org_group g WHERE g.organization_id=org.id),'[]'::jsonb));

  ELSIF p_action='saveGroup' THEN
    id:=(p_data->>'id')::bigint; parent_id:=(p_data->>'parentId')::bigint; label:=btrim(p_data->>'name');
    IF label IS NULL OR length(label) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    SELECT count(*),min(g.id) INTO root_count,root_id FROM public.org_group g WHERE g.organization_id=org.id AND g.parent_id IS NULL;
    IF root_count>1 THEN RAISE EXCEPTION 'staff_group_multiple_roots'; END IF;
    IF root_id IS NULL THEN
      INSERT INTO public.org_group(organization_id,name,parent_id) VALUES(org.id,org.name,NULL) RETURNING org_group.id INTO root_id;
    END IF;
    -- NULL is the legacy Desktop value for 'directly under the organization'.
    parent_id:=coalesce(parent_id,root_id);
    IF parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.org_group g WHERE g.id=parent_id AND g.organization_id=org.id) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    IF id IS NOT NULL THEN
      SELECT * INTO grp FROM public.org_group g WHERE g.id=id AND g.organization_id=org.id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'staff_not_found'; END IF;
      IF grp.parent_id IS NULL THEN RAISE EXCEPTION 'staff_group_root_read_only'; END IF;
      SELECT g.xmin::text INTO revision FROM public.org_group g WHERE g.id=id;
      IF revision IS DISTINCT FROM p_data->>'expectedVersion' THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      IF parent_id IS NOT NULL AND EXISTS (WITH RECURSIVE descendants AS (
        SELECT g.id FROM public.org_group g WHERE g.id=id AND g.organization_id=org.id
        UNION SELECT g.id FROM public.org_group g JOIN descendants d ON g.parent_id=d.id WHERE g.organization_id=org.id)
        SELECT 1 FROM descendants d WHERE d.id=parent_id) THEN RAISE EXCEPTION 'staff_group_cycle'; END IF;
      UPDATE public.org_group g SET name=label,parent_id=save_parent.parent_id,updated_at=stamp
        FROM (SELECT parent_id) save_parent WHERE g.id=id;
    ELSE
      INSERT INTO public.org_group(organization_id,name,parent_id) VALUES(org.id,label,parent_id) RETURNING org_group.id INTO id;
    END IF;
    result:=jsonb_build_object('id',id);

  ELSIF p_action='saveStaff' THEN
    id:=(p_data->>'id')::bigint;group_id:=(p_data->>'groupId')::bigint;label:=btrim(p_data->>'name');phone:=public.normalize_phone(p_data->>'phone');
    IF label IS NULL OR length(label) NOT BETWEEN 1 AND 200 OR phone IS NULL OR phone !~ '^0[0-9]{9,10}$' OR group_id IS NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    IF p_data ? 'isDepartmentManager' AND jsonb_typeof(p_data->'isDepartmentManager') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.org_group g WHERE g.id=group_id AND g.organization_id=org.id) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    IF EXISTS(SELECT 1 FROM public.org_staff s WHERE s.organization_id=org.id AND public.normalize_phone(s.phone)=phone AND (id IS NULL OR s.id<>id)) THEN RAISE EXCEPTION 'staff_phone_exists'; END IF;
    IF id IS NULL THEN
      SELECT count(*) INTO total FROM public.org_staff s WHERE s.organization_id=org.id AND s.deleted_at IS NULL;
      IF total>=org.max_staff THEN RAISE EXCEPTION 'staff_quota_full'; END IF;
      INSERT INTO public.org_staff(organization_id,name,phone,username,password,is_active,is_admin,created_at,updated_at,expiration_date)
      VALUES(org.id,label,phone,org.id::text||'.'||phone,'123456',true,false,stamp,stamp,
        (timezone('Asia/Ho_Chi_Minh',stamp)::date+coalesce(org.staff_duration_days,365)+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')
      RETURNING org_staff.id INTO id;
    ELSE
      SELECT * INTO target FROM public.org_staff s WHERE s.id=id AND s.organization_id=org.id AND s.deleted_at IS NULL FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'staff_not_found'; END IF;
      IF public.aka_agent_staff_management_row(id)->>'version' IS DISTINCT FROM p_data->>'expectedVersion' THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      UPDATE public.org_staff s SET name=label,phone=save_phone.phone,updated_at=stamp FROM (SELECT phone) save_phone WHERE s.id=id;
    END IF;
    DELETE FROM public.org_group_staff gs WHERE gs.staff_id=id AND gs.organization_id=org.id AND gs.group_id<>group_id;
    IF NOT EXISTS(SELECT 1 FROM public.org_group_staff gs WHERE gs.staff_id=id AND gs.organization_id=org.id AND gs.group_id=group_id) THEN
      INSERT INTO public.org_group_staff(organization_id,staff_id,group_id,is_admin) VALUES(org.id,id,group_id,false);
    END IF;
    -- Optional for legacy clients: omission keeps the previous membership behavior.
    -- Explicit true replaces every current manager of the chosen department, as Chat does.
    IF p_data ? 'isDepartmentManager' THEN
      IF (p_data->>'isDepartmentManager')::boolean THEN
        UPDATE public.org_group_staff gs SET is_admin=false
          WHERE gs.organization_id=org.id AND gs.group_id=group_id AND gs.staff_id<>id AND gs.is_admin IS TRUE;
      END IF;
      UPDATE public.org_group_staff gs SET is_admin=(p_data->>'isDepartmentManager')::boolean
        WHERE gs.organization_id=org.id AND gs.group_id=group_id AND gs.staff_id=id
          AND gs.is_admin IS DISTINCT FROM (p_data->>'isDepartmentManager')::boolean;
    END IF;
    result:=public.aka_agent_staff_management_row(id);

  ELSIF p_action='revealPassword' THEN
    SELECT s.password INTO revision FROM public.org_staff s WHERE s.id=(p_data->>'id')::bigint AND s.organization_id=org.id AND s.deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    result:=jsonb_build_object('password',revision);

  ELSE
    IF p_action='prepareDevices' THEN
      IF jsonb_typeof(p_data->'ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
      SELECT array_agg(DISTINCT value::bigint ORDER BY value::bigint) INTO ids FROM jsonb_array_elements_text(p_data->'ids');
    ELSE
      IF jsonb_typeof(p_data->'targets') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
      SELECT array_agg(DISTINCT (value->>'id')::bigint ORDER BY (value->>'id')::bigint) INTO ids FROM jsonb_array_elements(p_data->'targets');
    END IF;
    IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 100 OR array_position(ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
    IF p_action='prepareDevices' THEN
      PERFORM s.id FROM public.org_staff s WHERE s.id=ANY(ids) AND s.organization_id=org.id ORDER BY s.id FOR SHARE;
    ELSE
      PERFORM s.id FROM public.org_staff s WHERE s.id=ANY(ids) AND s.organization_id=org.id ORDER BY s.id FOR UPDATE;
    END IF;
    IF (SELECT count(*) FROM public.org_staff s WHERE s.id=ANY(ids) AND s.organization_id=org.id AND s.deleted_at IS NULL)<>cardinality(ids) THEN RAISE EXCEPTION 'staff_not_found'; END IF;
    IF p_action='prepareDevices' THEN
      SELECT jsonb_build_object('items',jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'username',s.username,
        'version',s.xmin::text,'isBound',s.aka_agent_device_fingerprint_hash IS NOT NULL,
        'label',presence.device_label,'platform',presence.device_platform,'lastSeenAt',presence.last_seen_at) ORDER BY s.id)) INTO result
      FROM public.org_staff s LEFT JOIN LATERAL (SELECT p.device_label,p.device_platform,p.last_seen_at FROM public.auto_staff_device_presence p
        WHERE p.staff_id=s.id AND p.organization_id=org.id ORDER BY p.last_seen_at DESC LIMIT 1) presence ON true WHERE s.id=ANY(ids);
    ELSE
      IF jsonb_array_length(p_data->'targets')<>cardinality(ids) THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
      FOR obj IN SELECT value FROM jsonb_array_elements(p_data->'targets') LOOP
        IF jsonb_typeof(obj) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(obj) k WHERE k NOT IN ('id','expectedVersion')) THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
        IF (obj->>'id')::bigint IS NULL OR obj->>'expectedVersion' IS NULL THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
        IF p_action='setStatus' THEN revision:=public.aka_agent_staff_management_row((obj->>'id')::bigint)->>'version';
        ELSE SELECT s.xmin::text INTO revision FROM public.org_staff s WHERE s.id=(obj->>'id')::bigint; END IF;
        IF revision IS DISTINCT FROM obj->>'expectedVersion' THEN RAISE EXCEPTION 'staff_conflict'; END IF;
      END LOOP;
      IF p_action='setStatus' THEN
        IF jsonb_typeof(p_data->'isActive') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'staff_invalid_input'; END IF;
        IF NOT (p_data->>'isActive')::boolean AND (actor.id=ANY(ids) OR NOT EXISTS(SELECT 1 FROM public.org_staff s
          WHERE s.organization_id=org.id AND s.is_admin IS TRUE AND s.is_active AND s.deleted_at IS NULL AND NOT s.id=ANY(ids))) THEN RAISE EXCEPTION 'staff_admin_required'; END IF;
        UPDATE public.org_staff s SET is_active=(p_data->>'isActive')::boolean,updated_at=stamp WHERE s.id=ANY(ids);
      ELSE
        UPDATE public.org_staff s SET aka_agent_device_fingerprint_hash=NULL,updated_at=stamp
          WHERE s.id=ANY(ids) AND s.aka_agent_device_fingerprint_hash IS NOT NULL;
      END IF;
      result:=jsonb_build_object('count',cardinality(ids));
    END IF;
  END IF;
  IF mutation THEN
    INSERT INTO public.auto_staff_management_requests(request_id,actor_id,organization_id,action,payload,result)
      VALUES(request_id,actor.id,org.id,p_action,p_data,result);
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_stop_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_stop_campaign_data_group_source(
      p_staff_id, p_organization_id, p_campaign_id, p_request_id, p_reason
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_stop_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_locked_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_hash text;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_data_group_source_request';
  END IF;

  -- Discover immutable lock keys without retaining a row lock.  All state is
  -- revalidated after acquiring the common group -> campaign -> source locks.
  SELECT source.*
  INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = p_campaign_id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign_data_group_source_not_found';
  END IF;

  PERFORM contact_group.id
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = v_source.group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;

  PERFORM campaign.id
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
            )
          )
        )
      )
  FOR UPDATE OF campaign, account;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data_group_campaign_not_found';
  END IF;

  SELECT source.*
  INTO v_locked_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = v_source.id
    AND source.campaign_id = p_campaign_id
    AND source.group_id = v_source.group_id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign_data_group_source_changed';
  END IF;
  v_source := v_locked_source;

  v_hash := md5(jsonb_build_object(
    'operation', 'stop_source',
    'campaignId', p_campaign_id,
    'reason', COALESCE(
      NULLIF(btrim(COALESCE(p_reason, '')), ''), 'manual_stop'
    )
  )::text);

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status,
    staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'stop_source', v_source.group_id, v_hash,
    'processing', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT batch.*
    INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'stop_source'
      OR v_batch.request_hash <> v_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN
      RETURN v_batch.result;
    END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  UPDATE public.auto_campaign_data_group_sources
  SET status = 'stopped',
      stopped_at = COALESCE(stopped_at, now()),
      stop_reason = COALESCE(
        NULLIF(btrim(COALESCE(p_reason, '')), ''), 'manual_stop'
      ),
      updated_at = now()
  WHERE id = v_source.id
  RETURNING * INTO v_source;

  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
  WHERE id = v_batch.id;

  RETURN to_jsonb(v_source);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_take_campaign_content_index(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_claim_token uuid, p_runtime_unit_token uuid, p_input_data_id bigint, p_action_code text, p_variant_count integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_org bigint;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_input public.auto_campaign_input_data%ROWTYPE;
  v_raw text;
  v_index integer;
  v_first boolean;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0 OR p_runtime_target IS NULL
    OR p_runtime_target NOT IN ('desktop','server')
    OR p_runtime_claim_token IS NULL OR p_runtime_unit_token IS NULL
    OR p_action_code IS NULL OR btrim(p_action_code) = '' OR length(p_action_code) > 128
    OR p_variant_count IS NULL OR p_variant_count < 1
    OR (p_input_data_id IS NOT NULL AND p_input_data_id <= 0) THEN
    RAISE EXCEPTION 'campaign_content_invalid_arguments';
  END IF;

  SELECT organization_id INTO v_org FROM public.org_staff
  WHERE id=p_staff_id AND is_active IS TRUE FOR SHARE;
  IF v_org IS NULL THEN RAISE EXCEPTION 'campaign_content_not_owner'; END IF;

  -- Same lock order as unit claim: staff -> entitlement -> serialization -> input -> campaign/account.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
  IF p_input_data_id IS NOT NULL THEN
    SELECT * INTO v_input FROM public.auto_campaign_input_data
    WHERE id=p_input_data_id AND campaign_id=p_campaign_id
      AND NOT COALESCE(is_delete,false) AND status='đang chạy' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'campaign_content_input_not_owned'; END IF;
  END IF;

  SELECT c.* INTO v_campaign FROM public.auto_campaigns c
  JOIN public.auto_accounts a ON a.id=c.account_id AND a.staff_id=c.staff_id
  WHERE c.id=p_campaign_id AND c.account_id=p_account_id AND c.staff_id=p_staff_id
    AND (c.organization_id IS NULL OR c.organization_id=v_org)
    AND (a.organization_id IS NULL OR a.organization_id=v_org)
    AND NOT COALESCE(c.is_delete,false) AND NOT COALESCE(a.is_delete,false)
    AND a.is_active IS TRUE AND a.login_status='đã đăng nhập'
    -- Server pause drains the already-claimed unit before releasing ownership.
    AND (p_runtime_target='server' OR (c.status='đang chạy' AND a.status='đang chạy'))
    AND c.runtime_claim_token=p_runtime_claim_token AND c.runtime_claim_target=p_runtime_target
    AND c.runtime_unit_token=p_runtime_unit_token AND c.runtime_unit_claimed_at IS NOT NULL
  FOR UPDATE OF c,a;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_content_not_owner'; END IF;
  IF p_input_data_id IS NOT NULL AND NOT COALESCE(p_input_data_id=ANY(v_campaign.runtime_unit_input_data_ids),false) THEN
    RAISE EXCEPTION 'campaign_content_input_not_in_unit';
  END IF;
  IF p_variant_count=1 THEN RETURN 0; END IF;

  v_first := p_input_data_id IS NULL OR NOT (v_input.content_rotation_indexes ? p_action_code);
  IF v_first THEN
    v_raw := v_campaign.content_rotation_indexes->>p_action_code;
    IF v_raw IS NULL AND v_campaign.action_id IN ('facebook_timeline_post','facebook_page_post')
      AND p_action_code IN ('fb_post_my_profile','fb_post_page') THEN
      v_raw := v_campaign.extra_settings->>'contentRotationIndex';
    END IF;
  ELSE
    v_raw := v_input.content_rotation_indexes->>p_action_code;
  END IF;
  -- Modulo the current snapshot size; changing templates does not clear state.
  v_index := CASE WHEN v_raw ~ '^[0-9]{1,16}$'
    THEN mod(v_raw::numeric,p_variant_count)::integer ELSE 0 END;
  IF v_first THEN
    UPDATE public.auto_campaigns SET content_rotation_indexes=jsonb_set(
      content_rotation_indexes,ARRAY[p_action_code],to_jsonb((v_index+1)%p_variant_count),true)
    WHERE id=p_campaign_id;
  END IF;
  IF p_input_data_id IS NOT NULL THEN
    UPDATE public.auto_campaign_input_data SET content_rotation_indexes=jsonb_set(
      content_rotation_indexes,ARRAY[p_action_code],to_jsonb((v_index+1)%p_variant_count),true)
    WHERE id=p_input_data_id;
  END IF;
  RETURN v_index;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_write_action_result_v1(p_staff_id bigint, p_campaign_id bigint, p_account_id bigint, p_claim_token uuid, p_unit_token uuid, p_result_key text, p_detail jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
 c public.auto_campaigns%ROWTYPE;
 d public.auto_campaign_details%ROWTYPE;
 p public.auto_account_action_status_policies%ROWTYPE;
 v_input_id bigint := (p_detail->>'input_data_id')::bigint;
 decision jsonb := p_detail->'policy_snapshot';
BEGIN
 IF p_staff_id IS NULL OR p_campaign_id IS NULL OR p_account_id IS NULL
   OR p_claim_token IS NULL OR p_unit_token IS NULL OR NULLIF(p_result_key,'') IS NULL
   OR jsonb_typeof(p_detail) IS DISTINCT FROM 'object'
   OR jsonb_typeof(decision) IS DISTINCT FROM 'object'
   OR jsonb_typeof(decision->'countsTowardLimit') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(decision->'resetErrorStreak') IS DISTINCT FROM 'boolean'
   OR decision->>'reportGroup' IS NULL OR decision->>'reportGroup' NOT IN ('success','failure','skipped','pending')
   OR decision->>'badTargetEffect' IS NULL OR decision->>'badTargetEffect' NOT IN ('increment','reset','ignore')
   OR decision->>'inputEffect' IS NULL OR decision->>'inputEffect' NOT IN ('complete','pause','requeue','none')
   OR decision->>'operationState' IS NULL OR decision->>'operationState' NOT IN ('committed','not_committed','unknown')
   OR decision ? 'settlement'
 THEN RAISE EXCEPTION 'action_result_payload_invalid'; END IF;
 -- Result commit drains an already claimed operation. Do not reject its error
 -- detail because an error policy just disabled the account or staff access.
 PERFORM 1 FROM public.org_staff WHERE id=p_staff_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_scope_invalid'; END IF;
 PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);
 IF v_input_id IS NOT NULL THEN
   PERFORM 1 FROM public.auto_campaign_input_data WHERE id=v_input_id AND campaign_id=p_campaign_id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'action_result_input_invalid'; END IF;
 END IF;
 SELECT x.* INTO c FROM public.auto_campaigns x JOIN public.auto_accounts a ON a.id=p_account_id
   AND a.staff_id=x.staff_id AND a.organization_id IS NOT DISTINCT FROM x.organization_id
 WHERE x.id=p_campaign_id AND x.staff_id=p_staff_id
   AND p_account_id IN (x.account_id,x.secondary_account_id)
   AND x.runtime_claim_token=p_claim_token AND x.runtime_unit_token=p_unit_token
   AND x.runtime_unit_claimed_at IS NOT NULL FOR UPDATE OF x;
 IF NOT FOUND THEN RAISE EXCEPTION 'action_result_claim_invalid'; END IF;
 IF v_input_id IS NOT NULL AND NOT COALESCE(v_input_id=ANY(c.runtime_unit_input_data_ids),false)
 THEN RAISE EXCEPTION 'action_result_input_not_in_unit'; END IF;
 SELECT * INTO d FROM public.auto_campaign_details WHERE result_key=p_result_key;
 IF FOUND THEN
   IF d.campaign_id<>p_campaign_id OR d.account_id<>p_account_id
     OR d.input_data_id IS DISTINCT FROM v_input_id
     OR d.action_code IS DISTINCT FROM p_detail->>'action_code'
     OR d.status_id IS DISTINCT FROM (p_detail->>'status_id')::bigint
     OR d.policy_snapshot->>'unitKey' IS DISTINCT FROM md5(p_unit_token::text)
   THEN RAISE EXCEPTION 'action_result_key_conflict'; END IF;
   RETURN jsonb_build_object('detail',to_jsonb(d),'inserted',false);
 END IF;
 SELECT * INTO p FROM public.auto_account_action_status_policies
   WHERE id=(p_detail->>'action_status_policy_id')::bigint FOR SHARE;
 IF NOT FOUND OR p.status_id IS DISTINCT FROM (p_detail->>'status_id')::bigint
   OR (p.action_code IS NOT NULL AND p.action_code IS DISTINCT FROM p_detail->>'action_code')
 THEN RAISE EXCEPTION 'result_policy_identity_mismatch'; END IF;
 IF EXISTS (SELECT 1 FROM public.auto_campaign_details old
   WHERE old.campaign_id=p_campaign_id AND ((v_input_id IS NULL AND old.input_data_id IS NULL) OR old.input_data_id=v_input_id) AND old.policy_snapshot->>'unitKey'=md5(p_unit_token::text)
     AND old.policy_snapshot ? 'settlement')
 THEN RAISE EXCEPTION 'action_result_target_settled'; END IF;
 decision:=decision || jsonb_build_object('unitKey',md5(p_unit_token::text));
 -- Guard execution evidence even if a caller supplied an unsafe retry decision.
 IF decision->>'inputEffect'='requeue' AND decision->>'operationState'<>'not_committed'
 THEN decision:=jsonb_set(decision,'{inputEffect}','"pause"'); END IF;
 INSERT INTO public.auto_campaign_details(input_data_id,campaign_id,account_id,action_code,action_name,status,
   error_code,log,data,post_url,status_id,sub_status_id,action_status_policy_id,report_group,
   counts_toward_limit,policy_snapshot,result_key)
 VALUES(v_input_id,p_campaign_id,p_account_id,p_detail->>'action_code',p_detail->>'action_name',p_detail->>'status',
   NULLIF(p_detail->>'error_code',''),p_detail->>'log',p_detail->'data',p_detail->>'post_url',
   (p_detail->>'status_id')::bigint,(p_detail->>'sub_status_id')::bigint,p.id,decision->>'reportGroup',
   (decision->>'countsTowardLimit')::boolean,decision,p_result_key) RETURNING * INTO d;
 IF (decision->>'countsTowardLimit')::boolean THEN
   PERFORM public.increment_auto_account_action_count(p_account_id,d.action_code,1);
 END IF;
 IF (decision->>'resetErrorStreak')::boolean THEN
   UPDATE public.auto_account_error_state SET count_consecutive_errors=0,updated_at=now()
     WHERE account_id=p_account_id AND action_code=d.action_code;
 END IF;
 RETURN jsonb_build_object('detail',to_jsonb(d),'inserted',true);
END $function$

CREATE OR REPLACE FUNCTION public.aka_agent_yield_campaign_daily_boundary(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_runtime_claim_token uuid, p_claimed_vietnam_date date)
 RETURNS TABLE(ok boolean, reason text, campaign_status text, account_status text, db_now timestamp with time zone, vietnam_date_key date, claimed_vietnam_date_key date, effective_stop_time time without time zone, boundary_at timestamp with time zone, day_changed boolean, running_input_count bigint)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_now timestamptz;
  v_vietnam_date date;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_organization_id bigint;
  v_campaign_status text;
  v_account_status text;
  v_daily_stop_time time without time zone;
  v_campaign_is_delete boolean;
  v_account_is_delete boolean;
  v_account_platform text;
  v_account_is_zalo_web boolean;
  v_account_is_zalo_server boolean;
  v_stored_claim_token uuid;
  v_stored_claim_target text;
  v_stored_claim_vietnam_date date;
  v_stored_unit_token uuid;
  v_effective_stop_time time without time zone;
  v_boundary_at timestamptz;
  v_day_changed boolean;
  v_running_input_count bigint := 0;
  v_reason text;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'campaign, account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'runtime target must be desktop or server';
  END IF;
  IF p_runtime_claim_token IS NULL OR p_claimed_vietnam_date IS NULL THEN
    RAISE EXCEPTION 'runtime claim token and Vietnam date are required';
  END IF;

  -- Yield is cleanup. Do not require staff.is_active or a live entitlement:
  -- capability loss must not strand a campaign/account in running state.
  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;

  IF NOT FOUND OR v_organization_id IS NULL THEN
    v_now := clock_timestamp();
    v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;
    RETURN QUERY SELECT
      false, 'runtime_not_owner', NULL::text, NULL::text,
      v_now, v_vietnam_date, p_claimed_vietnam_date,
      NULL::time, NULL::timestamptz,
      v_vietnam_date > p_claimed_vietnam_date,
      0::bigint;
    RETURN;
  END IF;

  -- Use the same campaign-scoped serialization barrier as Server run-unit
  -- claims and Control pause/resume before touching input/campaign rows.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  -- Wait for any in-flight unit row to become stable, but never mutate it.
  -- The runtime calls this RPC only after its current target/batch has settled.
  PERFORM input_data.id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.campaign_id = p_campaign_id
    AND COALESCE(input_data.is_delete, false) = false
    AND input_data.status = 'đang chạy'
  ORDER BY input_data.id
  FOR UPDATE OF input_data;

  PERFORM campaign_input.id
  FROM public.auto_campaign_inputs AS campaign_input
  WHERE campaign_input.campaign_id = p_campaign_id
    AND COALESCE(campaign_input.is_delete, false) = false
    AND campaign_input.status = 'đang chạy'
  ORDER BY campaign_input.id
  FOR UPDATE OF campaign_input;

  SELECT
    campaign.status,
    account.status,
    campaign.daily_stop_time,
    COALESCE(campaign.is_delete, false),
    COALESCE(account.is_delete, false),
    lower(btrim(COALESCE(account.flatform_type, ''))),
    COALESCE(account.is_zalo_show_web, false),
    COALESCE(account.is_zalo_server, false),
    campaign.runtime_claim_token,
    campaign.runtime_claim_target,
    campaign.runtime_claim_vietnam_date,
    campaign.runtime_unit_token
  INTO
    v_campaign_status,
    v_account_status,
    v_daily_stop_time,
    v_campaign_is_delete,
    v_account_is_delete,
    v_account_platform,
    v_account_is_zalo_web,
    v_account_is_zalo_server,
    v_stored_claim_token,
    v_stored_claim_target,
    v_stored_claim_vietnam_date,
    v_stored_unit_token
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND (
      campaign.organization_id IS NULL
      OR campaign.organization_id = v_organization_id
    )
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF campaign, account;

  v_now := clock_timestamp();
  v_vietnam_date := timezone('Asia/Ho_Chi_Minh', v_now)::date;

  IF NOT FOUND THEN
    RETURN QUERY SELECT
      false, 'not_found', NULL::text, NULL::text,
      v_now, v_vietnam_date, p_claimed_vietnam_date,
      NULL::time, NULL::timestamptz,
      v_vietnam_date > p_claimed_vietnam_date,
      0::bigint;
    RETURN;
  END IF;

  v_effective_stop_time := LEAST(
    COALESCE(v_daily_stop_time, time '23:59:00'),
    time '23:59:00'
  );
  v_boundary_at := (
    p_claimed_vietnam_date + v_effective_stop_time
  ) AT TIME ZONE 'Asia/Ho_Chi_Minh';
  v_day_changed := v_vietnam_date > p_claimed_vietnam_date;

  SELECT
    (
      SELECT count(*)
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.campaign_id = p_campaign_id
        AND COALESCE(input_data.is_delete, false) = false
        AND input_data.status = 'đang chạy'
    ) + (
      SELECT count(*)
      FROM public.auto_campaign_inputs AS campaign_input
      WHERE campaign_input.campaign_id = p_campaign_id
        AND COALESCE(campaign_input.is_delete, false) = false
        AND campaign_input.status = 'đang chạy'
    )
  INTO v_running_input_count;

  IF v_stored_unit_token IS NOT NULL THEN
    -- A durable lease is the authoritative in-flight marker, including for an
    -- empty-ID aggregate unit and after DB-first control changed visible state.
    v_reason := 'unit_still_running';
  ELSIF (v_runtime_target = 'server' AND (
      v_account_platform <> 'zalo'
      OR v_account_is_zalo_web
      OR NOT v_account_is_zalo_server
    ))
    OR (v_runtime_target = 'desktop' AND (
      v_account_platform = 'zalo' AND v_account_is_zalo_server
    ))
  THEN
    v_reason := 'runtime_not_owner';
  ELSIF v_campaign_is_delete THEN
    v_reason := 'campaign_deleted';
  ELSIF v_account_is_delete THEN
    v_reason := 'account_deleted';
  ELSIF v_campaign_status IS DISTINCT FROM 'đang chạy'
    OR v_account_status IS DISTINCT FROM 'đang chạy'
  THEN
    -- A DB-first running -> paused transition preserves the parent tuple, but
    -- visible control still wins so the owning executor performs its normal
    -- account-release cleanup instead of yielding or starting new work.
    v_reason := 'runtime_control_paused';
  ELSIF v_stored_claim_token IS DISTINCT FROM p_runtime_claim_token
    OR v_stored_claim_target IS DISTINCT FROM v_runtime_target
    OR v_stored_claim_vietnam_date IS DISTINCT FROM p_claimed_vietnam_date
  THEN
    -- While control remains running, mismatch wins over a newer run's input
    -- count so the stale executor cannot loop on unit_still_running.
    v_reason := 'runtime_claim_mismatch';
  ELSIF v_running_input_count > 0 THEN
    v_reason := 'unit_still_running';
  ELSIF p_claimed_vietnam_date > v_vietnam_date THEN
    v_reason := 'invalid_claimed_vietnam_date';
  ELSIF v_day_changed THEN
    v_reason := 'vietnam_day_changed';
  ELSIF v_now >= v_boundary_at THEN
    v_reason := CASE
      WHEN v_daily_stop_time IS NULL THEN 'daily_drain_due'
      ELSE 'daily_stop_due'
    END;
  ELSE
    v_reason := 'boundary_not_due';
  END IF;

  IF v_reason IN (
    'vietnam_day_changed',
    'daily_drain_due',
    'daily_stop_due'
  ) THEN
    UPDATE public.auto_campaigns AS campaign
    SET
      status = 'chờ xử lý',
      runtime_claim_token = NULL,
      runtime_claim_target = NULL,
      runtime_claim_vietnam_date = NULL,
      runtime_claimed_at = NULL,
      updated_at = v_now
    WHERE campaign.id = p_campaign_id
      AND campaign.status = 'đang chạy'
      AND campaign.runtime_claim_token = p_runtime_claim_token
      AND campaign.runtime_claim_target = v_runtime_target
      AND campaign.runtime_claim_vietnam_date = p_claimed_vietnam_date
      AND campaign.runtime_unit_token IS NULL;

    IF FOUND THEN
      UPDATE public.auto_accounts AS account
      SET
        status = 'chờ xử lý',
        updated_at = v_now
      WHERE account.id = p_account_id
        AND account.staff_id = p_staff_id
        AND account.status = 'đang chạy';

      v_campaign_status := 'chờ xử lý';
      IF FOUND THEN
        v_account_status := 'chờ xử lý';
      END IF;
      v_reason := 'yielded_' || v_reason;
    ELSE
      -- Defensive CAS result; row locks make this unlikely, but never report a
      -- successful yield when a newer status won.
      v_reason := 'runtime_control_paused';
    END IF;
  END IF;

  RETURN QUERY SELECT
    v_reason IN (
      'yielded_vietnam_day_changed',
      'yielded_daily_drain_due',
      'yielded_daily_stop_due'
    ),
    v_reason,
    v_campaign_status,
    v_account_status,
    v_now,
    v_vietnam_date,
    p_claimed_vietnam_date,
    v_effective_stop_time,
    v_boundary_at,
    v_day_changed,
    v_running_input_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_zalo_phone_check_usage(p_staff_id bigint, p_organization_id bigint, p_account_id bigint, p_runtime_target text, p_claim_token uuid, p_consume boolean, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_capabilities record;
  v_today date;
  v_count integer := 0;
  v_limit integer := 600;
  v_setting text;
  v_allowed boolean;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0 OR p_consume IS NULL
    OR p_runtime_target IS NULL OR p_runtime_target NOT IN ('desktop','server') THEN
    RAISE EXCEPTION 'phone_check_identity_invalid';
  END IF;
  IF p_auth_username IS NOT NULL OR p_auth_password IS NOT NULL THEN
    PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  ELSIF p_runtime_target <> 'server' OR p_claim_token IS NULL THEN
    RAISE EXCEPTION 'phone_check_auth_required';
  END IF;
  -- Preserve the existing scan lock order: staff, entitlement barrier, account.
  PERFORM 1 FROM public.org_staff s WHERE s.id=p_staff_id AND s.organization_id=p_organization_id
    AND s.is_active=true AND public.aka_agent_staff_time_allowed(s.id) FOR SHARE OF s;
  IF NOT FOUND THEN RAISE EXCEPTION 'phone_check_staff_invalid'; END IF;
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  SELECT * INTO v_capabilities FROM public.resolve_organization_zalo_account_capabilities(p_organization_id);
  IF p_consume OR p_auth_username IS NULL THEN
    SELECT * INTO v_account FROM public.auto_accounts a
      WHERE a.id=p_account_id AND a.staff_id=p_staff_id
        AND (a.organization_id IS NULL OR a.organization_id=p_organization_id) FOR UPDATE OF a;
  ELSE
    SELECT * INTO v_account FROM public.auto_accounts a
      WHERE a.id=p_account_id AND a.staff_id=p_staff_id
        AND (a.organization_id IS NULL OR a.organization_id=p_organization_id);
  END IF;
  IF NOT FOUND OR COALESCE(v_account.is_delete,false)
    OR lower(btrim(COALESCE(v_account.flatform_type,''))) <> 'zalo' THEN
    RAISE EXCEPTION 'phone_check_account_invalid';
  END IF;
  IF (p_runtime_target='server' AND (v_account.is_zalo_server IS NOT TRUE OR v_account.is_zalo_show_web IS TRUE
      OR NOT COALESCE(v_capabilities.qr_enabled,false) OR NOT COALESCE(v_capabilities.server_enabled,false)))
    OR (p_runtime_target='desktop' AND (v_account.is_zalo_server IS TRUE
      OR (v_account.is_zalo_show_web IS TRUE AND NOT COALESCE(v_capabilities.web_enabled,false))
      OR (v_account.is_zalo_show_web IS NOT TRUE AND NOT COALESCE(v_capabilities.qr_enabled,false)))) THEN
    RAISE EXCEPTION 'phone_check_runtime_not_owner';
  END IF;
  IF (p_consume OR p_auth_username IS NULL) AND (p_claim_token IS NULL
    OR v_account.runtime_operation_claim_token IS DISTINCT FROM p_claim_token
    OR v_account.status IS DISTINCT FROM 'đang chạy'
    OR v_account.is_active IS NOT TRUE OR v_account.login_status IS DISTINCT FROM 'đã đăng nhập') THEN
    RAISE EXCEPTION 'phone_check_claim_invalid';
  END IF;
  -- Compute after acquiring the row lock, including a wait across midnight.
  v_today := timezone('Asia/Ho_Chi_Minh',clock_timestamp())::date;
  IF (v_account.zalo_phone_check_usage->>'date')::date > v_today THEN
    RAISE EXCEPTION 'phone_check_usage_date_in_future';
  END IF;
  IF v_account.zalo_phone_check_usage->>'date' = v_today::text THEN
    v_count := (v_account.zalo_phone_check_usage->>'count')::integer;
  END IF;
  SELECT value INTO v_setting FROM public.auto_system_settings
    WHERE key='zalo.phone_check.daily_limit' AND is_active=true AND is_secret=false;
  IF v_setting ~ '^[1-9][0-9]{0,9}$' AND v_setting::numeric <= 2147483647 THEN
    v_limit := v_setting::integer;
  END IF;
  v_allowed := v_count < v_limit;
  IF p_consume AND v_allowed THEN
    v_count := v_count+1;
    UPDATE public.auto_accounts SET zalo_phone_check_usage=jsonb_build_object('date',v_today,'count',v_count)
      WHERE id=p_account_id;
  END IF;
  RETURN jsonb_build_object('allowed',v_allowed,'date',v_today,'count',v_count,'limit',v_limit,
    'remaining',greatest(0,v_limit-v_count),
    'resetAt',((v_today+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'));
END;
$function$

CREATE OR REPLACE FUNCTION public.append_auto_campaign_log(p_campaign_id bigint, p_staff_id bigint, p_log_line text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
 v_log text:=p_log_line;
 v_marker constant text:=' … [nội dung quá dài đã được rút gọn]';
BEGIN
 IF p_campaign_id IS NULL OR p_campaign_id<=0 THEN RAISE EXCEPTION 'Campaign ID must be a positive integer'; END IF;
 IF p_staff_id IS NULL OR p_staff_id<=0 THEN RAISE EXCEPTION 'Staff ID must be a positive integer'; END IF;
 IF nullif(btrim(coalesce(v_log,'')),'') IS NULL THEN RAISE EXCEPTION 'Campaign log line must not be empty'; END IF;
 IF char_length(v_log)>16000 THEN v_log:=left(v_log,16000-char_length(v_marker))||v_marker; END IF;
 -- All writers acquire this lock before identity allocation. A later cursor
 -- can therefore never jump over an earlier uncommitted append for this campaign.
 PERFORM pg_advisory_xact_lock(hashtextextended('auto_campaign_logs:'||p_campaign_id::text,0));
 IF NOT EXISTS (SELECT 1 FROM public.auto_campaigns c WHERE c.id=p_campaign_id AND c.staff_id=p_staff_id AND coalesce(c.is_delete,false)=false)
 THEN RAISE EXCEPTION 'Active campaign % was not found',p_campaign_id; END IF;
 INSERT INTO public.auto_campaign_logs(campaign_id,log) VALUES(p_campaign_id,v_log);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_campaign_zalo_realtime_group_event(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_group_id text, p_group_name text, p_trigger_type text, p_target_uid text, p_target_name text, p_event_time timestamp with time zone, p_schedule_at timestamp with time zone, p_raw_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(inserted boolean, event_id bigint, input_data_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id bigint;
  v_input_data_id bigint;
  v_organization_id bigint;
  v_capabilities record;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_target_uid text := btrim(COALESCE(p_target_uid, ''));
  v_target_name text := NULLIF(btrim(COALESCE(p_target_name, '')), '');
  v_group_id text := btrim(COALESCE(p_group_id, ''));
  v_group_name text := NULLIF(btrim(COALESCE(p_group_name, '')), '');
  v_schedule_at timestamptz := COALESCE(p_schedule_at, now());
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 THEN RAISE EXCEPTION 'campaign_id is required'; END IF;
  IF p_account_id IS NULL OR p_account_id <= 0 THEN RAISE EXCEPTION 'account_id is required'; END IF;
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN RAISE EXCEPTION 'staff_id is required'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN RAISE EXCEPTION 'runtime target must be desktop or server'; END IF;
  IF v_group_id = '' THEN RAISE EXCEPTION 'group_id is required'; END IF;
  IF v_target_uid = '' OR v_target_uid = '0' THEN RAISE EXCEPTION 'target_uid is required'; END IF;
  IF p_trigger_type NOT IN ('join', 'leave', 'interact') THEN RAISE EXCEPTION 'invalid trigger_type: %', p_trigger_type; END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RAISE EXCEPTION 'active staff % was not found', p_staff_id; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR (v_runtime_target = 'server'
      AND NOT COALESCE(v_capabilities.server_enabled, false))
  THEN RAISE EXCEPTION 'runtime_not_owner'; END IF;

  PERFORM 1
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.action_id = 'zalo_message_group_realtime'
    AND campaign.status IN ('chờ xử lý', 'đang chạy')
    AND COALESCE(campaign.is_delete, false) = false
  FOR SHARE OF campaign;
  IF NOT FOUND THEN RAISE EXCEPTION 'runtime_control_paused'; END IF;

  PERFORM 1
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND (
      (v_runtime_target = 'server' AND COALESCE(account.is_zalo_server, false) = true)
      OR (v_runtime_target = 'desktop' AND COALESCE(account.is_zalo_server, false) = false)
    )
    AND account.is_active = true
    AND account.status IN ('chờ xử lý', 'đang chạy')
    AND COALESCE(account.is_delete, false) = false
  FOR SHARE OF account;
  IF NOT FOUND THEN RAISE EXCEPTION 'runtime_control_paused'; END IF;

  INSERT INTO public.auto_campaign_zalo_realtime_group_events (
    campaign_id, account_id, group_id, group_name, trigger_type,
    target_uid, target_name, event_time, raw_payload
  ) VALUES (
    p_campaign_id, p_account_id, v_group_id, v_group_name, p_trigger_type,
    v_target_uid, v_target_name, COALESCE(p_event_time, now()), COALESCE(p_raw_payload, '{}'::jsonb)
  ) ON CONFLICT (campaign_id, target_uid) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT event.id, event.input_data_id INTO v_event_id, v_input_data_id
    FROM public.auto_campaign_zalo_realtime_group_events AS event
    WHERE event.campaign_id = p_campaign_id AND event.target_uid = v_target_uid;
    RETURN QUERY SELECT false, v_event_id, v_input_data_id;
    RETURN;
  END IF;

  INSERT INTO public.auto_campaign_input_data (
    campaign_id, input_id, name, uid, status, note, schedule
  ) VALUES (
    p_campaign_id, NULL, v_target_name, v_target_uid, 'chờ xử lý', '', v_schedule_at
  ) RETURNING id INTO v_input_data_id;

  UPDATE public.auto_campaign_zalo_realtime_group_events
  SET input_data_id = v_input_data_id, updated_at = now()
  WHERE id = v_event_id;
  UPDATE public.auto_campaigns
  SET schedule = v_schedule_at, updated_at = now()
  WHERE id = p_campaign_id AND account_id = p_account_id
    AND status IN ('chờ xử lý', 'đang chạy')
    AND (schedule IS NULL OR schedule < now() OR schedule > v_schedule_at);

  RETURN QUERY SELECT true, v_event_id, v_input_data_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_staff_zalo_runtime_mode(p_staff_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_mode record;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Staff ID must be a positive integer';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_profile AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id);

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Active staff % was not found', p_staff_id;
  END IF;

  SELECT * INTO v_mode
  FROM public.resolve_organization_zalo_runtime_mode(v_organization_id);

  RETURN jsonb_build_object(
    'staff_id', p_staff_id,
    'is_zalo_server', COALESCE(v_mode.is_zalo_server, false),
    'is_zalo_show_web', COALESCE(v_mode.web_enabled, false),
    'zalo_qr_enabled', COALESCE(v_mode.qr_enabled, false),
    'zalo_web_enabled', COALESCE(v_mode.web_enabled, false),
    'revision', COALESCE(v_mode.mode_revision, 'none:' || v_organization_id::text)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_auto_automation_enqueue_failures(p_staff_id bigint, p_organization_id bigint, p_worker_id text, p_limit integer DEFAULT 100, p_auth_username text DEFAULT NULL::text, p_auth_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_base jsonb;
  v_detail record;
  v_outcome jsonb;
  v_processed integer := 0;
  v_completed integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
BEGIN
  v_base := public.reconcile_auto_automation_enqueue_failures_v185_internal(
    p_staff_id, p_organization_id, p_worker_id, p_limit,
    p_auth_username, p_auth_password
  );

  FOR v_detail IN
    SELECT detail.id
    FROM public.auto_automation_detail AS detail
    WHERE detail.staff_id = p_staff_id AND detail.organization_id = p_organization_id
      AND detail.status = 'đã thêm'
      AND detail.target_data_group_id IS NOT NULL
      AND detail.target_data_group_member_id IS NULL
      AND COALESCE(detail.target_data_group_sync_status, 'pending') IN ('pending', 'failed')
    ORDER BY detail.processed_at, detail.id
    LIMIT v_limit
  LOOP
    v_processed := v_processed + 1;
    v_outcome := public.aka_agent_ingest_automation_data_group_result(
      p_staff_id, p_organization_id, v_detail.id
    );
    CASE v_outcome ->> 'code'
      WHEN 'completed' THEN v_completed := v_completed + 1;
      WHEN 'skipped' THEN v_skipped := v_skipped + 1;
      ELSE v_failed := v_failed + 1;
    END CASE;
  END LOOP;

  RETURN COALESCE(v_base, '{}'::jsonb) || jsonb_build_object(
    'data_group_processed', v_processed,
    'data_group_completed', v_completed,
    'data_group_skipped', v_skipped,
    'data_group_failed', v_failed
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.release_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Account and staff IDs must be positive integers'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = v_previous_status,
    runtime_operation_claim_token = NULL,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND account.status = 'đang chạy'
    AND account.runtime_operation_claim_token = p_claim_token;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF account;
  IF NOT FOUND THEN RETURN false; END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  -- Release is cleanup, not a new operation. Capability loss does not prevent
  -- either runtime from releasing its own subtype.
  IF (v_runtime_target = 'server' AND (v_is_web OR NOT v_is_server))
    OR (v_runtime_target = 'desktop' AND v_is_server)
  THEN RETURN false; END IF;

  UPDATE public.auto_accounts
  SET status = v_previous_status, updated_at = now()
  WHERE id = p_account_id AND status = 'đang chạy';
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_prepare_device_change(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username);
  IF NOT FOUND THEN RETURN jsonb_build_object('code', 'not_found'); END IF;
  IF NOT s.is_active THEN RETURN jsonb_build_object('code', 'inactive'); END IF;
